var LIBRARY = [
  { num:1, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Analyse contradictoire', en:'Adversarial analysis', ar:'التحليل المعاكس' },
    badge:{ fr:'🛡️ N°1', en:'🛡️ #1', ar:'🛡️ الأول' },
    desc:{ fr:'Force l\'IA à devenir analyste bear. Le prompt le plus important — à utiliser AVANT chaque achat. Technique du "role prompting" : attribuer un rôle à l\'IA change radicalement la qualité de la réponse.', en:'Forces the AI to become a bear analyst. The most important prompt — use it BEFORE every buy. "Role prompting" technique: assigning a role to the AI dramatically changes the quality of the response.', ar:'أجبر الذكاء الاصطناعي على لعب دور محلل هبوطي. أهم برومبت على الإطلاق — استخدمه قبل كل عملية شراء. تقنية "role prompting": إسناد دور للذكاء الاصطناعي يغيّر جذرياً جودة الإجابة.' },
    code:{ fr:'Je veux acheter [TICKER] à [PRIX]. Joue le rôle d\'un analyste bear agressif mandaté par un hedge fund short-seller. Donne-moi 7 raisons concrètes pour lesquelles ce trade pourrait échouer :\n— 2 risques macro (cycle, taux, géopolitique)\n— 2 risques sectoriels (concurrence, disruption, régulation)\n— 2 risques spécifiques au titre (valorisation, insider selling, qualité du bilan)\n— 1 risque que les bulls ignorent systématiquement\nPour chaque risque, quantifie l\'impact potentiel sur le cours (en %). Ne sois pas poli, sois honnête. Conclus par : "Si malgré tout ça vous achetez, votre stop doit être à [niveau]."', en:'I want to buy [TICKER] at [PRICE]. Play the role of an aggressive bear analyst hired by a short-selling hedge fund. Give me 7 concrete reasons why this trade could fail:\n— 2 macro risks (cycle, rates, geopolitics)\n— 2 sector risks (competition, disruption, regulation)\n— 2 stock-specific risks (valuation, insider selling, balance sheet quality)\n— 1 risk that bulls systematically ignore\nFor each risk, quantify the potential impact on the stock price (in %). Don\'t be polite, be honest. Conclude with: "If you still buy after all this, your stop should be at [level]."', ar:'أريد شراء [TICKER] بسعر [PRICE]. قم بدور محلل هبوطي عدواني مُكلَّف من صندوق تحوّط بائع على المكشوف. أعطني 7 أسباب ملموسة لاحتمال فشل هذه الصفقة:\n— خطران كليان (الدورة، الفائدة، الجيوسياسة)\n— خطران قطاعيان (المنافسة، التحوّل الرقمي، التنظيم)\n— خطران خاصان بالسهم (التقييم، بيع المطّلعين، جودة الميزانية)\n— خطر واحد يتجاهله المتفائلون دائماً\nلكل خطر، قدّر التأثير المحتمل على السعر (بالنسبة المئوية %). لا تكن مجاملاً، كن صادقاً. اختم بـ: "إذا أصررت على الشراء رغم كل ذلك، يجب أن يكون وقف الخسارة عند [المستوى]."' }
  },
  { num:2, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Qu\'est-ce que j\'ai oublié ?', en:'"What am I missing?"', ar:'ما الذي نسيته؟' },
    badge:{ fr:'🔍 Blind Spot', en:'🔍 Blind Spot', ar:'🔍 النقطة العمياء' },
    desc:{ fr:'Le "blind spot prompt" — la meilleure arme contre le biais de confirmation. À utiliser APRÈS chaque analyse, quand vous êtes convaincu de votre thèse. L\'IA excelle à trouver ce que vous ne cherchez pas.', en:'The "blind spot prompt" — the best weapon against confirmation bias. Use it AFTER every analysis, when you are convinced of your thesis. AI excels at finding what you are not looking for.', ar:'برومبت "النقطة العمياء" — أقوى سلاح ضد تحيّز التأكيد. استخدمه بعد كل تحليل، حين تكون مقتنعاً بأطروحتك. الذكاء الاصطناعي يتفوّق في إيجاد ما لا تبحث عنه.' },
    code:{ fr:'Je suis convaincu que [TICKER] va [monter/baisser] parce que [VOTRE THÈSE EN 2-3 PHRASES]. Maintenant, démolis ma thèse. Spécifiquement :\n1. Quel fait vérifiable contredit directement mon argument principal ?\n2. Quel concurrent ou substitut je sous-estime ?\n3. Quelle hypothèse implicite dans mon raisonnement pourrait être fausse ?\n4. Quel événement calendaire (earnings, expiry, unlock, macro) pourrait invalider ma thèse avant qu\'elle ne se réalise ?\n5. Si je me trompe, à quel prix je saurai que j\'ai tort ? (niveau technique d\'invalidation)\nNe me donne pas de réponse diplomatique. Si ma thèse est solide, dis-le — mais si elle a des trous, montre-les.', en:'I am convinced that [TICKER] will [go up/go down] because [YOUR THESIS IN 2-3 SENTENCES]. Now, tear my thesis apart. Specifically:\n1. What verifiable fact directly contradicts my main argument?\n2. What competitor or substitute am I underestimating?\n3. What implicit assumption in my reasoning could be wrong?\n4. What calendar event (earnings, expiry, unlock, macro) could invalidate my thesis before it plays out?\n5. If I am wrong, at what price will I know it? (technical invalidation level)\nDon\'t give me a diplomatic answer. If my thesis is solid, say so — but if it has holes, show them.', ar:'أنا مقتنع بأن [TICKER] سوف [يرتفع/ينخفض] لأن [أطروحتك في 2-3 جمل]. الآن، دمّر أطروحتي. تحديداً:\n1. ما الحقيقة القابلة للتحقق التي تناقض حجتي الرئيسية مباشرة؟\n2. ما المنافس أو البديل الذي أستخفّ به؟\n3. ما الافتراض الضمني في تحليلي الذي قد يكون خاطئاً؟\n4. ما الحدث المجدول (أرباح، انتهاء صلاحية، فتح قفل، ماكرو) الذي قد يُبطل أطروحتي قبل تحققها؟\n5. إذا كنت مخطئاً، عند أي سعر سأعلم أنني مخطئ؟ (مستوى الإبطال الفني)\nلا تعطني إجابة دبلوماسية. إذا كانت أطروحتي متينة، قُلها — لكن إذا فيها ثغرات، أظهرها.' }
  },
  { num:3, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Note d\'initiation sell-side', en:'Sell-side initiation note', ar:'مذكرة تغطية مؤسسية' },
    badge:{ fr:'🏦 Pro', en:'🏦 Pro', ar:'🏦 مؤسسي' },
    desc:{ fr:'Technique du "role prompting" poussée à l\'extrême : l\'IA rédige comme un analyste sell-side de Goldman/Morgan Stanley. Résultat : structure professionnelle, DCF, comps, catalyseurs datés.', en:'"Role prompting" taken to the extreme: the AI writes like a sell-side analyst at Goldman/Morgan Stanley. Result: professional structure, DCF, comps, dated catalysts.', ar:'تقنية "role prompting" في أقصى درجاتها: الذكاء الاصطناعي يكتب كمحلل sell-side في Goldman/Morgan Stanley. النتيجة: هيكل احترافي، DCF، مقارنات، محفّزات مؤرّخة.' },
    code:{ fr:'Tu es un analyste equity senior chez Goldman Sachs. Rédige une note d\'initiation de couverture sur [TICKER] au format institutionnel :\n\nEXECUTIVE SUMMARY (5 lignes max)\nRECOMMENDATION : Buy / Neutral / Sell — Price Target : $[X] (upside/downside %)\n\n1. INVESTMENT THESIS (3 bullets max)\n2. BUSINESS MODEL — Décompose le CA par segment, géographie, récurrence. MOAT : pricing power, switching costs, network effects ?\n3. FINANCIALS — Tableau : CA, EBITDA, BPA, marge nette, FCF yield sur 3 ans (historique + 2 ans forward). Mets en gras les inflexions.\n4. VALORISATION — DCF (WACC, terminal growth, fair value) + comparables (EV/EBITDA, P/E, PEG vs peers). Quel multiple le marché price-t-il ? Est-ce justifié ?\n5. CATALYSEURS — 3 événements datés qui pourraient faire bouger le titre (earnings, produit, macro, M&amp;A)\n6. RISQUES — Top 3 avec probabilité (haute/moyenne/basse) et impact ($)\n7. CONCLUSION — Conviction 1-10 et horizon recommandé', en:'You are a senior equity analyst at Goldman Sachs. Write an initiation-of-coverage note on [TICKER] in institutional format:\n\nEXECUTIVE SUMMARY (5 lines max)\nRECOMMENDATION: Buy / Neutral / Sell — Price Target: $[X] (upside/downside %)\n\n1. INVESTMENT THESIS (3 bullets max)\n2. BUSINESS MODEL — Break down revenue by segment, geography, recurring vs one-time. MOAT: pricing power, switching costs, network effects?\n3. FINANCIALS — Table: Revenue, EBITDA, EPS, net margin, FCF yield over 3 years (historical + 2 years forward). Bold the inflection points.\n4. VALUATION — DCF (WACC, terminal growth, fair value) + comparables (EV/EBITDA, P/E, PEG vs peers). What multiple is the market pricing in? Is it justified?\n5. CATALYSTS — 3 dated events that could move the stock (earnings, product, macro, M&amp;A)\n6. RISKS — Top 3 with probability (high/medium/low) and impact ($)\n7. CONCLUSION — Conviction 1-10 and recommended time horizon', ar:'أنت محلل أسهم أول في Goldman Sachs. اكتب مذكرة بدء تغطية على [TICKER] بالصيغة المؤسسية:\n\nEXECUTIVE SUMMARY (5 سطور كحد أقصى)\nRECOMMENDATION: Buy / Neutral / Sell — Price Target: $[X] (نسبة الصعود/الهبوط %)\n\n1. INVESTMENT THESIS (3 نقاط كحد أقصى)\n2. BUSINESS MODEL — حلّل الإيرادات حسب القطاع والجغرافيا والتكرار. الخندق: قوة التسعير، تكاليف التحويل، تأثيرات الشبكة؟\n3. FINANCIALS — جدول: الإيرادات، EBITDA، ربحية السهم، هامش صافي، عائد FCF على 3 سنوات (تاريخي + سنتين مستقبليتين). ضع بالخط العريض نقاط الانعطاف.\n4. VALORISATION — DCF (WACC، معدل النمو النهائي، القيمة العادلة) + المقارنات (EV/EBITDA، P/E، PEG مقابل الأقران). ما المضاعف الذي يسعّره السوق؟ هل هذا مبرّر؟\n5. CATALYSEURS — 3 أحداث مؤرّخة يمكن أن تحرّك السهم (أرباح، منتج، ماكرو، M&amp;A)\n6. RISQUES — أهم 3 مخاطر مع الاحتمال (عالٍ/متوسط/منخفض) والتأثير ($)\n7. CONCLUSION — درجة الاقتناع من 1 إلى 10 والأفق الموصى به' }
  },
  { num:4, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Morning brief personnalisé', en:'Personalized morning brief', ar:'ملخص صباحي مخصص' },
    badge:{ fr:'☀️ Matinal', en:'☀️ Morning', ar:'☀️ صباحي' },
    desc:{ fr:'Briefing matinal en 5 min centré sur VOS positions. Ne résume pas les news générales — concentre-toi sur ce qui impacte TON portefeuille. Idéal avec Perplexity ou Grok (accès web temps réel).', en:'5-minute morning briefing centered on YOUR positions. Don\'t summarize general news — focus on what impacts YOUR portfolio. Best with Perplexity or Grok (real-time web access).', ar:'إحاطة صباحية في 5 دقائق تركّز على مراكزك. لا تلخّص الأخبار العامة — ركّز على ما يؤثر على محفظتك. مثالي مع Perplexity أو Grok (وصول للويب المباشر).' },
    code:{ fr:'Mon portefeuille : [LISTE POSITIONS + % ALLOCATION]. Budget cash dispo : [MONTANT].\n\nRédige un briefing matinal actionnable en 5 sections :\n1. ALERTES — Lesquelles de mes positions ont bougé de &gt;2% overnight ou pre-market ? Pourquoi ?\n2. ACTUALITÉS — Uniquement les news qui impactent DIRECTEMENT une de mes positions (earnings, upgrade/downgrade, M&amp;A, FDA, contrat)\n3. CALENDRIER — Événements du jour/semaine qui concernent mes positions (ex-div, earnings, macro clé)\n4. NIVEAUX — Pour chaque position : support/résistance le plus proche, RSI actuel, distance au stop recommandé\n5. ACTION — Résumé en 3 mots par position : RIEN / SURVEILLER / RENFORCER / ALLÉGER / COUPER. Justifie chaque "COUPER" ou "RENFORCER".\n\nFormat : bulletpoints, zéro blabla, priorité par urgence.', en:'My portfolio: [LIST OF POSITIONS + % ALLOCATION]. Available cash: [AMOUNT].\n\nWrite an actionable morning briefing in 5 sections:\n1. ALERTS — Which of my positions moved &gt;2% overnight or pre-market? Why?\n2. NEWS — Only news that DIRECTLY impacts one of my positions (earnings, upgrade/downgrade, M&amp;A, FDA, contract)\n3. CALENDAR — Today\'s/this week\'s events affecting my positions (ex-div, earnings, key macro)\n4. LEVELS — For each position: nearest support/resistance, current RSI, distance to recommended stop\n5. ACTION — Summary in 3 words per position: HOLD / WATCH / ADD / TRIM / CUT. Justify every "CUT" or "ADD".\n\nFormat: bullet points, zero fluff, prioritized by urgency.', ar:'محفظتي: [قائمة المراكز + نسبة التخصيص %]. السيولة المتاحة: [المبلغ].\n\nاكتب إحاطة صباحية قابلة للتنفيذ في 5 أقسام:\n1. تنبيهات — أي من مراكزي تحرّك بأكثر من 2% خلال الليل أو ما قبل السوق؟ لماذا؟\n2. أخبار — فقط الأخبار التي تؤثر مباشرة على إحدى مراكزي (أرباح، ترقية/تخفيض، M&amp;A، FDA، عقد)\n3. تقويم — أحداث اليوم/الأسبوع التي تخص مراكزي (تاريخ استحقاق أرباح، أرباح فصلية، بيانات كلية مفتاحية)\n4. مستويات — لكل مركز: أقرب دعم/مقاومة، RSI الحالي، المسافة من وقف الخسارة الموصى به\n5. إجراء — ملخص من 3 كلمات لكل مركز: لا شيء / مراقبة / تعزيز / تخفيف / قطع. برّر كل "قطع" أو "تعزيز".\n\nالتنسيق: نقاط مختصرة، بدون ثرثرة، الأولوية حسب الإلحاح.' }
  },
  { num:5, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Screening multi-critères', en:'Multi-criteria screening', ar:'فرز متعدد المعايير' },
    badge:{ fr:'🎯 Screener', en:'🎯 Screener', ar:'🎯 فلتر' },
    desc:{ fr:'Filtre quantitatif strict avec seuils précis. L\'IA ne peut pas inventer des chiffres si vous imposez un format tableau. Astuce : demander "élargis aux secteurs adjacents" pour ne pas rater des opportunités.', en:'Strict quantitative filter with precise thresholds. The AI cannot make up numbers when you enforce a table format. Tip: asking "expand to adjacent sectors" prevents you from missing opportunities.', ar:'فلتر كمّي صارم بعتبات محددة. الذكاء الاصطناعي لا يستطيع اختلاق أرقام إذا فرضت تنسيق جدول. نصيحة: اطلب "التوسع للقطاعات المجاورة" حتى لا تفوّتك فرص.' },
    code:{ fr:'Trouve-moi 10 actions qui passent TOUS ces filtres simultanément :\n— Secteur : [SECTEUR ou "tous secteurs"]\n— P/E forward &lt; 20\n— Croissance CA &gt; 10%/an sur 3 ans\n— ROE &gt; 15%\n— Dette nette / EBITDA &lt; 2\n— Free Cash Flow positif\n— Market cap &gt; $1B (pas de micro-caps)\n\nPrésente les résultats dans un TABLEAU avec colonnes : Ticker | Secteur | P/E fwd | Croissance CA 3Y | ROE | Dette/EBITDA | FCF Yield | Risque #1.\nTrie par ROE décroissant. Pour chaque ligne, le "Risque #1" doit être spécifique (pas générique).\nBonus : ajoute 3 candidats de secteurs adjacents que je n\'aurais pas cherchés.', en:'Find me 10 stocks that pass ALL of these filters simultaneously:\n— Sector: [SECTOR or "all sectors"]\n— Forward P/E &lt; 20\n— Revenue growth &gt; 10%/year over 3 years\n— ROE &gt; 15%\n— Net debt / EBITDA &lt; 2\n— Free Cash Flow positive\n— Market cap &gt; $1B (no micro-caps)\n\nPresent results in a TABLE with columns: Ticker | Sector | Fwd P/E | 3Y Revenue Growth | ROE | Debt/EBITDA | FCF Yield | Risk #1.\nSort by ROE descending. For each row, "Risk #1" must be specific (not generic).\nBonus: add 3 candidates from adjacent sectors I would not have searched.', ar:'ابحث لي عن 10 أسهم تجتاز جميع هذه الفلاتر في آن واحد:\n— القطاع: [SECTOR أو "جميع القطاعات"]\n— P/E forward &lt; 20\n— نمو الإيرادات &gt; 10%/سنة على 3 سنوات\n— ROE &gt; 15%\n— صافي الدين / EBITDA &lt; 2\n— التدفقات النقدية الحرة إيجابية\n— القيمة السوقية &gt; $1B (بدون micro-caps)\n\nقدّم النتائج في جدول بأعمدة: Ticker | القطاع | P/E fwd | نمو الإيرادات 3 سنوات | ROE | الدين/EBITDA | عائد FCF | الخطر الأول.\nرتّب حسب ROE تنازلياً. لكل سطر، "الخطر الأول" يجب أن يكون محدداً (وليس عاماً).\nإضافة: أضف 3 مرشحين من قطاعات مجاورة ما كنت لأبحث فيها.' }
  },
  { num:6, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Comparaison peer-group', en:'Peer-group comparison', ar:'مقارنة مجموعة الأقران' },
    badge:{ fr:'⚖️ Versus', en:'⚖️ Versus', ar:'⚖️ مقارنة' },
    desc:{ fr:'Comparaison structurée en tableau — force l\'IA à être factuelle et comparable. Le format tableau empêche les réponses vagues.', en:'Structured table comparison — forces the AI to be factual and comparable. The table format prevents vague answers.', ar:'مقارنة مهيكلة في جدول — تجبر الذكاء الاصطناعي على أن يكون واقعياً وقابلاً للمقارنة. تنسيق الجدول يمنع الإجابات الغامضة.' },
    code:{ fr:'Compare [TICKER A] vs [TICKER B] vs [TICKER C] dans un tableau structuré :\n\nTABLEAU 1 — VALORISATION :\nTicker | P/E fwd | EV/EBITDA | PEG | P/FCF | Price/Sales\n\nTABLEAU 2 — CROISSANCE :\nTicker | CA 1Y% | CA 3Y CAGR | BPA 1Y% | Guidance vs consensus\n\nTABLEAU 3 — QUALITÉ :\nTicker | Marge nette | ROE | ROIC | Dette/EBITDA | FCF conversion\n\nTABLEAU 4 — MOMENTUM :\nTicker | Perf 3M | Perf 6M | RSI 14 | Distance EMA200 | Insider buying\n\nCLASSEMENT FINAL : Attribue un score /100 à chaque ticker (pondération : 30% qualité, 25% valorisation, 25% croissance, 20% momentum). Conclus par : "Si je ne devais en garder qu\'un, ce serait [X] parce que [raison en 1 phrase]."\nMentionne 1-2 concurrents que j\'ai oubliés dans la comparaison.', en:'Compare [TICKER A] vs [TICKER B] vs [TICKER C] in a structured table:\n\nTABLE 1 — VALUATION:\nTicker | Fwd P/E | EV/EBITDA | PEG | P/FCF | Price/Sales\n\nTABLE 2 — GROWTH:\nTicker | 1Y Revenue % | 3Y Revenue CAGR | 1Y EPS % | Guidance vs consensus\n\nTABLE 3 — QUALITY:\nTicker | Net margin | ROE | ROIC | Debt/EBITDA | FCF conversion\n\nTABLE 4 — MOMENTUM:\nTicker | 3M Perf | 6M Perf | RSI 14 | Distance to EMA200 | Insider buying\n\nFINAL RANKING: Assign a score /100 to each ticker (weighting: 30% quality, 25% valuation, 25% growth, 20% momentum). Conclude with: "If I could only keep one, it would be [X] because [reason in 1 sentence]."\nMention 1-2 competitors I may have missed in the comparison.', ar:'قارن [TICKER A] مقابل [TICKER B] مقابل [TICKER C] في جدول مهيكل:\n\nالجدول 1 — التقييم:\nTicker | P/E fwd | EV/EBITDA | PEG | P/FCF | Price/Sales\n\nالجدول 2 — النمو:\nTicker | نمو الإيرادات سنة | CAGR إيرادات 3 سنوات | نمو ربحية السهم سنة | التوجيهات مقابل الإجماع\n\nالجدول 3 — الجودة:\nTicker | هامش صافي | ROE | ROIC | الدين/EBITDA | تحويل FCF\n\nالجدول 4 — الزخم:\nTicker | أداء 3 أشهر | أداء 6 أشهر | RSI 14 | المسافة من EMA200 | شراء المطّلعين\n\nالترتيب النهائي: امنح درجة من 100 لكل رمز (الأوزان: 30% جودة، 25% تقييم، 25% نمو، 20% زخم). اختم بـ: "لو كان عليّ الاحتفاظ بواحد فقط، سيكون [X] لأن [السبب في جملة واحدة]."\nاذكر 1-2 منافسين نسيتهم في المقارنة.' }
  },
  { num:7, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Débrief earnings en 5 min', en:'Earnings debrief in 5 min', ar:'تحليل الأرباح في 5 دقائق' },
    badge:{ fr:'📊 Earnings', en:'📊 Earnings', ar:'📊 أرباح' },
    desc:{ fr:'Décryptage des résultats trimestriels avec ce que le marché a vraiment retenu. Astuce : demander le "sentiment du management" force l\'IA à analyser le ton du call, pas juste les chiffres.', en:'Quarterly results breakdown focusing on what the market actually noticed. Tip: asking for "management sentiment" forces the AI to analyze the tone of the call, not just the numbers.', ar:'تحليل النتائج الفصلية مع ما استوعبه السوق فعلاً. نصيحة: طلب "معنويات الإدارة" يجبر الذكاء الاصطناعي على تحليل نبرة المكالمة، وليس الأرقام فحسب.' },
    code:{ fr:'[TICKER] vient de publier ses résultats du [Q1/Q2/Q3/Q4 ANNÉE]. Analyse en 5 points :\n\n1. BEAT OR MISS — EPS : réalisé vs consensus vs whisper. CA : réalisé vs consensus. Marges : expansion ou contraction ? (donne les % exacts)\n2. GUIDANCE — Le management a-t-il relevé, maintenu ou abaissé les prévisions ? Sur quel segment ? C\'est ÇA que le marché regarde, pas le trimestre passé.\n3. CE QUE LE MARCHÉ A RETENU — Pourquoi le titre a-t-il bougé de [X%] after-hours ? Quel élément spécifique du call a surpris ?\n4. SENTIMENT MANAGEMENT — Score 1-10. Étaient-ils confiants ou prudents ? Y a-t-il des formulations comme "challenging environment", "cautious optimism" qui signalent un virage ?\n5. TRADE — Maintenant que les résultats sont sortis : renforcer, conserver ou couper ? À quel prix l\'acheter en pullback ?', en:'[TICKER] just reported [Q1/Q2/Q3/Q4 YEAR] results. Analyze in 5 points:\n\n1. BEAT OR MISS — EPS: actual vs consensus vs whisper. Revenue: actual vs consensus. Margins: expansion or contraction? (give exact %)\n2. GUIDANCE — Did management raise, maintain or lower forecasts? On which segment? THIS is what the market watches, not last quarter.\n3. WHAT THE MARKET NOTICED — Why did the stock move [X%] after-hours? What specific element from the call surprised the market?\n4. MANAGEMENT SENTIMENT — Score 1-10. Were they confident or cautious? Are there phrases like "challenging environment", "cautious optimism" that signal a shift?\n5. TRADE — Now that results are out: add, hold or cut? At what price to buy on a pullback?', ar:'[TICKER] نشر للتو نتائج [Q1/Q2/Q3/Q4 YEAR]. حلّل في 5 نقاط:\n\n1. تفوّق أم إخفاق — EPS: الفعلي مقابل الإجماع مقابل whisper. الإيرادات: الفعلي مقابل الإجماع. الهوامش: توسّع أم تقلّص؟ (أعطِ النسب الدقيقة %)\n2. التوجيهات — هل رفعت الإدارة أو حافظت أو خفّضت التوقعات؟ على أي قطاع؟ هذا ما ينظر إليه السوق، وليس الربع الماضي.\n3. ما الذي استوعبه السوق — لماذا تحرّك السهم بنسبة [X%] بعد الإغلاق؟ ما العنصر المحدد في المكالمة الذي فاجأ؟\n4. معنويات الإدارة — درجة من 1 إلى 10. هل كانوا واثقين أم حذرين؟ هل هناك عبارات مثل "challenging environment"، "cautious optimism" تشير إلى تحوّل؟\n5. الصفقة — الآن بعد صدور النتائج: تعزيز، احتفاظ أم قطع؟ بأي سعر الشراء عند التراجع؟' }
  },
  { num:8, cat:'portfolio', numBg:'#f5f3ff', numColor:'#7c3aed', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Audit de portefeuille', en:'Portfolio audit', ar:'تدقيق المحفظة' },
    badge:{ fr:'🔬 Audit', en:'🔬 Audit', ar:'🔬 تدقيق' },
    desc:{ fr:'Diagnostic complet avec seuils d\'alerte quantifiés. Règle clé : une position &gt;30% du portefeuille = signal d\'alerte concentration, quelle que soit la conviction.', en:'Full diagnostic with quantified alert thresholds. Key rule: any position &gt;30% of the portfolio = concentration alert, regardless of conviction.', ar:'تشخيص شامل مع عتبات تنبيه كمّية. القاعدة الأساسية: أي مركز يتجاوز 30% من المحفظة = تنبيه تركيز، مهما كانت درجة الاقتناع.' },
    code:{ fr:'Voici mon portefeuille : [LISTE POSITIONS + % ALLOCATION + PRIX D\'ENTRÉE].\n\nAudite-le comme un risk manager de fonds institutionnel :\n1. CONCENTRATION — Toute position &gt;30% = ALERTE ROUGE. Toute position &gt;20% = AVERTISSEMENT. Concentration sectorielle et géographique.\n2. CORRÉLATIONS — Quelles positions bougeraient ensemble en cas de krach ? Estime la corrélation par paire (faible/moyenne/forte).\n3. FACTEURS — Mon portefeuille est-il en réalité un pari sur un seul facteur (growth, momentum, taux) déguisé en diversification ?\n4. STRESS TEST — Estime la perte en % si : a) S&amp;P 500 -20%, b) Taux 10Y +100bps, c) Récession -30% earnings\n5. TROUS — Que manque-t-il ? (géographie, secteur, hedge, décorrélants comme or/TLT/BTC)\n6. VERDICT — Score diversification /10. Top 3 actions à faire dans les 30 prochains jours pour améliorer le risk/reward. Sois brutal.', en:'Here is my portfolio: [LIST OF POSITIONS + % ALLOCATION + ENTRY PRICE].\n\nAudit it like an institutional fund risk manager:\n1. CONCENTRATION — Any position &gt;30% = RED ALERT. Any position &gt;20% = WARNING. Sector and geographic concentration.\n2. CORRELATIONS — Which positions would move together in a crash? Estimate pairwise correlation (low/medium/high).\n3. FACTORS — Is my portfolio actually a disguised bet on a single factor (growth, momentum, rates)?\n4. STRESS TEST — Estimate the loss in % if: a) S&amp;P 500 -20%, b) 10Y yield +100bps, c) Recession -30% earnings\n5. GAPS — What is missing? (geography, sector, hedge, decorrelators like gold/TLT/BTC)\n6. VERDICT — Diversification score /10. Top 3 actions to take in the next 30 days to improve risk/reward. Be brutal.', ar:'هذه محفظتي: [قائمة المراكز + نسبة التخصيص % + سعر الدخول].\n\nدقّقها كمدير مخاطر في صندوق مؤسسي:\n1. التركيز — أي مركز يتجاوز 30% = تنبيه أحمر. أي مركز يتجاوز 20% = تحذير. التركيز القطاعي والجغرافي.\n2. الارتباطات — أي المراكز ستتحرك معاً في حالة انهيار؟ قدّر الارتباط لكل زوج (ضعيف/متوسط/قوي).\n3. العوامل — هل محفظتي في الحقيقة رهان على عامل واحد (نمو، زخم، فائدة) متنكّر في هيئة تنويع؟\n4. اختبار الإجهاد — قدّر الخسارة بالنسبة المئوية إذا: أ) S&amp;P 500 ينخفض 20%، ب) عائد 10 سنوات يرتفع 100 نقطة أساس، ج) ركود مع انخفاض الأرباح 30%\n5. الثغرات — ما الذي ينقص؟ (جغرافيا، قطاعات، تحوّط، أصول غير مترابطة كالذهب/TLT/BTC)\n6. الحكم — درجة التنويع من 10. أهم 3 إجراءات يجب اتخاذها خلال 30 يوماً لتحسين المخاطر/العائد. كن صريحاً.' }
  },
  { num:9, cat:'portfolio', numBg:'#f5f3ff', numColor:'#7c3aed', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Stress-test 4 scénarios', en:'Stress-test 4 scenarios', ar:'اختبار الإجهاد 4 سيناريوهات' },
    badge:{ fr:'💥 Crash Test', en:'💥 Crash Test', ar:'💥 اختبار' },
    desc:{ fr:'Simulation de 4 crises sur votre portefeuille avec hedge recommandé. Le format tableau force l\'IA à chiffrer chaque impact au lieu de rester vague.', en:'Simulates 4 crises on your portfolio with recommended hedges. The table format forces the AI to quantify each impact instead of staying vague.', ar:'محاكاة 4 أزمات على محفظتك مع التحوّط الموصى به. تنسيق الجدول يجبر الذكاء الاصطناعي على تقدير كل تأثير بالأرقام بدلاً من البقاء غامضاً.' },
    code:{ fr:'Mon portefeuille : [LISTE POSITIONS + % ALLOCATION].\n\nSimule l\'impact de 4 scénarios de crise dans un TABLEAU :\n\n| Scénario | Description | Impact portefeuille | Position la + vulnérable | Hedge recommandé |\n|----------|------------|-------------------|------------------------|-----------------|\n| 1. Récession | S&amp;P -30%, spreads +300bps | -X% | [TICKER] | [HEDGE] |\n| 2. Inflation | CPI &gt;6%, Fed hike +200bps | -X% | [TICKER] | [HEDGE] |\n| 3. Géopolitique | Crise Taiwan, pétrole $150 | -X% | [TICKER] | [HEDGE] |\n| 4. Tech krach | Nasdaq -40%, AI bubble burst | -X% | [TICKER] | [HEDGE] |\n\nPour chaque scénario, utilise les betas historiques et les corrélations passées (pas des estimations au doigt mouillé).\nCONCLUSION : Quel est le pire scénario pour MON portefeuille spécifiquement ? Quel hedge coûte le moins cher par rapport à la protection apportée ?', en:'My portfolio: [LIST OF POSITIONS + % ALLOCATION].\n\nSimulate the impact of 4 crisis scenarios in a TABLE:\n\n| Scenario | Description | Portfolio impact | Most vulnerable position | Recommended hedge |\n|----------|------------|-----------------|------------------------|------------------|\n| 1. Recession | S&amp;P -30%, spreads +300bps | -X% | [TICKER] | [HEDGE] |\n| 2. Inflation | CPI &gt;6%, Fed hike +200bps | -X% | [TICKER] | [HEDGE] |\n| 3. Geopolitical | Taiwan crisis, oil $150 | -X% | [TICKER] | [HEDGE] |\n| 4. Tech crash | Nasdaq -40%, AI bubble burst | -X% | [TICKER] | [HEDGE] |\n\nFor each scenario, use historical betas and past correlations (not back-of-the-envelope estimates).\nCONCLUSION: What is the worst-case scenario for MY specific portfolio? Which hedge costs the least relative to the protection it provides?', ar:'محفظتي: [قائمة المراكز + نسبة التخصيص %].\n\nحاكِ تأثير 4 سيناريوهات أزمة في جدول:\n\n| السيناريو | الوصف | التأثير على المحفظة | المركز الأكثر عرضة | التحوّط الموصى به |\n|----------|-------|-------------------|-------------------|-----------------|\n| 1. ركود | S&amp;P ينخفض 30%، فروقات الائتمان +300 نقطة أساس | -X% | [TICKER] | [HEDGE] |\n| 2. تضخم | CPI يتجاوز 6%، Fed يرفع +200 نقطة أساس | -X% | [TICKER] | [HEDGE] |\n| 3. جيوسياسي | أزمة تايوان، نفط $150 | -X% | [TICKER] | [HEDGE] |\n| 4. انهيار تقني | Nasdaq ينخفض 40%، انفجار فقاعة الذكاء الاصطناعي | -X% | [TICKER] | [HEDGE] |\n\nلكل سيناريو، استخدم معاملات بيتا التاريخية والارتباطات الفعلية (وليس تقديرات عشوائية).\nالخلاصة: ما أسوأ سيناريو لمحفظتي تحديداً؟ أي تحوّط يكلّف الأقل مقارنة بالحماية التي يوفرها؟' }
  },
  { num:10, cat:'crypto', numBg:'#fff7ed', numColor:'#ea580c', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Due diligence on-chain', en:'On-chain due diligence', ar:'العناية الواجبة على السلسلة' },
    badge:{ fr:'⛓️ On-Chain', en:'⛓️ On-Chain', ar:'⛓️ أون تشين' },
    desc:{ fr:'Checklist quantitative pour analyser un token AVANT d\'acheter. Les seuils sont calibrés : TVL &lt;$10M = micro-cap risqué, top 10 wallets &gt;40% = concentration toxique. Chiffres issus du guide spéculateur.', en:'Quantitative checklist to analyze a token BEFORE buying. Calibrated thresholds: TVL &lt;$10M = risky micro-cap, top 10 wallets &gt;40% = toxic concentration. Figures from Le Guide du Spéculateur.', ar:'قائمة تحقق كمّية لتحليل أي توكن قبل الشراء. العتبات مُعايَرة: TVL أقل من $10M = micro-cap خطير، أكبر 10 محافظ تتجاوز 40% = تركّز سام. الأرقام مستمدة من دليل المضارب.' },
    code:{ fr:'Due diligence complète sur [TOKEN/PROTOCOLE] — réponds avec des CHIFFRES, pas des opinions :\n\n1. TOKENOMICS — Supply max | Circulating | Inflation annuelle % | Prochain unlock : date + montant + % du circulating\n2. ON-CHAIN — TVL ($) | TVL &lt;$10M = RED FLAG | Active addresses 30J | Tendance (croissant/décroissant) | Volume DEX vs CEX ratio\n3. CONCENTRATION — Top 10 wallets = quel % de la supply ? (&gt;40% = RED FLAG) | Le fondateur/treasury détient combien % ?\n4. SMART CONTRACT — Audité par qui ? | Bugs/exploits passés ? | Contrat upgradeable ou immutable ? | Renounced ?\n5. FONDAMENTAUX — Revenu du protocole (fees 30J) | P/S ratio on-chain | Compétiteurs directs et leurs métriques\n6. CATALYSEURS — 3 événements datés (upgrade, listing, partnership, unlock)\n\nCHECKLIST RED FLAGS (réponds OUI/NON) :\n☐ Top 10 wallets &gt; 40% supply | ☐ TVL &lt; $10M | ☐ Pas d\'audit | ☐ Équipe anonyme | ☐ Token unlock &gt;10% dans 30J | ☐ Volume en baisse 3 mois consécutifs\nNombre de red flags : X/6 → Score confiance : [A/B/C/D]', en:'Full due diligence on [TOKEN/PROTOCOL] — answer with NUMBERS, not opinions:\n\n1. TOKENOMICS — Max supply | Circulating | Annual inflation % | Next unlock: date + amount + % of circulating\n2. ON-CHAIN — TVL ($) | TVL &lt;$10M = RED FLAG | Active addresses 30D | Trend (growing/declining) | DEX vs CEX volume ratio\n3. CONCENTRATION — Top 10 wallets = what % of supply? (&gt;40% = RED FLAG) | How much does the founder/treasury hold?\n4. SMART CONTRACT — Audited by whom? | Past bugs/exploits? | Contract upgradeable or immutable? | Renounced?\n5. FUNDAMENTALS — Protocol revenue (fees 30D) | On-chain P/S ratio | Direct competitors and their metrics\n6. CATALYSTS — 3 dated events (upgrade, listing, partnership, unlock)\n\nRED FLAGS CHECKLIST (answer YES/NO):\n☐ Top 10 wallets &gt; 40% supply | ☐ TVL &lt; $10M | ☐ No audit | ☐ Anonymous team | ☐ Token unlock &gt;10% within 30D | ☐ Volume declining 3 consecutive months\nNumber of red flags: X/6 → Confidence score: [A/B/C/D]', ar:'عناية واجبة كاملة على [TOKEN/PROTOCOL] — أجب بالأرقام وليس بالآراء:\n\n1. TOKENOMICS — العرض الأقصى | المتداول | التضخم السنوي % | فتح القفل التالي: التاريخ + المبلغ + النسبة من المتداول %\n2. ON-CHAIN — TVL ($) | TVL أقل من $10M = علامة حمراء | العناوين النشطة 30 يوماً | الاتجاه (صعودي/هبوطي) | نسبة حجم DEX مقابل CEX\n3. التركيز — أكبر 10 محافظ = أي نسبة من العرض؟ (أكثر من 40% = علامة حمراء) | المؤسس/الخزينة كم يملكون %؟\n4. SMART CONTRACT — من أجرى التدقيق؟ | ثغرات/اختراقات سابقة؟ | العقد قابل للترقية أم ثابت؟ | تم التخلي عنه (Renounced)؟\n5. الأساسيات — إيرادات البروتوكول (الرسوم 30 يوماً) | نسبة P/S على السلسلة | المنافسون المباشرون ومقاييسهم\n6. المحفّزات — 3 أحداث مؤرّخة (ترقية، إدراج، شراكة، فتح قفل)\n\nقائمة علامات حمراء (أجب بنعم/لا):\n&#9744; أكبر 10 محافظ تتجاوز 40% من العرض | &#9744; TVL أقل من $10M | &#9744; لا يوجد تدقيق | &#9744; فريق مجهول | &#9744; فتح قفل يتجاوز 10% خلال 30 يوماً | &#9744; الحجم في انخفاض 3 أشهر متتالية\nعدد العلامات الحمراء: X/6 ← درجة الثقة: [A/B/C/D]' }
  },
  { num:11, cat:'crypto', numBg:'#fff7ed', numColor:'#ea580c', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Rug pull detector', en:'Rug pull detector', ar:'كاشف الاحتيال' },
    badge:{ fr:'🚨 Danger', en:'🚨 Danger', ar:'🚨 خطر' },
    desc:{ fr:'7 questions binaires OUI/NON pour évaluer un token suspect. Score &ge;4 = ne pas toucher. Ce scoring vient du Guide du Spéculateur et a filtré des dizaines de rug pulls.', en:'7 binary YES/NO questions to evaluate a suspicious token. Score ≥4 = do not touch. This scoring comes from Le Guide du Spéculateur and has filtered out dozens of rug pulls.', ar:'7 أسئلة ثنائية نعم/لا لتقييم توكن مشبوه. الدرجة 4 فما فوق = لا تقترب. نظام التقييم مستمد من دليل المضارب وقد صفّى عشرات حالات rug pull.' },
    code:{ fr:'[TOKEN] buzze sur les réseaux et je suis tenté. Avant que je fasse une erreur, réponds à ces 7 questions par OUI ou NON :\n\n1. L\'équipe est-elle anonyme (pas de LinkedIn, pas de track record vérifiable) ?\n2. Le contrat est-il non-audité OU audité par un auditeur inconnu ?\n3. La liquidité LP est-elle non-lockée ou lockée &lt;6 mois ?\n4. Les top 5 wallets détiennent-ils &gt;50% de la supply ?\n5. Le token existe-t-il depuis &lt;30 jours ?\n6. Le volume est-il concentré à &gt;80% sur un seul DEX/CEX ?\n7. Y a-t-il des fonctions suspectes dans le contrat (mint illimité, pause trading, blacklist, hidden fee) ?\n\nSCORE : Nombre de OUI / 7\n— 0-1 : Risque acceptable → sizing max 2% du portefeuille\n— 2-3 : Risque élevé → sizing max 0.5%, stop mental -30%\n— 4+ : DANGER → Ne pas toucher. Cherche la prochaine opportunité.\n\nSi le score est &le;3, donne quand même : entry, stop (-30%), TP (+100% minimum pour justifier le risque), et sizing en % du portefeuille.', en:'[TOKEN] is buzzing on social media and I am tempted. Before I make a mistake, answer these 7 questions with YES or NO:\n\n1. Is the team anonymous (no LinkedIn, no verifiable track record)?\n2. Is the contract unaudited OR audited by an unknown auditor?\n3. Is the LP liquidity unlocked or locked for &lt;6 months?\n4. Do the top 5 wallets hold &gt;50% of the supply?\n5. Has the token existed for &lt;30 days?\n6. Is &gt;80% of the volume concentrated on a single DEX/CEX?\n7. Are there suspicious functions in the contract (unlimited mint, pause trading, blacklist, hidden fee)?\n\nSCORE: Number of YES / 7\n— 0-1: Acceptable risk → max sizing 2% of portfolio\n— 2-3: High risk → max sizing 0.5%, mental stop -30%\n— 4+: DANGER → Do not touch. Look for the next opportunity.\n\nIf score ≤3: still provide entry, stop (-30%), TP (+100% minimum to justify the risk), and sizing as % of portfolio.', ar:'[TOKEN] يثير ضجة على الشبكات الاجتماعية وأنا مُغرى. قبل أن أرتكب خطأ، أجب بنعم أو لا عن هذه الأسئلة السبعة:\n\n1. هل الفريق مجهول الهوية (لا LinkedIn، لا سجل إنجازات قابل للتحقق)؟\n2. هل العقد غير مُدقَّق أو مُدقَّق من جهة غير معروفة؟\n3. هل سيولة LP غير مقفلة أو مقفلة لأقل من 6 أشهر؟\n4. هل يملك أكبر 5 محافظ أكثر من 50% من العرض؟\n5. هل عمر التوكن أقل من 30 يوماً؟\n6. هل الحجم مركّز بأكثر من 80% على DEX/CEX واحد؟\n7. هل توجد وظائف مشبوهة في العقد (سك غير محدود، إيقاف التداول، قائمة سوداء، رسوم مخفية)؟\n\nالدرجة: عدد نعم / 7\n— 0-1: خطر مقبول ← حجم أقصى 2% من المحفظة\n— 2-3: خطر مرتفع ← حجم أقصى 0.5%، وقف خسارة ذهني -30%\n— 4+: خطر ← لا تلمسه. ابحث عن الفرصة التالية.\n\nإذا كانت الدرجة 3 أو أقل: أعطِ مع ذلك: entry، stop (-30%)، TP (+100% كحد أدنى لتبرير المخاطرة)، والحجم كنسبة من المحفظة.' }
  },
  { num:12, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Score short squeeze', en:'Short squeeze score', ar:'درجة الضغط على البائعين' },
    badge:{ fr:'🔥 Squeeze', en:'🔥 Squeeze', ar:'🔥 ضغط' },
    desc:{ fr:'8 critères binaires avec seuils quantitatifs calibrés (SI% &gt;20%, DTC &gt;5 jours, CTB &gt;50%). Score issu du Guide du Spéculateur — utilisé dans le scanner quotidien DailyTickers.', en:'8 binary criteria with calibrated quantitative thresholds (SI% &gt;20%, DTC &gt;5 days, CTB &gt;50%). Score from Le Guide du Spéculateur — used in the DailyTickers daily scanner.', ar:'8 معايير ثنائية بعتبات كمّية مُعايَرة (SI% أكثر من 20%، DTC أكثر من 5 أيام، CTB أكثر من 50%). الدرجة مستمدة من دليل المضارب — تُستخدم في الماسح اليومي لـ DailyTickers.' },
    code:{ fr:'Évalue le potentiel de short squeeze de [TICKER]. Réponds par OUI/NON à chaque critère (avec la donnée chiffrée) :\n\n1. Short Interest &gt; 20% du float ? (SI% actuel : ?)\n2. Days to Cover &gt; 5 jours ? (DTC actuel : ?)\n3. Cost to Borrow &gt; 50% annualisé ? (CTB actuel : ?)\n4. Free float &lt; 50M d\'actions ? (float actuel : ?)\n5. FTDs (Failures to Deliver) en hausse sur 15 jours ?\n6. Catalyst à venir dans les 30 jours ? (earnings, FDA, contrat — lequel ?)\n7. Buzz social croissant ? (mentions StockTwits/Reddit en hausse 7J ?)\n8. Options : gamma exposure positive + OI concentré sur calls OTM ?\n\nSCORE : X/8\n— 6-8 : Squeeze PROBABLE → trade agressif, sizing 3-5%, stop serré -15%\n— 4-5 : Squeeze POSSIBLE → trade modéré, sizing 2%, stop -20%\n— 0-3 : Pas de squeeze en vue → passer\n\nSi score &ge;5 : entry, stop, TP1 (+50%), TP2 (+100%), sizing, et timing optimal.', en:'Evaluate the short squeeze potential of [TICKER]. Answer YES/NO for each criterion (with the actual data):\n\n1. Short Interest &gt; 20% of float? (current SI%: ?)\n2. Days to Cover &gt; 5 days? (current DTC: ?)\n3. Cost to Borrow &gt; 50% annualized? (current CTB: ?)\n4. Free float &lt; 50M shares? (current float: ?)\n5. FTDs (Failures to Deliver) rising over 15 days?\n6. Catalyst coming within 30 days? (earnings, FDA, contract — which one?)\n7. Growing social buzz? (StockTwits/Reddit mentions rising over 7D?)\n8. Options: positive gamma exposure + OI concentrated on OTM calls?\n\nSCORE: X/8\n— 6-8: Squeeze LIKELY → aggressive trade, sizing 3-5%, tight stop -15%\n— 4-5: Squeeze POSSIBLE → moderate trade, sizing 2%, stop -20%\n— 0-3: No squeeze in sight → pass\n\nIf score ≥5: entry, stop, TP1 (+50%), TP2 (+100%), sizing, and optimal timing.', ar:'قيّم إمكانية short squeeze لـ [TICKER]. أجب بنعم/لا لكل معيار (مع الرقم الفعلي):\n\n1. Short Interest أكثر من 20% من الأسهم الحرة؟ (SI% الحالي: ؟)\n2. Days to Cover أكثر من 5 أيام؟ (DTC الحالي: ؟)\n3. Cost to Borrow أكثر من 50% سنوياً؟ (CTB الحالي: ؟)\n4. الأسهم الحرة أقل من 50 مليون سهم؟ (الأسهم الحرة الحالية: ؟)\n5. FTDs (إخفاقات التسليم) في ارتفاع خلال 15 يوماً؟\n6. محفّز قادم خلال 30 يوماً؟ (أرباح، FDA، عقد — أيّهم؟)\n7. ضجة اجتماعية متصاعدة؟ (إشارات StockTwits/Reddit في ارتفاع خلال 7 أيام؟)\n8. الخيارات: gamma exposure إيجابي + OI مركّز على calls خارج المال؟\n\nالدرجة: X/8\n— 6-8: ضغط مُرجَّح ← صفقة هجومية، حجم 3-5%، وقف خسارة ضيق -15%\n— 4-5: ضغط مُحتمَل ← صفقة معتدلة، حجم 2%، وقف خسارة -20%\n— 0-3: لا ضغط في الأفق ← تجاوز\n\nإذا كانت الدرجة 5 فما فوق: entry، stop، TP1 (+50%)، TP2 (+100%)، الحجم، والتوقيت الأمثل.' }
  },
  { num:13, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Insider buying signal', en:'Insider buying signal', ar:'إشارة شراء المطلعين' },
    badge:{ fr:'👔 Insiders', en:'👔 Insiders', ar:'👔 مطّلعون' },
    desc:{ fr:'Détection des achats d\'insiders significatifs. Règle clé : un seul achat ne veut rien dire. Ce qui compte c\'est le cluster buying (&ge;3 insiders en 5 jours) et les montants (&gt;$500K = signal fort).', en:'Detection of significant insider purchases. Key rule: a single buy means nothing. What matters is cluster buying (≥3 insiders within 5 days) and amounts (&gt;$500K = strong signal).', ar:'كشف مشتريات المطلعين المهمة. القاعدة الأساسية: عملية شراء واحدة لا تعني شيئاً. المهم هو الشراء الجماعي (3 مطلعين أو أكثر خلال 5 أيام) والمبالغ (أكثر من $500K = إشارة قوية).' },
    code:{ fr:'Analyse l\'activité insider de [TICKER] sur les 6 derniers mois (Form 4 SEC) :\n\n1. VOLUME — Montant total des achats vs ventes en $. Ratio achats/ventes.\n2. QUI — Quels insiders ont acheté ? (CEO/CFO/Board/10%+ holder). Un achat du CEO &gt; un achat du Board.\n3. CLUSTER — Y a-t-il eu &ge;3 insiders différents achetant dans une fenêtre de 5 jours ? (= signal le plus fort)\n4. MONTANT — Achats individuels &gt;$500K ? (&gt;$1M = conviction très forte)\n5. CONTEXTE — Les achats sont-ils proches du prix actuel ou beaucoup plus bas ? (achats proches du cours = plus significatif)\n6. TRACK RECORD — Ces insiders ont-ils eu raison par le passé ? (performance moyenne 6 mois après leurs achats précédents)\n\nVERDICT :\n— SIGNAL FORT (cluster + gros montants + track record positif) → Trade avec conviction\n— SIGNAL MODÉRÉ (quelques achats isolés) → Surveiller, pas suffisant seul\n— PAS DE SIGNAL (ventes nettes ou achats de routine/options exercées)\n\nSi SIGNAL FORT : entry au prix actuel, stop sous le prix d\'achat moyen des insiders, TP = target consensus.', en:'Analyze insider activity for [TICKER] over the last 6 months (SEC Form 4):\n\n1. VOLUME — Total dollar amount of buys vs sells. Buy/sell ratio.\n2. WHO — Which insiders bought? (CEO/CFO/Board/10%+ holder). A CEO buy &gt; a Board buy.\n3. CLUSTER — Were there ≥3 different insiders buying within a 5-day window? (= strongest signal)\n4. AMOUNT — Individual purchases &gt;$500K? (&gt;$1M = very strong conviction)\n5. CONTEXT — Were the purchases near the current price or much lower? (purchases near the current price = more significant)\n6. TRACK RECORD — Have these insiders been right in the past? (average performance 6 months after their previous purchases)\n\nVERDICT:\n— STRONG SIGNAL (cluster + large amounts + positive track record) → Trade with conviction\n— MODERATE SIGNAL (a few isolated purchases) → Watch, not sufficient on its own\n— NO SIGNAL (net selling or routine buys/exercised options)\n\nIf STRONG SIGNAL: entry at current price, stop below the insiders\' average purchase price, TP = consensus target.', ar:'حلّل نشاط المطلعين لـ [TICKER] خلال آخر 6 أشهر (Form 4 SEC):\n\n1. الحجم — إجمالي المشتريات مقابل المبيعات بالدولار. نسبة المشتريات/المبيعات.\n2. من — أي مطلعين اشتروا؟ (CEO/CFO/مجلس الإدارة/حامل أكثر من 10%). شراء CEO أهم من شراء عضو مجلس إدارة.\n3. شراء جماعي — هل هناك 3 مطلعين مختلفين أو أكثر اشتروا خلال نافذة 5 أيام؟ (= أقوى إشارة)\n4. المبلغ — مشتريات فردية تتجاوز $500K؟ (أكثر من $1M = اقتناع قوي جداً)\n5. السياق — هل المشتريات قريبة من السعر الحالي أم أقل بكثير؟ (مشتريات قريبة من السعر = أكثر دلالة)\n6. السجل — هل كان هؤلاء المطلعون محقين في الماضي؟ (متوسط الأداء 6 أشهر بعد مشترياتهم السابقة)\n\nالحكم:\n— إشارة قوية (شراء جماعي + مبالغ كبيرة + سجل إيجابي) ← صفقة بثقة\n— إشارة معتدلة (بعض المشتريات المعزولة) ← مراقبة، غير كافية وحدها\n— لا إشارة (مبيعات صافية أو مشتريات روتينية/خيارات مُمارَسة)\n\nإذا كانت الإشارة قوية: entry بالسعر الحالي، stop تحت متوسط سعر شراء المطلعين، TP = هدف إجماع المحللين.' }
  },
  { num:14, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Rumeur de rachat / M&amp;A', en:'Buyout rumor / M&amp;A', ar:'شائعة استحواذ' },
    badge:{ fr:'💎 M&A', en:'💎 M&A', ar:'💎 استحواذ' },
    desc:{ fr:'Évaluez la crédibilité d\'une rumeur de rachat et le prix cible. Inclut l\'analyse antitrust (HHI) et le scénario deal vs no-deal — essentiel pour calibrer le risk/reward.', en:'Evaluate the credibility of a buyout rumor and the target price. Includes antitrust analysis (HHI) and the deal vs no-deal scenario — essential for calibrating risk/reward.', ar:'قيّم مصداقية شائعة استحواذ والسعر المستهدف. يشمل تحليل مكافحة الاحتكار (HHI) وسيناريو صفقة مقابل لا صفقة — أساسي لضبط المخاطر/العائد.' },
    code:{ fr:'Il y a une rumeur de rachat sur [TICKER] par [ACQUÉREUR ou "acteur inconnu"]. Analyse :\n\n1. CRÉDIBILITÉ — Source de la rumeur ? (Bloomberg/Reuters = crédible, Reddit = méfiance). Historique de M&amp;A dans ce secteur (derniers deals, primes payées en %).\n2. VALORISATION — Prix actuel vs EV/EBITDA moyen des deals du secteur. Prime historique médiane du secteur (typiquement 25-40%). Fair value implicite si deal.\n3. ACQUÉREURS LOGIQUES — Top 3 acheteurs potentiels avec : capacité financière (cash + dette), synergies estimées en $, risque antitrust (HHI post-merger).\n4. SIGNAUX SUSPECTS — Volume anormal ? Options unusual activity (call sweeps, OI spike) ? Dark pool prints ? Insider buying récent ?\n5. SCÉNARIO DEAL vs NO-DEAL :\n   — Deal à [PRIX] → upside de +X% depuis le cours actuel\n   — No-deal → le titre retombe à [PRIX] (= downside de -Y%)\n   — R/R implicite : X:Y\n6. PROBABILITÉ — Estimation % du deal. Si &gt;50% et R/R &gt;2:1 → trade idea avec entry/stop/TP', en:'There is a buyout rumor on [TICKER] by [ACQUIRER or "unknown player"]. Analyze:\n\n1. CREDIBILITY — Source of the rumor? (Bloomberg/Reuters = credible, Reddit = skepticism). M&amp;A history in this sector (recent deals, premiums paid in %).\n2. VALUATION — Current price vs average EV/EBITDA of sector deals. Historical median sector premium (typically 25-40%). Implied fair value if deal goes through.\n3. LOGICAL ACQUIRERS — Top 3 potential buyers with: financial capacity (cash + debt), estimated synergies in $, antitrust risk (post-merger HHI).\n4. SUSPICIOUS SIGNALS — Abnormal volume? Unusual options activity (call sweeps, OI spike)? Dark pool prints? Recent insider buying?\n5. DEAL vs NO-DEAL SCENARIO:\n   — Deal at [PRICE] → upside of +X% from current price\n   — No-deal → stock falls back to [PRICE] (= downside of -Y%)\n   — Implied R/R: X:Y\n6. PROBABILITY — Estimated deal %. If &gt;50% and R/R &gt;2:1 → trade idea with entry/stop/TP', ar:'هناك شائعة استحواذ على [TICKER] من قبل [ACQUIRER أو "طرف مجهول"]. حلّل:\n\n1. المصداقية — مصدر الشائعة؟ (Bloomberg/Reuters = موثوق، Reddit = حذر). تاريخ M&amp;A في هذا القطاع (آخر الصفقات، العلاوات المدفوعة بالنسبة المئوية %).\n2. التقييم — السعر الحالي مقابل متوسط EV/EBITDA لصفقات القطاع. متوسط العلاوة التاريخية للقطاع (عادة 25-40%). القيمة العادلة الضمنية في حالة الصفقة.\n3. المستحوذون المنطقيون — أفضل 3 مشترين محتملين مع: القدرة المالية (نقد + دين)، التآزر المقدّر بالدولار $، خطر مكافحة الاحتكار (HHI بعد الاندماج).\n4. إشارات مشبوهة — حجم غير طبيعي؟ نشاط خيارات غير عادي (call sweeps، ارتفاع OI)؟ صفقات dark pool؟ شراء مطلعين حديث؟\n5. سيناريو صفقة مقابل لا صفقة:\n   — صفقة بسعر [PRICE] ← صعود +X% من السعر الحالي\n   — لا صفقة ← السهم يعود إلى [PRICE] (= هبوط -Y%)\n   — R/R الضمني: X:Y\n6. الاحتمال — تقدير نسبة % للصفقة. إذا كان أكثر من 50% و R/R أكثر من 2:1 ← فكرة تداول مع entry/stop/TP' }
  },
  { num:15, cat:'macro', numBg:'#eff6ff', numColor:'#2563eb', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Détection de régime de marché', en:'Market regime detection', ar:'كشف نظام السوق' },
    badge:{ fr:'🌡️ Régime', en:'🌡️ Regime', ar:'🌡️ نظام' },
    desc:{ fr:'8 indicateurs quantitatifs pour déterminer si on est en Risk-On, Neutre ou Risk-Off. Ce framework est utilisé quotidiennement par le scanner DailyTickers pour adapter les stratégies au régime.', en:'8 quantitative indicators to determine whether we are in Risk-On, Neutral or Risk-Off. This framework is used daily by the DailyTickers scanner to adapt strategies to the current regime.', ar:'8 مؤشرات كمّية لتحديد ما إذا كنا في نظام Risk-On أو محايد أو Risk-Off. يُستخدم هذا الإطار يومياً في ماسح DailyTickers لتكييف الاستراتيجيات حسب النظام.' },
    code:{ fr:'Réponds à ces 8 questions avec les CHIFFRES ACTUELS pour déterminer le régime de marché :\n\n1. VIX : Niveau actuel ? (&lt;15 = Risk-On, 15-25 = Neutre, &gt;25 = Risk-Off, &gt;35 = Panique)\n2. YIELD CURVE : Spread 10Y-2Y ? (inversé = récession probable, pentification = expansion)\n3. CREDIT : Spread HY (High Yield) vs Investment Grade ? (&lt;300bps = sain, &gt;500bps = stress)\n4. BREADTH : % d\'actions du S&amp;P 500 au-dessus de leur EMA 200 ? (&gt;60% = sain, &lt;40% = faiblesse)\n5. MOMENTUM : S&amp;P 500 au-dessus ou en dessous de son EMA 50 et EMA 200 ?\n6. VOLUMES : Volume moyen 5J vs 20J ? (ratio &gt;1.3 = nervosité accrue)\n7. DEVISES : DXY tendance 30J ? (hausse = risk-off global, baisse = risk-on)\n8. COMMODITIES : Or tendance 30J ? (hausse = fuite vers la sécurité)\n\nVERDICT RÉGIME : Risk-On / Neutre / Risk-Off / Panique\nPOSITIONNEMENT RECOMMANDÉ :\n— Risk-On → surpondérer growth, tech, small caps, crypto. Sous-pondérer défensives.\n— Neutre → portefeuille équilibré, pas de pari directionnel.\n— Risk-Off → surpondérer défensives, or, TLT, cash. Réduire levier et taille des positions.\n— Panique → 30%+ cash, hedges actifs (puts, VXX), uniquement des achats sur capitulation.', en:'Answer these 8 questions with CURRENT NUMBERS to determine the market regime:\n\n1. VIX: Current level? (&lt;15 = Risk-On, 15-25 = Neutral, &gt;25 = Risk-Off, &gt;35 = Panic)\n2. YIELD CURVE: 10Y-2Y spread? (inverted = recession likely, steepening = expansion)\n3. CREDIT: HY (High Yield) vs Investment Grade spread? (&lt;300bps = healthy, &gt;500bps = stress)\n4. BREADTH: % of S&amp;P 500 stocks above their 200-day EMA? (&gt;60% = healthy, &lt;40% = weakness)\n5. MOMENTUM: S&amp;P 500 above or below its 50-day and 200-day EMA?\n6. VOLUMES: 5-day average volume vs 20-day? (ratio &gt;1.3 = heightened nervousness)\n7. CURRENCIES: DXY 30-day trend? (rising = global risk-off, falling = risk-on)\n8. COMMODITIES: Gold 30-day trend? (rising = flight to safety)\n\nREGIME VERDICT: Risk-On / Neutral / Risk-Off / Panic\nRECOMMENDED POSITIONING:\n— Risk-On → overweight growth, tech, small caps, crypto. Underweight defensives.\n— Neutral → balanced portfolio, no directional bet.\n— Risk-Off → overweight defensives, gold, TLT, cash. Reduce leverage and position size.\n— Panic → 30%+ cash, active hedges (puts, VXX), only buy on capitulation.', ar:'أجب عن هذه الأسئلة الثمانية بالأرقام الفعلية لتحديد نظام السوق:\n\n1. VIX: المستوى الحالي؟ (أقل من 15 = Risk-On، 15-25 = محايد، أكثر من 25 = Risk-Off، أكثر من 35 = ذعر)\n2. منحنى العائد: فارق 10 سنوات - سنتين؟ (معكوس = ركود محتمل، انحدار = توسع)\n3. الائتمان: فارق High Yield مقابل Investment Grade؟ (أقل من 300 نقطة أساس = صحي، أكثر من 500 نقطة أساس = ضغط)\n4. الاتساع: نسبة % من أسهم S&amp;P 500 فوق EMA 200؟ (أكثر من 60% = صحي، أقل من 40% = ضعف)\n5. الزخم: S&amp;P 500 فوق أم تحت EMA 50 و EMA 200؟\n6. الأحجام: متوسط الحجم 5 أيام مقابل 20 يوماً؟ (نسبة أكثر من 1.3 = توتر متزايد)\n7. العملات: اتجاه DXY خلال 30 يوماً؟ (صعود = risk-off عالمي، هبوط = risk-on)\n8. السلع: اتجاه الذهب خلال 30 يوماً؟ (صعود = هروب نحو الملاذ الآمن)\n\nحكم النظام: Risk-On / محايد / Risk-Off / ذعر\nالتموضع الموصى به:\n— Risk-On ← زيادة وزن النمو، التكنولوجيا، الأسهم الصغيرة، الكريبتو. تخفيف الدفاعية.\n— محايد ← محفظة متوازنة، بدون رهان اتجاهي.\n— Risk-Off ← زيادة وزن الدفاعية، الذهب، TLT، السيولة. تخفيض الرافعة المالية وحجم المراكز.\n— ذعر ← 30%+ سيولة، تحوّطات فعّالة (puts، VXX)، شراء فقط عند الاستسلام.' }
  },
  { num:16, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Plan de trade technique', en:'Technical trade plan', ar:'خطة تداول فنية' },
    badge:{ fr:'📐 Technique', en:'📐 Technical', ar:'📐 فني' },
    desc:{ fr:'Transforme un "j\'aime bien ce ticker" en plan de trade structuré avec niveaux d\'entrée, stop et objectifs. Sans plan écrit, vous tradez avec votre estomac — et votre estomac a tort 60% du temps.', en:'Turns an "I like this ticker" into a structured trade plan with entry levels, stop and targets. Without a written plan, you trade with your gut — and your gut is wrong 60% of the time.', ar:'حوّل "يعجبني هذا السهم" إلى خطة تداول منظّمة بمستويات دخول ووقف خسارة وأهداف. بدون خطة مكتوبة، أنت تتداول بأحاسيسك — وأحاسيسك مخطئة 60% من الوقت.' },
    code:{ fr:'[TICKER] est à [PRIX ACTUEL]. Je suis [BULLISH/BEARISH]. Construis un plan de trade complet :\n\n1. NIVEAUX CLÉS — Identifie les 3 supports et 3 résistances les plus pertinents (prix exacts). Méthode : EMA 20/50/200, pivots, volumes antérieurs, gaps non comblés.\n2. ENTRY — Zone d\'entrée optimale [prix - prix]. Justifie : pourquoi ce niveau et pas un autre ? Quel signal de confirmation attendre ? (bougie, volume, breakout)\n3. STOP LOSS — Niveau d\'invalidation technique (pas un % arbitraire). Placé sous quel support / au-dessus de quelle résistance ? Perte en % et en $.\n4. OBJECTIFS —\n   TP1 : [prix] (+X%) — prendre 50% de la position\n   TP2 : [prix] (+X%) — prendre 30%\n   TP3 : [prix] (+X%) — laisser courir 20% avec trailing stop\n5. RATIO R/R — Calculé précisément. Si R/R &lt; 1.5:1, dis-moi que le trade ne vaut pas le risque.\n6. TIMING — Quel timeframe ? (scalp / intraday / swing / position). Y a-t-il un catalyseur calendaire à respecter ?\n7. GESTION — Quand remonter le stop ? À quel niveau passer breakeven ? Conditions pour couper avant le stop.\n\nFormat : tableau récapitulatif Entry | Stop | TP1 | TP2 | TP3 | R/R en bas.', en:'[TICKER] is at [CURRENT PRICE]. I am [BULLISH/BEARISH]. Build a complete trade plan:\n\n1. KEY LEVELS — Identify the 3 most relevant supports and 3 resistances (exact prices). Method: EMA 20/50/200, pivots, prior volume levels, unfilled gaps.\n2. ENTRY — Optimal entry zone [price - price]. Justify: why this level and not another? What confirmation signal to wait for? (candle, volume, breakout)\n3. STOP LOSS — Technical invalidation level (not an arbitrary %). Placed below which support / above which resistance? Loss in % and $.\n4. TARGETS —\n   TP1: [price] (+X%) — take 50% of position\n   TP2: [price] (+X%) — take 30%\n   TP3: [price] (+X%) — let 20% run with trailing stop\n5. R/R RATIO — Calculated precisely. If R/R &lt; 1.5:1, tell me the trade is not worth the risk.\n6. TIMING — Which timeframe? (scalp / intraday / swing / position). Is there a calendar catalyst to respect?\n7. MANAGEMENT — When to raise the stop? At what level to move to breakeven? Conditions to cut before the stop.\n\nFormat: summary table Entry | Stop | TP1 | TP2 | TP3 | R/R at the bottom.', ar:'[TICKER] عند [السعر الحالي]. أنا [BULLISH/BEARISH]. ابنِ خطة تداول كاملة:\n\n1. المستويات الرئيسية — حدّد 3 دعوم و3 مقاومات الأكثر صلة (أسعار دقيقة). الطريقة: EMA 20/50/200، نقاط الارتكاز، الأحجام السابقة، الفجوات غير المغلقة.\n2. الدخول — منطقة الدخول المثلى [سعر - سعر]. برّر: لماذا هذا المستوى وليس غيره؟ ما إشارة التأكيد المطلوبة؟ (شمعة، حجم، اختراق)\n3. وقف الخسارة — مستوى إبطال فني (وليس نسبة عشوائية). موضوع تحت أي دعم / فوق أي مقاومة؟ الخسارة بالنسبة المئوية وبالدولار.\n4. الأهداف —\n   TP1: [سعر] (+X%) — أخذ 50% من المركز\n   TP2: [سعر] (+X%) — أخذ 30%\n   TP3: [سعر] (+X%) — ترك 20% مع trailing stop\n5. نسبة R/R — محسوبة بدقة. إذا كانت R/R &lt; 1.5:1، أخبرني أن الصفقة لا تستحق المخاطرة.\n6. التوقيت — أي إطار زمني؟ (scalp / يومي / swing / مركز). هل هناك محفّز في التقويم يجب احترامه؟\n7. الإدارة — متى ترفع وقف الخسارة؟ عند أي مستوى تنتقل إلى breakeven؟ شروط القطع قبل الوقف.\n\nالصيغة: جدول ملخص Entry | Stop | TP1 | TP2 | TP3 | R/R في الأسفل.' }
  },
  { num:17, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Sizing &amp; gestion du risque', en:'Position sizing &amp; risk management', ar:'حجم المركز وإدارة المخاطر' },
    badge:{ fr:'⚙️ Sizing', en:'⚙️ Sizing', ar:'⚙️ حجم' },
    desc:{ fr:'Le prompt que 90% des débutants oublient. La taille de position EST votre gestion du risque. Inclut la formule de Kelly simplifiée et la règle des 2%.', en:'The prompt that 90% of beginners forget. Position sizing IS your risk management. Includes the simplified Kelly formula and the 2% rule.', ar:'البرومبت الذي ينساه 90% من المبتدئين. حجم المركز هو إدارة المخاطر بحد ذاتها. يتضمن صيغة Kelly المبسطة وقاعدة الـ 2%.' },
    code:{ fr:'Mon portefeuille total : [MONTANT €/$]. Mes positions ouvertes actuelles : [LISTE + % ALLOC].\n\nJe veux prendre un trade sur [TICKER] avec entry à [PRIX] et stop à [STOP].\n\nCalcule :\n1. RISQUE PAR TRADE — Perte en $ si le stop est touché. Maximum acceptable = 1-2% du portefeuille. Si le trade dépasse 2%, dis-le clairement.\n2. TAILLE DE POSITION — Nombre d\'actions/unités exact pour respecter la règle des 2%. Montant en $ et en % du portefeuille.\n3. KELLY SIMPLIFIÉ — Avec un win rate estimé de [X%] et un R/R de [Y:1], quelle est la fraction de Kelly ? (Kelly% = Win% - (1-Win%)/R). Si Kelly &gt; 5%, plafonner à 5%.\n4. PORTFOLIO HEAT — Total des risques ouverts (somme des pertes si tous les stops sont touchés). Si heat &gt; 6% du portefeuille = ALERTE, réduire.\n5. CORRÉLATION — Ce nouveau trade est-il corrélé à des positions existantes ? Si oui, réduire la taille de moitié.\n6. SCÉNARIO CATASTROPHE — Si TOUTES mes positions touchent leur stop simultanément : drawdown total en % et en $. Est-ce survivable ?\n\nRÉSUMÉ : Position recommandée = [X] actions / [Y $] / [Z%] du portefeuille.', en:'My total portfolio: [AMOUNT $/€]. My current open positions: [LIST + % ALLOCATION].\n\nI want to take a trade on [TICKER] with entry at [PRICE] and stop at [STOP].\n\nCalculate:\n1. RISK PER TRADE — Loss in $ if stop is hit. Maximum acceptable = 1-2% of portfolio. If the trade exceeds 2%, say so clearly.\n2. POSITION SIZE — Exact number of shares/units to respect the 2% rule. Amount in $ and % of portfolio.\n3. SIMPLIFIED KELLY — With an estimated win rate of [X%] and R/R of [Y:1], what is the Kelly fraction? (Kelly% = Win% - (1-Win%)/R). If Kelly &gt; 5%, cap at 5%.\n4. PORTFOLIO HEAT — Total open risk (sum of losses if all stops are hit). If heat &gt; 6% of portfolio = ALERT, reduce.\n5. CORRELATION — Is this new trade correlated with existing positions? If yes, cut size in half.\n6. CATASTROPHE SCENARIO — If ALL my positions hit their stop simultaneously: total drawdown in % and $. Is this survivable?\n\nSUMMARY: Recommended position = [X] shares / [Y $] / [Z%] of portfolio.', ar:'إجمالي محفظتي: [المبلغ €/$]. مراكزي المفتوحة الحالية: [القائمة + % التوزيع].\n\nأريد فتح صفقة على [TICKER] بدخول عند [السعر] ووقف عند [STOP].\n\nاحسب:\n1. المخاطرة لكل صفقة — الخسارة بالدولار إذا تم ضرب الوقف. الحد الأقصى المقبول = 1-2% من المحفظة. إذا تجاوزت الصفقة 2%، قلها بوضوح.\n2. حجم المركز — عدد الأسهم/الوحدات الدقيق لاحترام قاعدة الـ 2%. المبلغ بالدولار وبنسبة المحفظة.\n3. Kelly المبسط — بمعدل ربح تقديري [X%] ونسبة R/R تبلغ [Y:1]، ما هو كسر Kelly؟ (Kelly% = Win% - (1-Win%)/R). إذا كان Kelly &gt; 5%، ضع حداً أقصى عند 5%.\n4. حرارة المحفظة — إجمالي المخاطر المفتوحة (مجموع الخسائر إذا ضُربت جميع الأوقاف). إذا كانت الحرارة &gt; 6% من المحفظة = تنبيه، خفّض.\n5. الارتباط — هل هذه الصفقة الجديدة مرتبطة بمراكز موجودة؟ إذا نعم، خفّض الحجم إلى النصف.\n6. سيناريو الكارثة — إذا ضُربت جميع أوقاف مراكزي في نفس الوقت: التراجع الإجمالي بالنسبة المئوية وبالدولار. هل يمكن البقاء؟\n\nالملخص: المركز الموصى به = [X] سهم / [Y $] / [Z%] من المحفظة.' }
  },
  { num:18, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Setup pré-earnings', en:'Pre-earnings setup', ar:'إعداد ما قبل الأرباح' },
    badge:{ fr:'🎲 Pre-Earn', en:'🎲 Pre-Earn', ar:'🎲 ما قبل' },
    desc:{ fr:'Préparez un trade avant les résultats trimestriels. Le vrai edge est dans l\'analyse du "implied move" vs le move réalisé historiquement — si le marché surpaie la volatilité, vendez-la. Sinon, achetez-la.', en:'Prepare a trade before quarterly earnings. The real edge is in analyzing the "implied move" vs the historically realized move — if the market is overpaying for volatility, sell it. Otherwise, buy it.', ar:'جهّز صفقة قبل النتائج الفصلية. الميزة الحقيقية في تحليل "implied move" مقابل الحركة المحققة تاريخياً — إذا كان السوق يدفع أكثر مقابل التقلب، بِعه. وإلا، اشتره.' },
    code:{ fr:'[TICKER] publie ses résultats le [DATE]. Prix actuel : [PRIX].\n\nANALYSE PRÉ-EARNINGS :\n1. CONSENSUS — EPS attendu : ? | CA attendu : ? | Marge attendue : ? (source : Yahoo Finance / Seeking Alpha)\n2. HISTORIQUE DE SURPRISES — Tableau des 4 derniers trimestres :\n   | Trimestre | EPS estimé | EPS réalisé | Surprise % | Move J+1 |\n3. WHISPER vs CONSENSUS — Le "vrai" chiffre attendu par le marché est-il au-dessus du consensus officiel ?\n4. IMPLIED MOVE — Prix du straddle ATM / prix de l\'action = move implicite en %. Compare avec le move réalisé moyen sur 4 trimestres. Si implied &gt; réalisé : la vol est chère → vendre (short straddle/iron condor). Si implied &lt; réalisé : la vol est cheap → acheter (long straddle/strangle).\n5. IV RANK — IV actuelle vs range 52 semaines. IV Rank &gt; 70% = vol chère, &lt; 30% = vol cheap.\n6. POSITIONNEMENT — Open interest inhabituel ? Call/put ratio ? Gamma exposure ?\n7. STRATÉGIE RECOMMANDÉE —\n   — Si bullish + vol chère : bull put spread\n   — Si bullish + vol cheap : long call OTM\n   — Si neutre + vol chère : iron condor / short straddle\n   — Si unsure : rester flat, trader le post-earnings le lendemain\n8. TIMING — Entrer la veille ? Le matin du jour J ? Ou attendre l\'after-hours et trader le lendemain ?', en:'[TICKER] reports earnings on [DATE]. Current price: [PRICE].\n\nPRE-EARNINGS ANALYSIS:\n1. CONSENSUS — Expected EPS: ? | Expected revenue: ? | Expected margin: ? (source: Yahoo Finance / Seeking Alpha)\n2. SURPRISE HISTORY — Table of the last 4 quarters:\n   | Quarter | Est. EPS | Actual EPS | Surprise % | Day+1 Move |\n3. WHISPER vs CONSENSUS — Is the "real" number expected by the market above the official consensus?\n4. IMPLIED MOVE — ATM straddle price / stock price = implied move in %. Compare with the average realized move over 4 quarters. If implied &gt; realized: vol is expensive → sell (short straddle/iron condor). If implied &lt; realized: vol is cheap → buy (long straddle/strangle).\n5. IV RANK — Current IV vs 52-week range. IV Rank &gt; 70% = expensive vol, &lt; 30% = cheap vol.\n6. POSITIONING — Unusual open interest? Call/put ratio? Gamma exposure?\n7. RECOMMENDED STRATEGY —\n   — If bullish + expensive vol: bull put spread\n   — If bullish + cheap vol: long OTM call\n   — If neutral + expensive vol: iron condor / short straddle\n   — If unsure: stay flat, trade post-earnings the next day\n8. TIMING — Enter the day before? Morning of? Or wait for after-hours and trade the next day?', ar:'[TICKER] ينشر نتائجه في [التاريخ]. السعر الحالي: [السعر].\n\nتحليل ما قبل الأرباح:\n1. الإجماع — EPS المتوقع: ؟ | الإيرادات المتوقعة: ؟ | الهامش المتوقع: ؟ (المصدر: Yahoo Finance / Seeking Alpha)\n2. تاريخ المفاجآت — جدول آخر 4 فصول:\n   | الفصل | EPS المقدّر | EPS المحقق | المفاجأة % | الحركة J+1 |\n3. WHISPER مقابل الإجماع — هل الرقم "الحقيقي" المتوقع من السوق أعلى من الإجماع الرسمي؟\n4. الحركة الضمنية — سعر straddle ATM / سعر السهم = الحركة الضمنية بالنسبة المئوية. قارن مع متوسط الحركة المحققة على 4 فصول. إذا كانت الضمنية &gt; المحققة: التقلب غالٍ ← بِع (short straddle/iron condor). إذا كانت الضمنية &lt; المحققة: التقلب رخيص ← اشترِ (long straddle/strangle).\n5. IV RANK — IV الحالية مقابل نطاق 52 أسبوعاً. IV Rank &gt; 70% = تقلب غالٍ، &lt; 30% = تقلب رخيص.\n6. التموضع — Open interest غير عادي؟ نسبة Call/Put؟ Gamma exposure؟\n7. الاستراتيجية الموصى بها —\n   — إذا صعودي + تقلب غالٍ: bull put spread\n   — إذا صعودي + تقلب رخيص: long call OTM\n   — إذا محايد + تقلب غالٍ: iron condor / short straddle\n   — إذا غير متأكد: ابقَ خارج السوق، تداول ما بعد الأرباح في اليوم التالي\n8. التوقيت — الدخول عشية الإعلان؟ صباح يوم الإعلان؟ أم الانتظار ما بعد الإغلاق والتداول في اليوم التالي؟' }
  },
  { num:19, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Audit sécurité dividende', en:'Dividend safety audit', ar:'تدقيق أمان الأرباح الموزعة' },
    badge:{ fr:'💰 Dividende', en:'💰 Dividend', ar:'💰 أرباح' },
    desc:{ fr:'Détecte les "yield traps" — un rendement &gt;8% est un signal d\'alerte, pas une opportunité. Vérifie la couverture FCF, la streak, et les signaux de coupe imminente.', en:'Detects "yield traps" — a yield &gt;8% is a warning sign, not an opportunity. Checks FCF coverage, streak, and imminent cut signals.', ar:'يكشف "فخاخ العائد" — عائد أعلى من 8% هو إشارة خطر وليس فرصة. يتحقق من تغطية FCF، والسلسلة المتواصلة، وإشارات القطع الوشيك.' },
    code:{ fr:'[TICKER] affiche un rendement de [X%]. Avant que je tombe dans le piège du yield, audite ce dividende :\n\n1. RENDEMENT — Actuel vs moyenne 5 ans. Si actuel &gt; 150% de la moyenne → le marché price un risque de coupe. PIÈGE ?\n2. COUVERTURE —\n   — Payout ratio (EPS) : ? (alerte si &gt;80%, danger si &gt;100%)\n   — Payout ratio (FCF) : ? (le vrai indicateur — alerte si &gt;75%)\n   — FCF / dividendes versés : ratio ? (sain si &gt; 1.5x)\n3. BILAN — Dette nette / EBITDA : ? (&gt;3x = risque). La dette est-elle en hausse ? Maturités à venir ?\n4. STREAK — Combien d\'années consécutives de hausse du dividende ? (Aristocrat = 25+, King = 50+, Champion = 10+)\n5. CROISSANCE — CAGR du dividende 5 ans : ? (&lt; inflation = perte de pouvoir d\'achat réelle)\n6. SIGNAUX DE COUPE — Cocher OUI/NON :\n   ☐ FCF en baisse 2 trimestres consécutifs\n   ☐ Management a changé le wording sur le dividende dans le dernier call\n   ☐ Payout ratio FCF &gt; 90%\n   ☐ Secteur en difficulté structurelle\n   ☐ Buyback suspendu (souvent le premier signe avant la coupe du dividende)\n   → Si ≥3 OUI : risque de coupe ÉLEVÉ\n\n7. VERDICT : Aristocrat solide / Rendement fiable / Yield trap à éviter\nDates clés : prochaine ex-date, prochaine date de versement.', en:'[TICKER] shows a yield of [X%]. Before I fall into the yield trap, audit this dividend:\n\n1. YIELD — Current vs 5-year average. If current &gt; 150% of average → the market is pricing in a cut risk. TRAP?\n2. COVERAGE —\n   — Payout ratio (EPS): ? (alert if &gt;80%, danger if &gt;100%)\n   — Payout ratio (FCF): ? (the real indicator — alert if &gt;75%)\n   — FCF / dividends paid: ratio? (healthy if &gt; 1.5x)\n3. BALANCE SHEET — Net debt / EBITDA: ? (&gt;3x = risk). Is debt rising? Upcoming maturities?\n4. STREAK — How many consecutive years of dividend increases? (Aristocrat = 25+, King = 50+, Champion = 10+)\n5. GROWTH — 5-year dividend CAGR: ? (&lt; inflation = real loss of purchasing power)\n6. CUT SIGNALS — Check YES/NO:\n   ☐ FCF declining 2 consecutive quarters\n   ☐ Management changed wording about the dividend in the latest call\n   ☐ FCF payout ratio &gt; 90%\n   ☐ Sector in structural difficulty\n   ☐ Buyback suspended (often the first sign before a dividend cut)\n   → If ≥3 YES: cut risk is HIGH\n\n7. VERDICT: Solid Aristocrat / Reliable yield / Yield trap to avoid\nKey dates: next ex-date, next payment date.', ar:'[TICKER] يُظهر عائداً بنسبة [X%]. قبل أن أقع في فخ العائد، دقّق هذا التوزيع:\n\n1. العائد — الحالي مقابل المتوسط 5 سنوات. إذا كان الحالي &gt; 150% من المتوسط ← السوق يسعّر مخاطر القطع. فخ؟\n2. التغطية —\n   — نسبة التوزيع (EPS): ؟ (تنبيه إذا &gt;80%، خطر إذا &gt;100%)\n   — نسبة التوزيع (FCF): ؟ (المؤشر الحقيقي — تنبيه إذا &gt;75%)\n   — FCF / التوزيعات المدفوعة: النسبة؟ (صحي إذا &gt; 1.5x)\n3. الميزانية — الدين الصافي / EBITDA: ؟ (&gt;3x = خطر). هل الدين في ارتفاع؟ استحقاقات قادمة؟\n4. السلسلة — كم سنة متتالية من رفع التوزيع؟ (Aristocrat = 25+، King = 50+، Champion = 10+)\n5. النمو — CAGR للتوزيع 5 سنوات: ؟ (&lt; التضخم = خسارة حقيقية في القوة الشرائية)\n6. إشارات القطع — حدد نعم/لا:\n   ☐ FCF في انخفاض لفصلين متتاليين\n   ☐ الإدارة غيّرت الصياغة حول التوزيع في آخر مكالمة أرباح\n   ☐ نسبة التوزيع FCF &gt; 90%\n   ☐ القطاع في صعوبة هيكلية\n   ☐ إعادة الشراء معلّقة (غالباً أول علامة قبل قطع التوزيع)\n   ← إذا ≥3 نعم: خطر قطع مرتفع\n\n7. الحكم: Aristocrat متين / عائد موثوق / فخ عائد يجب تجنبه\nالتواريخ الرئيسية: تاريخ ex-date التالي، تاريخ الدفع التالي.' }
  },
  { num:20, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Réalité-check valorisation', en:'Valuation reality check', ar:'فحص واقعية التقييم' },
    badge:{ fr:'🧮 DCF', en:'🧮 DCF', ar:'🧮 تقييم' },
    desc:{ fr:'5 méthodes de valorisation croisées pour savoir si un titre est cher ou pas. La question la plus puissante : "quel taux de croissance le marché price-t-il ?" (reverse DCF). Si la réponse est irréaliste, le titre est trop cher.', en:'5 cross-referenced valuation methods to know if a stock is expensive or not. The most powerful question: "what growth rate is the market pricing in?" (reverse DCF). If the answer is unrealistic, the stock is too expensive.', ar:'5 طرق تقييم متقاطعة لمعرفة إذا كان السهم غالياً أم لا. السؤال الأقوى: "ما معدل النمو الذي يسعّره السوق؟" (reverse DCF). إذا كانت الإجابة غير واقعية، فالسهم غالٍ جداً.' },
    code:{ fr:'[TICKER] cote à [PRIX]. Est-ce cher ? Réponds avec 5 méthodes :\n\n1. COMPARABLES — Tableau :\n   | Métrique | [TICKER] | Peer 1 | Peer 2 | Peer 3 | Médiane secteur |\n   | P/E fwd | | | | | |\n   | EV/EBITDA | | | | | |\n   | P/FCF | | | | | |\n   | PEG | | | | | |\n   Prime ou décote en % vs médiane. La prime est-elle JUSTIFIÉE ? (croissance supérieure, moat, qualité)\n\n2. HISTORIQUE — P/E actuel vs P/E moyen 5 ans. Combien d\'écarts-types au-dessus/en-dessous de la moyenne ? (&gt;2σ = extrême)\n\n3. DCF SIMPLIFIÉ — Hypothèses : croissance FCF [X%] sur 5 ans, terminal growth 2.5%, WACC [Y%]. Fair value : $[Z]. Upside/downside : [%].\n\n4. REVERSE DCF — C\'est LA question clé : au prix actuel, quel taux de croissance annuel le marché price-t-il implicitement sur 5 ans ? Si &gt; 25%/an → le marché est très optimiste. Si &lt; 5%/an → le marché est pessimiste. Ce taux est-il réaliste vu l\'historique ?\n\n5. SUM-OF-THE-PARTS — Si multi-segments : valorise chaque segment séparément. Y a-t-il un conglomerate discount ? Un segment caché qui vaut plus que la market cap totale ?\n\nVERDICT : ☐ Sous-évalué ☐ Fair value ☐ Surévalué ☐ Bulle\nZone d\'achat estimée : $[X] - $[Y] (décote de 15-25% vs fair value pour marge de sécurité).', en:'[TICKER] trades at [PRICE]. Is it expensive? Answer with 5 methods:\n\n1. COMPARABLES — Table:\n   | Metric | [TICKER] | Peer 1 | Peer 2 | Peer 3 | Sector Median |\n   | Fwd P/E | | | | | |\n   | EV/EBITDA | | | | | |\n   | P/FCF | | | | | |\n   | PEG | | | | | |\n   Premium or discount in % vs median. Is the premium JUSTIFIED? (superior growth, moat, quality)\n\n2. HISTORICAL — Current P/E vs 5-year average P/E. How many standard deviations above/below the mean? (&gt;2σ = extreme)\n\n3. SIMPLIFIED DCF — Assumptions: FCF growth [X%] over 5 years, terminal growth 2.5%, WACC [Y%]. Fair value: $[Z]. Upside/downside: [%].\n\n4. REVERSE DCF — This is THE key question: at the current price, what annual growth rate is the market implicitly pricing in over 5 years? If &gt; 25%/yr → the market is very optimistic. If &lt; 5%/yr → the market is pessimistic. Is this rate realistic given the track record?\n\n5. SUM-OF-THE-PARTS — If multi-segment: value each segment separately. Is there a conglomerate discount? A hidden segment worth more than the total market cap?\n\nVERDICT: ☐ Undervalued ☐ Fair value ☐ Overvalued ☐ Bubble\nEstimated buy zone: $[X] - $[Y] (15-25% discount vs fair value for margin of safety).', ar:'[TICKER] يُتداول عند [السعر]. هل هو غالٍ؟ أجب بـ 5 طرق:\n\n1. المقارنات — جدول:\n   | المقياس | [TICKER] | نظير 1 | نظير 2 | نظير 3 | وسيط القطاع |\n   | P/E fwd | | | | | |\n   | EV/EBITDA | | | | | |\n   | P/FCF | | | | | |\n   | PEG | | | | | |\n   علاوة أو خصم بالنسبة المئوية مقابل الوسيط. هل العلاوة مبرّرة؟ (نمو أعلى، خندق، جودة)\n\n2. التاريخ — P/E الحالي مقابل P/E المتوسط 5 سنوات. كم انحراف معياري فوق/تحت المتوسط؟ (&gt;2σ = حد أقصى)\n\n3. DCF المبسط — الفرضيات: نمو FCF [X%] على 5 سنوات، نمو نهائي 2.5%، WACC [Y%]. القيمة العادلة: $[Z]. صعود/هبوط: [%].\n\n4. REVERSE DCF — هذا هو السؤال الرئيسي: بالسعر الحالي، ما معدل النمو السنوي الذي يسعّره السوق ضمنياً على 5 سنوات؟ إذا &gt; 25%/سنة ← السوق متفائل جداً. إذا &lt; 5%/سنة ← السوق متشائم. هل هذا المعدل واقعي بالنظر إلى التاريخ؟\n\n5. مجموع الأجزاء — إذا كانت هناك قطاعات متعددة: قيّم كل قطاع على حدة. هل يوجد خصم تكتل؟ هل هناك قطاع مخفي يساوي أكثر من إجمالي القيمة السوقية؟\n\nالحكم: ☐ مقيّم بأقل من قيمته ☐ قيمة عادلة ☐ مقيّم بأعلى من قيمته ☐ فقاعة\nمنطقة الشراء المقدّرة: $[X] - $[Y] (خصم 15-25% مقابل القيمة العادلة كهامش أمان).' }
  },
  { num:21, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Biotech : événement binaire', en:'Biotech: binary event', ar:'بيوتك: حدث ثنائي' },
    badge:{ fr:'🧬 FDA', en:'🧬 FDA', ar:'🧬 FDA' },
    desc:{ fr:'Les biotechs sont des paris binaires : +200% ou -80% sur un résultat FDA/Phase III. Ce prompt force un calcul de valeur attendue (EV) pour savoir si le pari est mathématiquement rentable, même avec une probabilité de succès faible.', en:'Biotechs are binary bets: +200% or -80% on an FDA/Phase III result. This prompt forces an expected value (EV) calculation to determine if the bet is mathematically profitable, even with a low probability of success.', ar:'البيوتك رهانات ثنائية: +200% أو -80% على نتيجة FDA/Phase III. هذا البرومبت يفرض حساب القيمة المتوقعة (EV) لمعرفة إذا كان الرهان مربحاً رياضياً، حتى مع احتمال نجاح منخفض.' },
    code:{ fr:'[TICKER] est une biotech avec un catalyseur binaire à venir : [RÉSULTAT PHASE/PDUFA/DONNÉES].\n\nANALYSE BINAIRE :\n1. PIPELINE — Tableau des candidats :\n   | Molécule | Indication | Phase | Taille du marché (TAM) | Date résultats | Probabilité historique de succès par phase |\n   Rappel probabilités moyennes : Phase I→II : 52%, Phase II→III : 28%, Phase III→Approval : 58%, PDUFA : 85%\n\n2. SCÉNARIO SUCCÈS — Si résultat positif :\n   — Estimation du peak sales ($)\n   — Multiple revenus pour biotech du stade (pre-revenue : 5-10x, commercial : 3-5x)\n   — Prix cible en cas de succès : $[X] (upside : +Y%)\n\n3. SCÉNARIO ÉCHEC — Si résultat négatif :\n   — Le pipeline restant vaut combien ? (cash + autres candidats)\n   — Floor price estimé : $[X] (downside : -Y%)\n\n4. VALEUR ATTENDUE — EV = (probabilité succès × upside) + (probabilité échec × downside)\n   — Si EV &gt; 0 : le pari est mathématiquement rentable\n   — Si EV &lt; 0 : même avec l\'upside, le risque n\'est pas compensé\n\n5. CASH RUNWAY — Cash actuel : $[X]M. Burn rate trimestriel : $[Y]M. Runway : [Z] trimestres. Risque de dilution si &lt;4 trimestres.\n\n6. TRADE — Si EV &gt; 0 : sizing max 2-3% du portefeuille (événement binaire = sizing réduit). Entry / Stop (si applicable — souvent pas de stop sur binaire) / TP.', en:'[TICKER] is a biotech with an upcoming binary catalyst: [PHASE RESULT/PDUFA/DATA READOUT].\n\nBINARY ANALYSIS:\n1. PIPELINE — Candidate table:\n   | Molecule | Indication | Phase | Market Size (TAM) | Results Date | Historical Success Probability by Phase |\n   Reminder average probabilities: Phase I→II: 52%, Phase II→III: 28%, Phase III→Approval: 58%, PDUFA: 85%\n\n2. SUCCESS SCENARIO — If positive result:\n   — Estimated peak sales ($)\n   — Revenue multiple for biotech at this stage (pre-revenue: 5-10x, commercial: 3-5x)\n   — Target price on success: $[X] (upside: +Y%)\n\n3. FAILURE SCENARIO — If negative result:\n   — How much is the remaining pipeline worth? (cash + other candidates)\n   — Estimated floor price: $[X] (downside: -Y%)\n\n4. EXPECTED VALUE — EV = (success probability × upside) + (failure probability × downside)\n   — If EV &gt; 0: the bet is mathematically profitable\n   — If EV &lt; 0: even with the upside, the risk is not compensated\n\n5. CASH RUNWAY — Current cash: $[X]M. Quarterly burn rate: $[Y]M. Runway: [Z] quarters. Dilution risk if &lt;4 quarters.\n\n6. TRADE — If EV &gt; 0: max sizing 2-3% of portfolio (binary event = reduced sizing). Entry / Stop (if applicable — often no stop on binary) / TP.', ar:'[TICKER] شركة بيوتك مع محفّز ثنائي قادم: [نتيجة PHASE/PDUFA/بيانات].\n\nالتحليل الثنائي:\n1. خط الأنابيب — جدول المرشحين:\n   | الجزيء | المؤشر | المرحلة | حجم السوق (TAM) | تاريخ النتائج | احتمال النجاح التاريخي حسب المرحلة |\n   تذكير بالاحتمالات المتوسطة: Phase I←II: 52%، Phase II←III: 28%، Phase III←Approval: 58%، PDUFA: 85%\n\n2. سيناريو النجاح — إذا كانت النتيجة إيجابية:\n   — تقدير ذروة المبيعات ($)\n   — مضاعف الإيرادات للبيوتك حسب المرحلة (ما قبل الإيرادات: 5-10x، تجاري: 3-5x)\n   — السعر المستهدف في حال النجاح: $[X] (صعود: +Y%)\n\n3. سيناريو الفشل — إذا كانت النتيجة سلبية:\n   — كم يساوي خط الأنابيب المتبقي؟ (السيولة + المرشحون الآخرون)\n   — السعر الأدنى المقدّر: $[X] (هبوط: -Y%)\n\n4. القيمة المتوقعة — EV = (احتمال النجاح × الصعود) + (احتمال الفشل × الهبوط)\n   — إذا كانت EV &gt; 0: الرهان مربح رياضياً\n   — إذا كانت EV &lt; 0: حتى مع الصعود، المخاطرة غير معوّضة\n\n5. مدرج السيولة — السيولة الحالية: $[X]M. معدل الحرق الفصلي: $[Y]M. المدرج: [Z] فصل. خطر تخفيف إذا &lt;4 فصول.\n\n6. الصفقة — إذا كانت EV &gt; 0: حجم أقصى 2-3% من المحفظة (حدث ثنائي = حجم مخفّض). الدخول / الوقف (إن أمكن — غالباً لا يوجد وقف على الثنائي) / الهدف.' }
  },
  { num:22, cat:'portfolio', numBg:'#f5f3ff', numColor:'#7c3aed', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Tax-loss harvesting', en:'Tax-loss harvesting', ar:'حصاد الخسائر الضريبية' },
    badge:{ fr:'📋 Tax', en:'📋 Tax', ar:'📋 ضرائب' },
    desc:{ fr:'Optimisation fiscale de fin d\'année (ou en cours d\'année sur les perdants). Identifie les positions à vendre pour matérialiser des moins-values, tout en maintenant l\'exposition via un swap. Attention aux règles de wash sale (30 jours US) ou aux spécificités PEA/CTO en Europe.', en:'Year-end tax optimization (or mid-year on losers). Identifies positions to sell to realize losses, while maintaining exposure via a swap. Watch out for wash sale rules (30 days US) or PEA/CTO specifics in Europe.', ar:'تحسين ضريبي لنهاية السنة (أو خلالها على الخاسرين). يحدد المراكز التي يجب بيعها لتحقيق خسائر رأسمالية، مع الحفاظ على التعرّض عبر بديل. انتبه لقواعد wash sale (30 يوماً في أمريكا) أو خصوصيات PEA/CTO في أوروبا.' },
    code:{ fr:'Mon portefeuille : [LISTE POSITIONS + PRIX D\'ENTRÉE + PRIX ACTUEL + ENVELOPPE (PEA/CTO/ISA/401k)].\nMon pays fiscal : [FRANCE / US / UK / AUTRE].\n\nOPTIMISATION FISCALE :\n1. PERTES LATENTES — Tableau de toutes les positions en moins-value :\n   | Ticker | P.achat | P.actuel | Moins-value | % perte | Enveloppe |\n   Total des moins-values matérialisables : $[X]\n\n2. GAINS LATENTS — Tableau des plus-values. Plus-values réalisées cette année : $[X].\n   Économie fiscale si je matérialise les pertes : $[Y] (au taux marginal de [Z%])\n\n3. SWAP PROPOSALS — Pour chaque position perdante, propose un substitut qui maintient l\'exposition :\n   | Vendre | Acheter à la place | Corrélation | Pourquoi c\'est un bon swap |\n   Exemples : MSFT → AAPL (même secteur), VTI → VOO (même exposition), ARKK → QQQM (tech growth)\n\n4. RÈGLES FISCALES —\n   — Wash sale rule applicable ? (US: 30 jours, pas de rachat du même titre)\n   — PEA : les moins-values ne sont pas déductibles sauf clôture\n   — CTO : imputation sur plus-values de même nature\n   — Report : les pertes sont-elles reportables et sur combien d\'années ?\n\n5. CALENDRIER — Date limite pour les transactions fiscales de cette année. Ordres à passer MAINTENANT vs ceux qui peuvent attendre.\n\nRÉSUMÉ : Économie nette estimée : $[X] après frais de transaction.', en:'My portfolio: [LIST OF POSITIONS + PURCHASE PRICE + CURRENT PRICE + ACCOUNT TYPE (PEA/CTO/ISA/401k)].\nMy tax country: [US / UK / FRANCE / OTHER].\n\nTAX OPTIMIZATION:\n1. UNREALIZED LOSSES — Table of all positions with a loss:\n   | Ticker | Purchase Price | Current Price | Loss | % Loss | Account |\n   Total realizable losses: $[X]\n\n2. UNREALIZED GAINS — Table of gains. Realized gains this year: $[X].\n   Tax savings if I realize the losses: $[Y] (at marginal rate of [Z%])\n\n3. SWAP PROPOSALS — For each losing position, suggest a substitute that maintains exposure:\n   | Sell | Buy Instead | Correlation | Why It\'s a Good Swap |\n   Examples: MSFT → AAPL (same sector), VTI → VOO (same exposure), ARKK → QQQM (tech growth)\n\n4. TAX RULES —\n   — Wash sale rule applicable? (US: 30 days, no repurchase of the same security)\n   — PEA: losses are not deductible except on closure\n   — CTO: offset against gains of the same type\n   — Carryforward: are losses carryable and for how many years?\n\n5. CALENDAR — Deadline for this year\'s tax transactions. Orders to place NOW vs those that can wait.\n\nSUMMARY: Estimated net savings: $[X] after transaction costs.', ar:'محفظتي: [قائمة المراكز + سعر الدخول + السعر الحالي + الحساب (PEA/CTO/ISA/401k)].\nبلد إقامتي الضريبية: [فرنسا / أمريكا / بريطانيا / آخر].\n\nالتحسين الضريبي:\n1. الخسائر الكامنة — جدول جميع المراكز في خسارة:\n   | السهم | سعر الشراء | السعر الحالي | الخسارة | % الخسارة | الحساب |\n   إجمالي الخسائر القابلة للتحقيق: $[X]\n\n2. الأرباح الكامنة — جدول الأرباح الرأسمالية. الأرباح المحققة هذا العام: $[X].\n   التوفير الضريبي إذا حققت الخسائر: $[Y] (بمعدل هامشي [Z%])\n\n3. مقترحات الاستبدال — لكل مركز خاسر، اقترح بديلاً يحافظ على التعرّض:\n   | بِع | اشترِ بدلاً منه | الارتباط | لماذا هو بديل جيد |\n   أمثلة: MSFT ← AAPL (نفس القطاع)، VTI ← VOO (نفس التعرّض)، ARKK ← QQQM (نمو تقني)\n\n4. القواعد الضريبية —\n   — هل قاعدة wash sale سارية؟ (أمريكا: 30 يوماً، عدم إعادة شراء نفس السهم)\n   — PEA: الخسائر غير قابلة للخصم إلا عند الإغلاق\n   — CTO: التعويض على أرباح رأسمالية من نفس النوع\n   — الترحيل: هل الخسائر قابلة للترحيل وعلى كم سنة؟\n\n5. التقويم — الموعد الأخير للعمليات الضريبية هذا العام. الأوامر الواجب تنفيذها الآن مقابل تلك التي يمكنها الانتظار.\n\nالملخص: التوفير الصافي المقدّر: $[X] بعد رسوم العمليات.' }
  },
  { num:23, cat:'portfolio', numBg:'#f5f3ff', numColor:'#7c3aed', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Construction de portefeuille', en:'Portfolio construction', ar:'بناء محفظة من الصفر' },
    badge:{ fr:'🏗️ Build', en:'🏗️ Build', ar:'🏗️ بناء' },
    desc:{ fr:'Pour ceux qui partent de zéro ou qui veulent tout reconstruire. Ce prompt force l\'IA à proposer des tickers concrets avec des % d\'allocation, pas juste "diversifiez entre actions et obligations".', en:'For those starting from scratch or wanting to rebuild everything. This prompt forces the AI to propose concrete tickers with allocation %, not just "diversify between stocks and bonds".', ar:'لمن يبدأون من الصفر أو يريدون إعادة البناء الكامل. هذا البرومبت يجبر الذكاء الاصطناعي على اقتراح أسهم محددة بنسب توزيع، وليس مجرد "نوّع بين الأسهم والسندات".' },
    code:{ fr:'J\'ai [MONTANT €/$] à investir. Mon profil :\n— Âge : [X] ans\n— Horizon : [X] ans\n— Tolérance au risque : [conservative / modéré / agressif]\n— Enveloppe : [PEA / CTO / 401k / ISA / crypto wallet]\n— Objectif : [croissance / revenu / préservation / spéculatif]\n— Contraintes : [éthique ESG / pas de tech / pas de crypto / Sharia-compliant / autre]\n\nCONSTRUIS un portefeuille concret :\n1. ALLOCATION STRATÉGIQUE — Tableau :\n   | Classe d\'actif | % | Instruments spécifiques | TER/frais |\n   | Actions US | X% | [ETF ou tickers] | X% |\n   | Actions EU | X% | [ETF ou tickers] | X% |\n   | Obligations | X% | [ETF ou tickers] | X% |\n   | Or / Commodities | X% | [ETF ou tickers] | X% |\n   | Crypto | X% | [tickers] | — |\n   | Cash | X% | — | — |\n\n2. JUSTIFICATION — Pourquoi cette allocation pour MON profil spécifiquement ? Référence historique : rendement et drawdown max de cette allocation sur 10 ans.\n\n3. PLAN D\'EXÉCUTION — Tout investir d\'un coup (lump sum) ou DCA sur [X] mois ? Justifie avec les stats historiques (lump sum gagne 68% du temps, mais DCA réduit le regret).\n\n4. REBALANCING — Fréquence recommandée : [mensuel / trimestriel / annuel]. Bandes de tolérance (ex: rebalancer si écart &gt; 5%).\n\n5. CE QUE JE NE DOIS PAS FAIRE — Top 5 erreurs courantes pour ce profil (ex: "ne pas mettre plus de 10% en crypto même si vous êtes agressif").', en:'I have [AMOUNT $/€] to invest. My profile:\n— Age: [X] years\n— Horizon: [X] years\n— Risk tolerance: [conservative / moderate / aggressive]\n— Account type: [PEA / CTO / 401k / ISA / crypto wallet]\n— Goal: [growth / income / preservation / speculative]\n— Constraints: [ESG ethical / no tech / no crypto / Sharia-compliant / other]\n\nBUILD a concrete portfolio:\n1. STRATEGIC ALLOCATION — Table:\n   | Asset Class | % | Specific Instruments | TER/fees |\n   | US Equities | X% | [ETF or tickers] | X% |\n   | EU Equities | X% | [ETF or tickers] | X% |\n   | Bonds | X% | [ETF or tickers] | X% |\n   | Gold / Commodities | X% | [ETF or tickers] | X% |\n   | Crypto | X% | [tickers] | — |\n   | Cash | X% | — | — |\n\n2. JUSTIFICATION — Why this allocation for MY specific profile? Historical reference: return and max drawdown of this allocation over 10 years.\n\n3. EXECUTION PLAN — Invest all at once (lump sum) or DCA over [X] months? Justify with historical stats (lump sum wins 68% of the time, but DCA reduces regret).\n\n4. REBALANCING — Recommended frequency: [monthly / quarterly / annual]. Tolerance bands (e.g.: rebalance if deviation &gt; 5%).\n\n5. WHAT NOT TO DO — Top 5 common mistakes for this profile (e.g.: "don\'t put more than 10% in crypto even if you\'re aggressive").', ar:'لديّ [المبلغ €/$] للاستثمار. ملفي الشخصي:\n— العمر: [X] سنة\n— الأفق: [X] سنة\n— تحمّل المخاطر: [محافظ / معتدل / عدواني]\n— الحساب: [PEA / CTO / 401k / ISA / محفظة كريبتو]\n— الهدف: [نمو / دخل / حفظ / مضاربة]\n— القيود: [ESG أخلاقي / بدون تقنية / بدون كريبتو / متوافق مع الشريعة / أخرى]\n\nابنِ محفظة محددة:\n1. التوزيع الاستراتيجي — جدول:\n   | فئة الأصول | % | الأدوات المحددة | TER/الرسوم |\n   | أسهم أمريكية | X% | [ETF أو أسهم] | X% |\n   | أسهم أوروبية | X% | [ETF أو أسهم] | X% |\n   | سندات | X% | [ETF أو أسهم] | X% |\n   | ذهب / سلع | X% | [ETF أو أسهم] | X% |\n   | كريبتو | X% | [رموز] | — |\n   | سيولة | X% | — | — |\n\n2. التبرير — لماذا هذا التوزيع لملفي الشخصي تحديداً؟ مرجع تاريخي: العائد والتراجع الأقصى لهذا التوزيع على 10 سنوات.\n\n3. خطة التنفيذ — استثمار كل شيء دفعة واحدة (lump sum) أم DCA على [X] شهر؟ برّر مع الإحصاءات التاريخية (lump sum يفوز 68% من الوقت، لكن DCA يقلّل الندم).\n\n4. إعادة التوازن — التكرار الموصى به: [شهري / فصلي / سنوي]. نطاقات التحمّل (مثال: إعادة التوازن إذا كان الانحراف &gt; 5%).\n\n5. ما لا يجب عليّ فعله — أكبر 5 أخطاء شائعة لهذا الملف (مثال: "لا تضع أكثر من 10% في الكريبتو حتى لو كنت عدوانياً").' }
  },
  { num:24, cat:'crypto', numBg:'#fff7ed', numColor:'#ea580c', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Cycle des narratives crypto', en:'Crypto narrative cycle', ar:'دورة السرديات الكريبتو' },
    badge:{ fr:'🌊 Narratifs', en:'🌊 Narratives', ar:'🌊 سرديات' },
    desc:{ fr:'En crypto, l\'argent suit les narratives (AI, RWA, DePIN, memecoins, L2...). Identifier où on est dans le cycle du hype pour chaque narrative est la clé. Early = acheter, Peak = prendre des profits, Dead = accumuler pour le prochain cycle.', en:'In crypto, money follows narratives (AI, RWA, DePIN, memecoins, L2...). Identifying where we are in the hype cycle for each narrative is the key. Early = buy, Peak = take profits, Dead = accumulate for the next cycle.', ar:'في الكريبتو، المال يتبع السرديات (AI، RWA، DePIN، memecoins، L2...). تحديد أين نحن في دورة الضجة لكل سردية هو المفتاح. Early = اشترِ، Peak = خذ أرباحاً، Dead = جمّع للدورة القادمة.' },
    code:{ fr:'Analyse les narratives crypto en cours :\n\nTABLEAU DES NARRATIVES :\n| Narrative | Phase (Early / Growth / Peak / Decline / Dead) | Tokens leaders | Perf 30J | TVL trend | Social buzz trend |\n| AI / DePIN | | | | | |\n| RWA (Real World Assets) | | | | | |\n| Memecoins | | | | | |\n| Layer 2 / Scaling | | | | | |\n| Restaking / LST | | | | | |\n| Gaming / Metaverse | | | | | |\n| DeFi 2.0 / Yield | | | | | |\n| BTC ecosystem (Ordinals, Runes) | | | | | |\n\nPour chaque narrative :\n1. PHASE — Où en est-on dans le Gartner Hype Cycle ? Innovation Trigger → Peak of Inflated Expectations → Trough of Disillusionment → Slope of Enlightenment → Plateau of Productivity\n2. ARGENT INTELLIGENT — Les VC investissent-ils encore ? Y a-t-il des gros rounds récents ?\n3. ROTATION — L\'argent sort-il d\'une narrative pour aller vers une autre ? Laquelle ?\n4. PLAY RECOMMANDÉ — Pour chaque narrative en phase Early/Growth : top 3 tokens à acheter. Pour chaque narrative en Peak : prendre des profits.\n\nRÉSUMÉ : "En ce moment, la narrative la plus prometteuse est [X] parce que [Y]. Éviter [Z] qui est en phase de déclin."', en:'Analyze the current crypto narratives:\n\nNARRATIVE TABLE:\n| Narrative | Phase (Early / Growth / Peak / Decline / Dead) | Leading Tokens | 30D Perf | TVL Trend | Social Buzz Trend |\n| AI / DePIN | | | | | |\n| RWA (Real World Assets) | | | | | |\n| Memecoins | | | | | |\n| Layer 2 / Scaling | | | | | |\n| Restaking / LST | | | | | |\n| Gaming / Metaverse | | | | | |\n| DeFi 2.0 / Yield | | | | | |\n| BTC ecosystem (Ordinals, Runes) | | | | | |\n\nFor each narrative:\n1. PHASE — Where are we in the Gartner Hype Cycle? Innovation Trigger → Peak of Inflated Expectations → Trough of Disillusionment → Slope of Enlightenment → Plateau of Productivity\n2. SMART MONEY — Are VCs still investing? Any recent large rounds?\n3. ROTATION — Is money flowing out of one narrative into another? Which one?\n4. RECOMMENDED PLAY — For each narrative in Early/Growth phase: top 3 tokens to buy. For each narrative at Peak: take profits.\n\nSUMMARY: "Right now, the most promising narrative is [X] because [Y]. Avoid [Z] which is in decline phase."', ar:'حلّل السرديات الكريبتو الجارية:\n\nجدول السرديات:\n| السردية | المرحلة (Early / Growth / Peak / Decline / Dead) | الرموز الرائدة | الأداء 30 يوماً | اتجاه TVL | اتجاه الضجة الاجتماعية |\n| AI / DePIN | | | | | |\n| RWA (Real World Assets) | | | | | |\n| Memecoins | | | | | |\n| Layer 2 / Scaling | | | | | |\n| Restaking / LST | | | | | |\n| Gaming / Metaverse | | | | | |\n| DeFi 2.0 / Yield | | | | | |\n| BTC ecosystem (Ordinals, Runes) | | | | | |\n\nلكل سردية:\n1. المرحلة — أين نحن في Gartner Hype Cycle؟ Innovation Trigger ← Peak of Inflated Expectations ← Trough of Disillusionment ← Slope of Enlightenment ← Plateau of Productivity\n2. الأموال الذكية — هل ما زال رأس المال المخاطر يستثمر؟ هل هناك جولات تمويل كبيرة حديثة؟\n3. الدوران — هل تخرج الأموال من سردية لتذهب إلى أخرى؟ أيّها؟\n4. الصفقة الموصى بها — لكل سردية في مرحلة Early/Growth: أفضل 3 رموز للشراء. لكل سردية في Peak: خذ أرباحاً.\n\nالملخص: "حالياً، السردية الأكثر واعدية هي [X] لأن [Y]. تجنّب [Z] التي في مرحلة انحدار."' }
  },
  { num:25, cat:'crypto', numBg:'#fff7ed', numColor:'#ea580c', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Surveillance des whales', en:'Whale watching', ar:'مراقبة الحيتان' },
    badge:{ fr:'🐋 Whales', en:'🐋 Whales', ar:'🐋 حيتان' },
    desc:{ fr:'Les whales (wallets &gt;$10M) sont les insiders de la crypto. Quand ils accumulent, c\'est bullish. Quand ils déposent sur exchange, c\'est bearish. Ce prompt analyse les mouvements on-chain pour détecter l\'accumulation ou la distribution.', en:'Whales (wallets &gt;$10M) are crypto\'s insiders. When they accumulate, it\'s bullish. When they deposit on exchanges, it\'s bearish. This prompt analyzes on-chain movements to detect accumulation or distribution.', ar:'الحيتان (محافظ &gt;$10M) هم الداخليون في عالم الكريبتو. عندما يجمّعون، هذا صعودي. عندما يودعون في المنصات، هذا هبوطي. هذا البرومبت يحلّل الحركات on-chain لكشف التجميع أو التوزيع.' },
    code:{ fr:'Analyse les mouvements des whales sur [TOKEN] :\n\n1. EXCHANGE FLOWS — Inflows vs outflows sur les exchanges centralisés (7 derniers jours) :\n   — Net inflow (dépôts &gt; retraits) = pression vendeuse → BEARISH\n   — Net outflow (retraits &gt; dépôts) = accumulation → BULLISH\n   Quantifie en $ et en % du circulating supply.\n\n2. TOP WALLETS — Activité des 20 plus gros wallets non-exchange :\n   — Combien ont accumulé sur 30 jours ?\n   — Combien ont distribué ?\n   — Y a-t-il de NOUVEAUX wallets &gt;$1M apparus récemment ?\n\n3. SMART MONEY — Les wallets historiquement profitables (early entrants, known VCs) :\n   — Que font-ils en ce moment ? Accumulation, hold, ou vente ?\n   — Y a-t-il des mouvements depuis des wallets de VC connus (a16z, Paradigm, Binance Labs) ?\n\n4. STABLECOIN FLOW — Les stablecoins affluent-ils vers les DEX/CEX ? (dry powder = acheteurs potentiels)\n\n5. LIQUIDATION MAP — À quels niveaux de prix y a-t-il le plus de liquidations long/short en attente ? Le prix est-il attiré vers ces niveaux ?\n\n6. FUNDING RATE — Positif (longs paient les shorts) = marché overleveraged long → risque de squeeze down. Négatif = l\'inverse.\n\nSIGNAL : ☐ Accumulation whale ☐ Distribution ☐ Neutre\nSi accumulation détectée : zone d\'entrée et sizing recommandé.', en:'Analyze whale movements on [TOKEN]:\n\n1. EXCHANGE FLOWS — Inflows vs outflows on centralized exchanges (last 7 days):\n   — Net inflow (deposits &gt; withdrawals) = sell pressure → BEARISH\n   — Net outflow (withdrawals &gt; deposits) = accumulation → BULLISH\n   Quantify in $ and % of circulating supply.\n\n2. TOP WALLETS — Activity of the 20 largest non-exchange wallets:\n   — How many have accumulated over 30 days?\n   — How many have distributed?\n   — Are there NEW wallets &gt;$1M that appeared recently?\n\n3. SMART MONEY — Historically profitable wallets (early entrants, known VCs):\n   — What are they doing right now? Accumulating, holding, or selling?\n   — Any movements from known VC wallets (a16z, Paradigm, Binance Labs)?\n\n4. STABLECOIN FLOW — Are stablecoins flowing toward DEX/CEX? (dry powder = potential buyers)\n\n5. LIQUIDATION MAP — At what price levels are the most long/short liquidations pending? Is price gravitating toward these levels?\n\n6. FUNDING RATE — Positive (longs pay shorts) = market overleveraged long → risk of squeeze down. Negative = the opposite.\n\nSIGNAL: ☐ Whale accumulation ☐ Distribution ☐ Neutral\nIf accumulation detected: entry zone and recommended sizing.', ar:'حلّل حركات الحيتان على [TOKEN]:\n\n1. تدفقات المنصات — التدفقات الداخلة مقابل الخارجة على المنصات المركزية (آخر 7 أيام):\n   — صافي تدفق داخلي (إيداعات &gt; سحوبات) = ضغط بيعي ← هبوطي\n   — صافي تدفق خارجي (سحوبات &gt; إيداعات) = تجميع ← صعودي\n   حدّد بالدولار وبنسبة من العرض المتداول.\n\n2. أكبر المحافظ — نشاط أكبر 20 محفظة غير منصّات:\n   — كم منها جمّع خلال 30 يوماً؟\n   — كم منها وزّع؟\n   — هل ظهرت محافظ جديدة &gt;$1M مؤخراً؟\n\n3. الأموال الذكية — المحافظ المربحة تاريخياً (دخول مبكر، VC معروفون):\n   — ماذا يفعلون الآن؟ تجميع، احتفاظ، أو بيع؟\n   — هل هناك حركات من محافظ VC معروفة (a16z، Paradigm، Binance Labs)؟\n\n4. تدفقات Stablecoin — هل العملات المستقرة تتدفق نحو DEX/CEX؟ (ذخيرة جافة = مشترون محتملون)\n\n5. خريطة التصفيات — عند أي مستويات سعرية يوجد أكبر عدد من تصفيات Long/Short المعلّقة؟ هل السعر منجذب نحو هذه المستويات؟\n\n6. معدل التمويل — إيجابي (المراكز الطويلة تدفع للقصيرة) = السوق مفرط الرافعة على Long ← خطر squeeze هبوطي. سلبي = العكس.\n\nالإشارة: ☐ تجميع حيتان ☐ توزيع ☐ محايد\nإذا كُشف تجميع: منطقة الدخول والحجم الموصى به.' }
  },
  { num:26, cat:'macro', numBg:'#eff6ff', numColor:'#2563eb', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Décryptage réunion Fed/BCE', en:'Fed/ECB meeting decoder', ar:'فك شفرة اجتماع الفيدرالي/المركزي' },
    badge:{ fr:'🏛️ Fed/BCE', en:'🏛️ Fed/ECB', ar:'🏛️ المركزي' },
    desc:{ fr:'Les marchés bougent de 1-3% sur un seul mot changé dans le communiqué de la Fed. Ce prompt force une analyse mot-à-mot du statement vs le précédent et traduit le "Fedspeak" en implications concrètes pour votre portefeuille.', en:'Markets move 1-3% on a single changed word in the Fed statement. This prompt forces a word-by-word analysis of the statement vs the previous one and translates "Fedspeak" into concrete implications for your portfolio.', ar:'الأسواق تتحرك 1-3% بسبب كلمة واحدة تتغيّر في بيان الفيدرالي. هذا البرومبت يفرض تحليلاً كلمة بكلمة للبيان مقارنة بالسابق ويترجم "لغة الفيدرالي" إلى تأثيرات ملموسة على محفظتك.' },
    code:{ fr:'La [FED / BCE / BOJ / BOE] vient de publier sa décision : [TAUX DÉCIDÉ / RÉSUMÉ EN 1 PHRASE].\n\nDÉCRYPTAGE :\n1. DÉCISION vs ATTENTES — Le marché attendait quoi ? (CME FedWatch, consensus). Surprise ou non ?\n\n2. STATEMENT — Quels mots ont CHANGÉ par rapport au dernier communiqué ? Surligne les différences clés. En Fedspeak :\n   — "ongoing" → ils continuent, pas de pivot\n   — "some" au lieu de "modest" → inflexion subtile\n   — "data-dependent" → ils ne savent pas eux-mêmes\n   — Ajout/retrait de "risks are balanced" → signal majeur\n\n3. DOT PLOT (si applicable) — Taux médian attendu à fin d\'année : avant vs maintenant. Le nombre de cuts/hikes pricé a-t-il changé ?\n\n4. CONFÉRENCE DE PRESSE — Qu\'a dit le président que le communiqué ne dit PAS ? Quel journaliste a posé la question qui a fait bouger le marché ?\n\n5. IMPACT IMMÉDIAT — Réaction :\n   | Actif | Mouvement | Interprétation |\n   | S&amp;P 500 | +/- X% | |\n   | Nasdaq | +/- X% | |\n   | 10Y yield | +/- Xbps | |\n   | DXY | +/- X% | |\n   | Or | +/- X% | |\n   | BTC | +/- X% | |\n\n6. POSITIONNEMENT — Comment ajuster mon portefeuille ? Quels secteurs favoriser (utilities si dovish, banks si hawkish) ? Quels trades sont maintenant invalidés ?', en:'The [FED / ECB / BOJ / BOE] just published its decision: [RATE DECIDED / 1-SENTENCE SUMMARY].\n\nDECODER:\n1. DECISION vs EXPECTATIONS — What did the market expect? (CME FedWatch, consensus). Surprise or not?\n\n2. STATEMENT — Which words CHANGED compared to the last statement? Highlight the key differences. In Fedspeak:\n   — "ongoing" → they continue, no pivot\n   — "some" instead of "modest" → subtle inflection\n   — "data-dependent" → they don\'t know themselves\n   — Addition/removal of "risks are balanced" → major signal\n\n3. DOT PLOT (if applicable) — Median expected rate at year-end: before vs now. Has the number of priced-in cuts/hikes changed?\n\n4. PRESS CONFERENCE — What did the chair say that the statement does NOT say? Which journalist asked the question that moved the market?\n\n5. IMMEDIATE IMPACT — Reaction:\n   | Asset | Move | Interpretation |\n   | S&amp;P 500 | +/- X% | |\n   | Nasdaq | +/- X% | |\n   | 10Y yield | +/- Xbps | |\n   | DXY | +/- X% | |\n   | Gold | +/- X% | |\n   | BTC | +/- X% | |\n\n6. POSITIONING — How to adjust my portfolio? Which sectors to favor (utilities if dovish, banks if hawkish)? Which trades are now invalidated?', ar:'[الفيدرالي / البنك المركزي الأوروبي / بنك اليابان / بنك إنجلترا] نشر قراره للتو: [السعر المقرر / ملخص في جملة واحدة].\n\nفك الشفرة:\n1. القرار مقابل التوقعات — ماذا كان السوق يتوقع؟ (CME FedWatch، الإجماع). مفاجأة أم لا؟\n\n2. البيان — أي كلمات تغيّرت مقارنة بالبيان الأخير؟ حدّد الاختلافات الرئيسية. بلغة الفيدرالي:\n   — "ongoing" ← يستمرون، لا تحوّل\n   — "some" بدلاً من "modest" ← انعطاف دقيق\n   — "data-dependent" ← هم أنفسهم لا يعرفون\n   — إضافة/حذف "risks are balanced" ← إشارة كبرى\n\n3. DOT PLOT (إن وُجد) — السعر الوسيط المتوقع نهاية السنة: قبل مقابل الآن. هل تغيّر عدد التخفيضات/الزيادات المسعّرة؟\n\n4. المؤتمر الصحفي — ماذا قال الرئيس ولم يقله البيان؟ أي صحفي طرح السؤال الذي حرّك السوق؟\n\n5. التأثير الفوري — ردة الفعل:\n   | الأصل | الحركة | التفسير |\n   | S&amp;P 500 | +/- X% | |\n   | Nasdaq | +/- X% | |\n   | عائد 10 سنوات | +/- X نقطة أساس | |\n   | DXY | +/- X% | |\n   | الذهب | +/- X% | |\n   | BTC | +/- X% | |\n\n6. التموضع — كيف أعدّل محفظتي؟ أي قطاعات أفضّل (المرافق إذا تيسيري، البنوك إذا تشددي)؟ أي صفقات أصبحت باطلة الآن؟' }
  },
  { num:27, cat:'macro', numBg:'#eff6ff', numColor:'#2563eb', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Radar rotation sectorielle', en:'Sector rotation radar', ar:'رادار الدوران القطاعي' },
    badge:{ fr:'🔄 Rotation', en:'🔄 Rotation', ar:'🔄 دوران' },
    desc:{ fr:'Où on est dans le cycle économique détermine quels secteurs surperforment. Ce prompt identifie la phase actuelle et donne des trades concrets de rotation sectorielle via ETFs.', en:'Where we are in the economic cycle determines which sectors outperform. This prompt identifies the current phase and provides concrete sector rotation trades via ETFs.', ar:'أين نحن في الدورة الاقتصادية يحدد أي القطاعات تتفوّق. هذا البرومبت يحدد المرحلة الحالية ويقدّم صفقات ملموسة للدوران القطاعي عبر ETFs.' },
    code:{ fr:'Analyse la rotation sectorielle en cours :\n\n1. PHASE DU CYCLE — Où sommes-nous ?\n   | Phase | Indicateurs clés | Secteurs leaders | Secteurs retardataires |\n   | Expansion précoce | ISM ↑, taux bas, earnings ↑ | Consumer Disc, Tech, Industrials | Utilities, Healthcare |\n   | Expansion tardive | ISM &gt;55, inflation ↑, taux ↑ | Energy, Materials, Financials | Consumer Disc, Tech |\n   | Contraction | ISM ↓, earnings ↓, spreads ↑ | Healthcare, Utilities, Consumer Staples | Financials, Industrials |\n   | Reprise | ISM ↑ depuis creux, taux ↓ | Tech, Consumer Disc, Real Estate | Energy, Utilities |\n   → Phase actuelle estimée : [X] — Justifie avec ISM, GDP, employment, inflation.\n\n2. PERFORMANCE RELATIVE — Tableau des 11 secteurs S&amp;P 500 :\n   | Secteur | ETF | Perf 1S | Perf 1M | Perf 3M | Relative vs SPY 3M | Flow 30J |\n   Souligne les 3 secteurs qui surperforment le SPY et les 3 qui sous-performent.\n\n3. SIGNAUX DE ROTATION — L\'argent est-il en train de sortir des gagnants pour aller vers les retardataires ? Signes : les leaders ralentissent, les laggards rebondissent, les flows ETF changent.\n\n4. TRADES RECOMMANDÉS — 3 paires long/short sectorielles :\n   | Long (secteur favorisé) | Short (secteur défavorisé) | Instrument | Horizon |\n   Exemple : Long XLE / Short XLK si rotation de tech vers energy.\n\n5. TIMING — Cette rotation est-elle en début ou en fin de course ? Combien de mois reste-t-il typiquement dans cette phase du cycle ?', en:'Analyze the current sector rotation:\n\n1. CYCLE PHASE — Where are we?\n   | Phase | Key Indicators | Leading Sectors | Lagging Sectors |\n   | Early Expansion | ISM ↑, low rates, earnings ↑ | Consumer Disc, Tech, Industrials | Utilities, Healthcare |\n   | Late Expansion | ISM &gt;55, inflation ↑, rates ↑ | Energy, Materials, Financials | Consumer Disc, Tech |\n   | Contraction | ISM ↓, earnings ↓, spreads ↑ | Healthcare, Utilities, Consumer Staples | Financials, Industrials |\n   | Recovery | ISM ↑ from trough, rates ↓ | Tech, Consumer Disc, Real Estate | Energy, Utilities |\n   → Estimated current phase: [X] — Justify with ISM, GDP, employment, inflation.\n\n2. RELATIVE PERFORMANCE — Table of the 11 S&amp;P 500 sectors:\n   | Sector | ETF | 1W Perf | 1M Perf | 3M Perf | Relative vs SPY 3M | 30D Flow |\n   Highlight the 3 sectors outperforming SPY and the 3 underperforming.\n\n3. ROTATION SIGNALS — Is money moving out of winners into laggards? Signs: leaders slowing, laggards bouncing, ETF flows changing.\n\n4. RECOMMENDED TRADES — 3 long/short sector pairs:\n   | Long (favored sector) | Short (unfavored sector) | Instrument | Horizon |\n   Example: Long XLE / Short XLK if rotation from tech to energy.\n\n5. TIMING — Is this rotation in its early or late innings? How many months typically remain in this cycle phase?', ar:'حلّل الدوران القطاعي الجاري:\n\n1. مرحلة الدورة — أين نحن؟\n   | المرحلة | المؤشرات الرئيسية | القطاعات الرائدة | القطاعات المتأخرة |\n   | توسع مبكر | ISM ↑، أسعار منخفضة، أرباح ↑ | استهلاك تقديري، تكنولوجيا، صناعات | مرافق، رعاية صحية |\n   | توسع متأخر | ISM &gt;55، تضخم ↑، أسعار ↑ | طاقة، مواد، مالية | استهلاك تقديري، تكنولوجيا |\n   | انكماش | ISM ↓، أرباح ↓، فوارق ↑ | رعاية صحية، مرافق، استهلاك أساسي | مالية، صناعات |\n   | انتعاش | ISM ↑ من القاع، أسعار ↓ | تكنولوجيا، استهلاك تقديري، عقارات | طاقة، مرافق |\n   ← المرحلة الحالية المقدّرة: [X] — برّر مع ISM، GDP، التوظيف، التضخم.\n\n2. الأداء النسبي — جدول قطاعات S&amp;P 500 الـ 11:\n   | القطاع | ETF | أداء أسبوع | أداء شهر | أداء 3 أشهر | نسبي مقابل SPY 3 أشهر | التدفقات 30 يوماً |\n   حدّد 3 قطاعات تتفوق على SPY و3 تتأخر.\n\n3. إشارات الدوران — هل تخرج الأموال من الرابحين نحو المتأخرين؟ العلامات: الرائدون يتباطأون، المتأخرون ينتعشون، تدفقات ETF تتغيّر.\n\n4. الصفقات الموصى بها — 3 أزواج long/short قطاعية:\n   | Long (قطاع مفضّل) | Short (قطاع غير مفضّل) | الأداة | الأفق |\n   مثال: Long XLE / Short XLK إذا دوران من التقنية نحو الطاقة.\n\n5. التوقيت — هل هذا الدوران في بدايته أم نهايته؟ كم شهراً يبقى عادةً في هذه المرحلة من الدورة؟' }
  },
  { num:28, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Analyse IPO / Direct listing', en:'IPO / Direct listing analysis', ar:'تحليل الطرح العام (IPO)' },
    badge:{ fr:'🆕 IPO', en:'🆕 IPO', ar:'🆕 طرح' },
    desc:{ fr:'80% des IPOs sous-performent le S&amp;P 500 à 1 an. Ce prompt identifie les 20% qui valent le coup en cherchant les red flags dans le S-1 et en comparant la valorisation demandée aux peers cotés.', en:'80% of IPOs underperform the S&amp;P 500 at 1 year. This prompt identifies the 20% that are worth it by looking for red flags in the S-1 and comparing the requested valuation to listed peers.', ar:'80% من الطروحات الأولية تتأخر عن S&amp;P 500 بعد عام. هذا البرومبت يحدد الـ 20% التي تستحق من خلال البحث عن إشارات الخطر في ملف S-1 ومقارنة التقييم المطلوب بالنظراء المدرجين.' },
    code:{ fr:'[ENTREPRISE] entre en bourse : [IPO / SPAC / Direct listing]. Prix estimé : $[X]. Valorisation demandée : $[Y]B.\n\nANALYSE IPO :\n1. BUSINESS — CA : $[X]M. Croissance : [Y%]. Marge brute : [Z%]. EBITDA positif ? FCF positif ? TAM revendiqué vs TAM réaliste.\n\n2. VALORISATION vs PEERS — Tableau :\n   | Métrique | [IPO] | Peer coté 1 | Peer coté 2 | Peer coté 3 |\n   | P/S | | | | |\n   | EV/Revenue | | | | |\n   | Croissance CA | | | | |\n   L\'IPO demande-t-elle une prime de [X%] vs les pairs ? Est-ce justifié ?\n\n3. RED FLAGS S-1 — Cherche spécifiquement :\n   ☐ Dual-class shares (fondateur garde le contrôle → mauvais pour les minoritaires)\n   ☐ Related-party transactions (le fondateur se paie via des entités liées)\n   ☐ Customer concentration (&gt;30% du CA = 1 client = risque)\n   ☐ Stock-based compensation &gt; 20% du CA (dilution massive)\n   ☐ Cash burn rate vs IPO proceeds (combien de temps avant la prochaine levée ?)\n   ☐ Perte nette qui s\'aggrave (pas la même chose qu\'une startup en croissance)\n\n4. LOCK-UP — Date d\'expiration : [DATE]. Volume estimé de ventes insiders à l\'unlock : [X]M d\'actions ([Y%] du float). Impact potentiel sur le cours.\n\n5. HISTORIQUE SECTEUR — Performance médiane des IPOs du même secteur : J+1, J+30, J+90, J+180, 1 an. Le track record est-il positif ?\n\n6. VERDICT — ☐ Participer à l\'IPO ☐ Acheter le premier pullback ☐ Attendre le lock-up expiry ☐ Éviter\nSi participer : allocation max en % du portefeuille et prix d\'entrée max.', en:'[COMPANY] is going public: [IPO / SPAC / Direct listing]. Estimated price: $[X]. Requested valuation: $[Y]B.\n\nIPO ANALYSIS:\n1. BUSINESS — Revenue: $[X]M. Growth: [Y%]. Gross margin: [Z%]. EBITDA positive? FCF positive? Claimed TAM vs realistic TAM.\n\n2. VALUATION vs PEERS — Table:\n   | Metric | [IPO] | Listed Peer 1 | Listed Peer 2 | Listed Peer 3 |\n   | P/S | | | | |\n   | EV/Revenue | | | | |\n   | Revenue Growth | | | | |\n   Is the IPO asking for a [X%] premium vs peers? Is it justified?\n\n3. S-1 RED FLAGS — Look specifically for:\n   ☐ Dual-class shares (founder keeps control → bad for minority shareholders)\n   ☐ Related-party transactions (founder pays themselves through related entities)\n   ☐ Customer concentration (&gt;30% of revenue = 1 customer = risk)\n   ☐ Stock-based compensation &gt; 20% of revenue (massive dilution)\n   ☐ Cash burn rate vs IPO proceeds (how long before the next raise?)\n   ☐ Net loss worsening (not the same as a growth-stage startup)\n\n4. LOCK-UP — Expiration date: [DATE]. Estimated volume of insider sales at unlock: [X]M shares ([Y%] of float). Potential price impact.\n\n5. SECTOR TRACK RECORD — Median performance of same-sector IPOs: Day+1, Day+30, Day+90, Day+180, 1 year. Is the track record positive?\n\n6. VERDICT — ☐ Participate in IPO ☐ Buy the first pullback ☐ Wait for lock-up expiry ☐ Avoid\nIf participating: max allocation as % of portfolio and max entry price.', ar:'[الشركة] تُدرج في البورصة: [IPO / SPAC / Direct listing]. السعر المقدّر: $[X]. التقييم المطلوب: $[Y]B.\n\nتحليل الطرح العام:\n1. النشاط — الإيرادات: $[X]M. النمو: [Y%]. الهامش الإجمالي: [Z%]. EBITDA إيجابي؟ FCF إيجابي؟ TAM المعلن مقابل TAM الواقعي.\n\n2. التقييم مقابل النظراء — جدول:\n   | المقياس | [الطرح] | نظير مدرج 1 | نظير مدرج 2 | نظير مدرج 3 |\n   | P/S | | | | |\n   | EV/Revenue | | | | |\n   | نمو الإيرادات | | | | |\n   هل يطلب الطرح علاوة [X%] مقابل النظراء؟ هل هي مبرّرة؟\n\n3. إشارات الخطر S-1 — ابحث تحديداً عن:\n   ☐ أسهم مزدوجة التصويت (المؤسس يحتفظ بالسيطرة ← سيئ للأقلية)\n   ☐ معاملات مع أطراف ذات صلة (المؤسس يدفع لنفسه عبر كيانات مرتبطة)\n   ☐ تركّز العملاء (&gt;30% من الإيرادات = عميل واحد = خطر)\n   ☐ تعويضات الأسهم &gt; 20% من الإيرادات (تخفيف ضخم)\n   ☐ معدل الحرق النقدي مقابل عائدات الطرح (كم من الوقت قبل الجولة التالية؟)\n   ☐ خسارة صافية تتفاقم (ليس نفس الشيء كشركة ناشئة في نمو)\n\n4. فترة الحظر — تاريخ الانتهاء: [التاريخ]. الحجم المقدّر لمبيعات الداخليين عند فتح الحظر: [X]M سهم ([Y%] من الأسهم الحرة). التأثير المحتمل على السعر.\n\n5. تاريخ القطاع — الأداء الوسيط للطروحات من نفس القطاع: J+1، J+30، J+90، J+180، سنة واحدة. هل السجل إيجابي؟\n\n6. الحكم — ☐ المشاركة في الطرح ☐ الشراء عند أول تراجع ☐ الانتظار حتى انتهاء فترة الحظر ☐ تجنّب\nإذا المشاركة: التوزيع الأقصى كنسبة من المحفظة وأقصى سعر دخول.' }
  },
  { num:29, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Constructeur de stratégie options', en:'Options strategy builder', ar:'باني استراتيجيات الخيارات' },
    badge:{ fr:'🎛️ Options', en:'🎛️ Options', ar:'🎛️ خيارات' },
    desc:{ fr:'Arrête de deviner quelle stratégie options utiliser. Ce prompt prend ton scénario (bullish/bearish/neutre, vol chère/cheap) et te donne la structure optimale avec Greeks, P&amp;L et breakevens.', en:'Stop guessing which options strategy to use. This prompt takes your scenario (bullish/bearish/neutral, expensive/cheap vol) and gives you the optimal structure with Greeks, P&amp;L and breakevens.', ar:'توقّف عن التخمين أي استراتيجية خيارات تستخدم. هذا البرومبت يأخذ سيناريوك (صعودي/هبوطي/محايد، تقلب غالٍ/رخيص) ويعطيك الهيكل الأمثل مع Greeks وP&amp;L ونقاط التعادل.' },
    code:{ fr:'CONTEXTE :\n— Ticker : [TICKER] à $[PRIX]\n— Ma vue : [BULLISH / BEARISH / NEUTRE / VOLATILITÉ]\n— Horizon : [1 semaine / 1 mois / 3 mois / 6 mois]\n— Budget max : $[MONTANT]\n— Objectif : [revenus (Theta) / protection (hedge) / levier directionnel / volatilité pure]\n— IV actuelle : [haute / basse / normale] (ou IV Rank : [X%])\n\nRECOMMANDATION :\n1. STRATÉGIE — Quelle structure ?\n   — Vue bullish + vol chère → Bull put spread ou short put\n   — Vue bullish + vol cheap → Long call ou call debit spread\n   — Vue bearish + vol chère → Bear call spread ou short call\n   — Vue bearish + vol cheap → Long put ou put debit spread\n   — Vue neutre + vol chère → Iron condor, short straddle, short strangle\n   — Pure vol → Long straddle / strangle\n\n2. LEGS CONCRETS — Tableau :\n   | Leg | Type | Strike | Expiration | Prime | Action (Buy/Sell) |\n   Total débit/crédit net : $[X]\n\n3. GREEKS — Delta, Gamma, Theta, Vega de la position totale. Qu\'est-ce que ça veut dire concrètement ? (ex: "Theta = +$15/jour → vous gagnez $15 chaque jour si le prix ne bouge pas")\n\n4. P&amp;L — Profit max : $[X] (+Y%). Perte max : $[X] (-Y%). Breakeven(s) : $[X].\n\n5. SCÉNARIOS — Si le titre dans 30 jours est à :\n   | Prix | P&amp;L | % | Action |\n   | -10% | | | |\n   | -5% | | | |\n   | Flat | | | |\n   | +5% | | | |\n   | +10% | | | |\n\n6. GESTION — Quand prendre les profits ? (règle : 50% du profit max pour les crédits). Quand couper ? Quand rouler ?', en:'CONTEXT:\n— Ticker: [TICKER] at $[PRICE]\n— My view: [BULLISH / BEARISH / NEUTRAL / VOLATILITY]\n— Horizon: [1 week / 1 month / 3 months / 6 months]\n— Max budget: $[AMOUNT]\n— Goal: [income (Theta) / protection (hedge) / directional leverage / pure volatility]\n— Current IV: [high / low / normal] (or IV Rank: [X%])\n\nRECOMMENDATION:\n1. STRATEGY — Which structure?\n   — Bullish view + expensive vol → Bull put spread or short put\n   — Bullish view + cheap vol → Long call or call debit spread\n   — Bearish view + expensive vol → Bear call spread or short call\n   — Bearish view + cheap vol → Long put or put debit spread\n   — Neutral view + expensive vol → Iron condor, short straddle, short strangle\n   — Pure vol → Long straddle / strangle\n\n2. CONCRETE LEGS — Table:\n   | Leg | Type | Strike | Expiration | Premium | Action (Buy/Sell) |\n   Total net debit/credit: $[X]\n\n3. GREEKS — Delta, Gamma, Theta, Vega of the total position. What does it mean concretely? (e.g.: "Theta = +$15/day → you earn $15 each day if price doesn\'t move")\n\n4. P&amp;L — Max profit: $[X] (+Y%). Max loss: $[X] (-Y%). Breakeven(s): $[X].\n\n5. SCENARIOS — If the stock in 30 days is at:\n   | Price | P&amp;L | % | Action |\n   | -10% | | | |\n   | -5% | | | |\n   | Flat | | | |\n   | +5% | | | |\n   | +10% | | | |\n\n6. MANAGEMENT — When to take profits? (rule: 50% of max profit for credits). When to cut? When to roll?', ar:'السياق:\n— السهم: [TICKER] عند $[السعر]\n— رأيي: [BULLISH / BEARISH / محايد / تقلّب]\n— الأفق: [أسبوع / شهر / 3 أشهر / 6 أشهر]\n— الميزانية القصوى: $[المبلغ]\n— الهدف: [دخل (Theta) / حماية (hedge) / رافعة اتجاهية / تقلّب بحت]\n— IV الحالية: [عالية / منخفضة / عادية] (أو IV Rank: [X%])\n\nالتوصية:\n1. الاستراتيجية — أي هيكل؟\n   — رؤية صعودية + تقلب غالٍ ← Bull put spread أو short put\n   — رؤية صعودية + تقلب رخيص ← Long call أو call debit spread\n   — رؤية هبوطية + تقلب غالٍ ← Bear call spread أو short call\n   — رؤية هبوطية + تقلب رخيص ← Long put أو put debit spread\n   — رؤية محايدة + تقلب غالٍ ← Iron condor، short straddle، short strangle\n   — تقلّب بحت ← Long straddle / strangle\n\n2. الأطراف الفعلية — جدول:\n   | الطرف | النوع | Strike | الاستحقاق | العلاوة | الإجراء (Buy/Sell) |\n   إجمالي الخصم/الائتمان الصافي: $[X]\n\n3. GREEKS — Delta، Gamma، Theta، Vega للمركز الإجمالي. ماذا يعني ذلك عملياً؟ (مثال: "Theta = +$15/يوم ← تربح $15 كل يوم إذا لم يتحرك السعر")\n\n4. P&amp;L — الربح الأقصى: $[X] (+Y%). الخسارة القصوى: $[X] (-Y%). نقطة/نقاط التعادل: $[X].\n\n5. السيناريوهات — إذا كان السهم بعد 30 يوماً عند:\n   | السعر | P&amp;L | % | الإجراء |\n   | -10% | | | |\n   | -5% | | | |\n   | ثابت | | | |\n   | +5% | | | |\n   | +10% | | | |\n\n6. الإدارة — متى تأخذ الأرباح؟ (قاعدة: 50% من الربح الأقصى للائتمانات). متى تقطع؟ متى تُدحرج؟' }
  },
  { num:30, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'ETF X-ray : radiographie complète', en:'ETF X-ray: full breakdown', ar:'أشعة سينية للصناديق (ETF X-ray)' },
    badge:{ fr:'🔎 X-Ray', en:'🔎 X-Ray', ar:'🔎 أشعة' },
    desc:{ fr:'Vous achetez un ETF sans savoir ce qu\'il y a dedans ? Ce prompt décompose les holdings, identifie les concentrations cachées, calcule le chevauchement avec vos positions existantes, et propose des alternatives moins chères.', en:'You\'re buying an ETF without knowing what\'s inside? This prompt breaks down the holdings, identifies hidden concentrations, calculates overlap with your existing positions, and suggests cheaper alternatives.', ar:'هل تشتري ETF دون معرفة ما بداخله؟ هذا البرومبت يفكّك المكونات، يحدد التركّزات المخفية، يحسب التداخل مع مراكزك الحالية، ويقترح بدائل أرخص.' },
    code:{ fr:'[ETF TICKER] — Radiographie complète :\n\n1. COMPOSITION — Top 10 holdings avec % du fonds :\n   | Rang | Ticker | Nom | % du fonds | Secteur |\n   Concentration du top 10 : [X%] (si &gt;40% → fausse diversification)\n\n2. RÉPARTITION — Sectorielle, géographique, par taille (large/mid/small cap). Y a-t-il un biais caché ? (ex: un ETF "monde" qui est 65% US)\n\n3. OVERLAP — Si j\'ai déjà [MES POSITIONS], quel chevauchement avec cet ETF ?\n   | Position existante | Aussi dans l\'ETF ? | % dans l\'ETF |\n   Si overlap &gt; 30% → l\'ETF n\'apporte pas de diversification réelle.\n\n4. COÛTS — TER : [X%]. Spread bid/ask moyen : [X%]. Tracking error vs indice : [X%]. Coût total réel annuel.\n\n5. ALTERNATIVES — 3 ETFs concurrents qui répliquent le même indice ou thème :\n   | ETF | TER | AUM | Perf 1Y | Avantage |\n   Y en a-t-il un strictement meilleur (moins cher, plus liquide, même perf) ?\n\n6. LIQUIDITÉ — AUM : $[X]B. Volume quotidien moyen : [X] actions. Spread moyen : [X]%. Si AUM &lt; $100M ou volume &lt; 50K → risque de liquidité et de fermeture.\n\n7. FISCALITÉ — Domicile du fonds (Irlande, Luxembourg, US) → impact sur la retenue à la source des dividendes. Pour un investisseur [PAYS], quel domicile est le plus avantageux ?\n\nVERDICT : ☐ Recommandé ☐ Acceptable ☐ Il y a mieux ☐ Éviter (frais trop élevés / trop concentré / illiquide)', en:'[ETF TICKER] — Full breakdown:\n\n1. COMPOSITION — Top 10 holdings with % of fund:\n   | Rank | Ticker | Name | % of Fund | Sector |\n   Top 10 concentration: [X%] (if &gt;40% → false diversification)\n\n2. ALLOCATION — By sector, geography, and size (large/mid/small cap). Is there a hidden bias? (e.g.: a "world" ETF that is 65% US)\n\n3. OVERLAP — If I already own [MY POSITIONS], what overlap with this ETF?\n   | Existing Position | Also in ETF? | % in ETF |\n   If overlap &gt; 30% → the ETF does not provide real diversification.\n\n4. COSTS — TER: [X%]. Average bid/ask spread: [X%]. Tracking error vs index: [X%]. True total annual cost.\n\n5. ALTERNATIVES — 3 competing ETFs replicating the same index or theme:\n   | ETF | TER | AUM | 1Y Perf | Advantage |\n   Is there one that is strictly better (cheaper, more liquid, same performance)?\n\n6. LIQUIDITY — AUM: $[X]B. Average daily volume: [X] shares. Average spread: [X%]. If AUM &lt; $100M or volume &lt; 50K → liquidity and closure risk.\n\n7. TAX DOMICILE — Fund domicile (Ireland, Luxembourg, US) → impact on dividend withholding tax. For a [COUNTRY] investor, which domicile is most advantageous?\n\nVERDICT: ☐ Recommended ☐ Acceptable ☐ There\'s better ☐ Avoid (fees too high / too concentrated / illiquid)', ar:'[ETF TICKER] — فحص شامل:\n\n1. التركيبة — أكبر 10 مكونات مع نسبة الصندوق:\n   | الترتيب | السهم | الاسم | % من الصندوق | القطاع |\n   تركّز أكبر 10: [X%] (إذا &gt;40% ← تنويع وهمي)\n\n2. التوزيع — قطاعي، جغرافي، حسب الحجم (large/mid/small cap). هل يوجد تحيّز مخفي؟ (مثال: ETF "عالمي" يحتوي 65% أمريكي)\n\n3. التداخل — إذا كانت لدي بالفعل [مراكزي]، ما التداخل مع هذا الصندوق؟\n   | المركز الحالي | موجود في الصندوق أيضاً؟ | % في الصندوق |\n   إذا التداخل &gt; 30% ← الصندوق لا يضيف تنويعاً حقيقياً.\n\n4. التكاليف — TER: [X%]. فارق العرض/الطلب المتوسط: [X%]. خطأ التتبع مقابل المؤشر: [X%]. التكلفة الإجمالية الحقيقية السنوية.\n\n5. البدائل — 3 صناديق منافسة تكرّر نفس المؤشر أو الموضوع:\n   | الصندوق | TER | AUM | الأداء سنة | الميزة |\n   هل يوجد صندوق أفضل بشكل صارم (أرخص، أكثر سيولة، نفس الأداء)؟\n\n6. السيولة — AUM: $[X]B. متوسط الحجم اليومي: [X] سهم. الفارق المتوسط: [X%]. إذا كان AUM &lt; $100M أو الحجم &lt; 50K ← خطر سيولة وإغلاق.\n\n7. الضرائب — مقر الصندوق (أيرلندا، لوكسمبورغ، أمريكا) ← التأثير على الاستقطاع الضريبي على الأرباح الموزعة. لمستثمر في [البلد]، أي مقر هو الأفضل؟\n\nالحكم: ☐ موصى به ☐ مقبول ☐ يوجد أفضل ☐ تجنّب (رسوم مرتفعة / مركّز جداً / غير سائل)' }
  }
,
  { num:31, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Scanner quotidien 10 setups', en:'Daily scanner: 10 setups', ar:'الماسح اليومي: 10 صفقات' },
    badge:{ fr:'🎯 Scanner', en:'🎯 Scanner', ar:'🎯 ماسح' },
    desc:{ fr:'Reproduis la méthode du scanner DailyTickers : 10 setups A+ diversifiés (US + EU + APAC + ETF). Chaque setup avec entry/stop/TP et score de confluence technique. Le secret ? Combiner 3+ signaux.', en:'Reproduce the DailyTickers scanner method: 10 A+ diversified setups (US + EU + APAC + ETF). Each setup with entry/stop/TP and technical confluence score. The secret? Combine 3+ signals.', ar:'أعد إنتاج طريقة ماسح DailyTickers: 10 صفقات A+ متنوعة (أمريكا + أوروبا + آسيا + ETF). كل صفقة بدخول/وقف/هدف ودرجة تقاطع فني. السر؟ دمج 3+ إشارات.' },
    code:{ fr:'Scanne le marché et trouve-moi 10 setups A+ pour aujourd\'hui.\n\nCRITÈRES DE SÉLECTION :\n— Score composite ≥ 85/100\n— Confluence technique ≥ 3 signaux parmi : RSI oversold/overbought, MACD cross, volume surge (>2x avg), prix sur support/résistance clé, breakout pattern\n— Diversification : min 5 US + 2 EU + 1 APAC + 2 ETFs\n\nPour chaque setup :\n| # | Ticker | Stratégie | Score | Entry | Stop | TP1 | TP2 | R:R |\n\nPour CHAQUE setup, détaille :\n1. Thèse (3 phrases max)\n2. Signaux de confluence (liste)\n3. Catalyseur à venir (date si possible)\n4. Risque principal\n\nFiltres d\'exclusion :\n— Pas de penny stocks (< $5)\n— Volume moyen > 500K/jour\n— Pas de tickers en earnings cette semaine (risque de gap)\n\nConclus par un résumé : régime de marché détecté (Risk-On/Off/Neutre), biais global, % de setups longs vs shorts.', en:'Scan the market and find me 10 A+ setups for today.\n\nSELECTION CRITERIA:\n— Composite score ≥ 85/100\n— Technical confluence ≥ 3 signals from: RSI oversold/overbought, MACD cross, volume surge (>2x avg), price at key support/resistance, breakout pattern\n— Diversification: min 5 US + 2 EU + 1 APAC + 2 ETFs\n\nFor each setup:\n| # | Ticker | Strategy | Score | Entry | Stop | TP1 | TP2 | R:R |\n\nFor EACH setup, detail:\n1. Thesis (3 sentences max)\n2. Confluence signals (list)\n3. Upcoming catalyst (date if possible)\n4. Main risk\n\nExclusion filters:\n— No penny stocks (< $5)\n— Average volume > 500K/day\n— No tickers reporting earnings this week (gap risk)\n\nConclude with a summary: detected market regime (Risk-On/Off/Neutral), overall bias, % of long vs short setups.', ar:'امسح السوق وأوجد لي 10 صفقات A+ لليوم.\n\nمعايير الاختيار:\n— درجة مركبة ≥ 85/100\n— تقاطع فني ≥ 3 إشارات من: RSI، MACD، حجم مرتفع (أكثر من 2x المتوسط)، سعر على دعم/مقاومة رئيسية، نمط اختراق\n— تنويع: حد أدنى 5 أمريكية + 2 أوروبية + 1 آسيوية + 2 ETF\n\nلكل صفقة:\n| # | السهم | الاستراتيجية | الدرجة | الدخول | الوقف | الهدف1 | الهدف2 | R:R |\n\nلكل صفقة بالتفصيل:\n1. الأطروحة (3 جمل كحد أقصى)\n2. إشارات التقاطع (قائمة)\n3. محفّز قادم (التاريخ إن أمكن)\n4. الخطر الرئيسي' }
  },
  { num:32, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Swing trade en 5 étapes', en:'Swing trade in 5 steps', ar:'صفقة سوينغ في 5 خطوات' },
    badge:{ fr:'🔥 Swing', en:'🔥 Swing', ar:'🔥 سوينغ' },
    desc:{ fr:'Plan de swing trade complet : de l\'identification du setup au money management. Horizon 2-15 jours. La clé ? Ne jamais entrer sans stop ET sans target.', en:'Complete swing trade plan: from setup identification to money management. 2-15 day horizon. The key? Never enter without a stop AND a target.', ar:'خطة سوينغ كاملة: من تحديد الصفقة إلى إدارة الأموال. أفق 2-15 يوماً. المفتاح؟ لا تدخل أبداً بدون وقف وهدف.' },
    code:{ fr:'[TICKER] à $[PRIX]. Je veux construire un swing trade (2-15 jours).\n\nÉTAPE 1 — SETUP\n- Pattern identifié ? (flag, triangle, double bottom, breakout, pullback sur EMA)\n- Confluences : RSI, MACD, volume, position vs EMAs 20/50/200\n- Le setup est-il mûr ou prématuré ?\n\nÉTAPE 2 — PLAN D\'ENTRÉE\n- Zone d\'entrée : $[X] à $[Y] (pas un prix unique — une zone)\n- Type d\'ordre : limit, stop-limit, ou market ?\n- Entrée échelonnée ? (50% immédiat + 50% sur pullback)\n\nÉTAPE 3 — GESTION DU RISQUE\n- Stop Loss : $[X] (justification technique : sous le support/EMA/pattern)\n- Risque en $ et en % du portefeuille (max 2% du capital par trade)\n- TP1 : $[X] (résistance/target intermédiaire) — alléger 50%\n- TP2 : $[X] (target final) — sortir le reste\n- R:R minimum : 1.5:1\n\nÉTAPE 4 — CATALYSEURS & TIMING\n- Y a-t-il un catalyseur dans les 15 jours ? (earnings, FDA, FOMC, ex-div)\n- Meilleur jour pour entrer (éviter lundi matin, vendredi après-midi)\n- Beta du titre : ajuster le sizing en conséquence\n\nÉTAPE 5 — JOURNAL\n- Setup : [type] | Conviction : [1-10] | Sizing : [%] | Horizon : [X jours]\n- Signaux d\'invalidation : liste de 3 conditions qui annulent le trade', en:'[TICKER] at $[PRICE]. I want to build a swing trade (2-15 days).\n\nSTEP 1 — SETUP\n- Pattern identified? (flag, triangle, double bottom, breakout, pullback to EMA)\n- Confluences: RSI, MACD, volume, position vs 20/50/200 EMAs\n- Is the setup ripe or premature?\n\nSTEP 2 — ENTRY PLAN\n- Entry zone: $[X] to $[Y] (not a single price — a zone)\n- Order type: limit, stop-limit, or market?\n- Scaled entry? (50% immediate + 50% on pullback)\n\nSTEP 3 — RISK MANAGEMENT\n- Stop Loss: $[X] (technical justification: below support/EMA/pattern)\n- Risk in $ and as % of portfolio (max 2% of capital per trade)\n- TP1: $[X] (intermediate resistance/target) — trim 50%\n- TP2: $[X] (final target) — exit the rest\n- Minimum R:R: 1.5:1\n\nSTEP 4 — CATALYSTS & TIMING\n- Is there a catalyst within 15 days? (earnings, FDA, FOMC, ex-div)\n- Best day to enter (avoid Monday morning, Friday afternoon)\n- Stock beta: adjust sizing accordingly\n\nSTEP 5 — JOURNAL\n- Setup: [type] | Conviction: [1-10] | Sizing: [%] | Horizon: [X days]\n- Invalidation signals: list 3 conditions that cancel the trade', ar:'[TICKER] عند $[السعر]. أريد بناء صفقة سوينغ (2-15 يوماً).\n\nالخطوة 1 — الإعداد\n- النمط المحدد؟ (flag، مثلث، قاع مزدوج، اختراق، تراجع على EMA)\n- التقاطعات: RSI، MACD، الحجم، الموقع مقابل EMAs 20/50/200\n\nالخطوة 2 — خطة الدخول\n- منطقة الدخول: $[X] إلى $[Y]\n- نوع الأمر: limit، stop-limit، أو market؟\n\nالخطوة 3 — إدارة المخاطر\n- وقف الخسارة: $[X]\n- TP1: $[X] — تخفيف 50%\n- TP2: $[X] — خروج الباقي\n- R:R أدنى: 1.5:1\n\nالخطوة 4 — المحفزات والتوقيت\n\nالخطوة 5 — التسجيل' }
  },
  { num:33, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Radar social & manipulation', en:'Social radar & manipulation', ar:'رادار اجتماعي وتلاعب' },
    badge:{ fr:'🕵️ Detect', en:'🕵️ Detect', ar:'🕵️ كشف' },
    desc:{ fr:'Détecte les pump & dump, les campagnes coordonnées et l\'activité suspecte. Analyse StockTwits, Reddit, X/Twitter. Si ça sent le piège, ce prompt le dira.', en:'Detect pump & dump, coordinated campaigns and suspicious activity. Analyzes StockTwits, Reddit, X/Twitter. If it smells like a trap, this prompt will say so.', ar:'اكشف pump & dump والحملات المنسقة والنشاط المشبوه. يحلل StockTwits وReddit وX/Twitter. إذا كانت فخاً، هذا البرومبت سيكشفه.' },
    code:{ fr:'[TICKER] buzz sur les réseaux sociaux. Analyse le sentiment social et détecte les manipulations potentielles :\n\n1. VOLUME SOCIAL — Mentions sur StockTwits (24h, 7j, tendance). Posts Reddit (r/wallstreetbets, r/stocks). Tweets $[TICKER] — volume vs moyenne historique.\n2. QUALITÉ vs QUANTITÉ — Les posts sont-ils de vrais analyses ou du spam ? Ratio de comptes créés < 30 jours. Patterns de bot (même message copié, timing suspect).\n3. INFLUENCEURS — Qui parle de ce ticker ? Track record de leurs recommandations passées. Sont-ils rémunérés ? (disclosure oblig SEC).\n4. SENTIMENT SCORE — Bullish/Bearish/Neutre en %. Changement sur 7 jours. Le sentiment est-il en avance ou en retard sur le prix ?\n5. RED FLAGS MANIPULATION :\n☐ Volume social explose alors que le prix stagne (= accumulation pré-pump)\n☐ Comptes < 30j constituent > 30% des posts\n☐ Messages identiques copiés-collés sur plusieurs plateformes\n☐ Influenceur connu pour pump & dump\n☐ Options unusuelles OTM calls juste avant le buzz\n☐ Insider selling pendant que le social monte\n\nSCORE MANIPULATION : 0-6 red flags\n0-1: Sentiment organique → trade possible\n2-3: Suspect → réduire sizing, stop très serré\n4+: Manipulation probable → NE PAS TOUCHER', en:'[TICKER] is buzzing on social media. Analyze social sentiment and detect potential manipulation:\n\n1. SOCIAL VOLUME — StockTwits mentions (24h, 7d, trend). Reddit posts (r/wallstreetbets, r/stocks). Tweets $[TICKER] — volume vs historical average.\n2. QUALITY vs QUANTITY — Are posts real analysis or spam? Ratio of accounts created < 30 days. Bot patterns (same message copied, suspicious timing).\n3. INFLUENCERS — Who is talking about this ticker? Track record of their past recommendations. Are they paid? (SEC disclosure required).\n4. SENTIMENT SCORE — Bullish/Bearish/Neutral in %. Change over 7 days. Is sentiment leading or lagging price?\n5. MANIPULATION RED FLAGS:\n☐ Social volume exploding while price stagnates (= pre-pump accumulation)\n☐ Accounts < 30d make up > 30% of posts\n☐ Identical messages copy-pasted across platforms\n☐ Influencer known for pump & dump\n☐ Unusual OTM call options just before the buzz\n☐ Insider selling while social is rising\n\nMANIPULATION SCORE: 0-6 red flags\n0-1: Organic sentiment → trade possible\n2-3: Suspect → reduce sizing, very tight stop\n4+: Likely manipulation → DO NOT TOUCH', ar:'[TICKER] يثير ضجة على وسائل التواصل. حلّل المعنويات الاجتماعية واكشف التلاعب المحتمل:\n\n1. الحجم الاجتماعي — إشارات StockTwits (24 ساعة، 7 أيام، الاتجاه). منشورات Reddit. تغريدات $[TICKER].\n2. الجودة مقابل الكمية — هل المنشورات تحليل حقيقي أم spam؟ نسبة الحسابات التي عمرها أقل من 30 يوماً.\n3. المؤثرون — من يتحدث عن هذا السهم؟ سجل توصياتهم السابقة.\n4. درجة المعنويات — صعودي/هبوطي/محايد بالنسبة المئوية.\n5. علامات التلاعب الحمراء:\n☐ الحجم الاجتماعي ينفجر بينما السعر راكد\n☐ حسابات عمرها أقل من 30 يوماً تشكل أكثر من 30% من المنشورات\n☐ رسائل متطابقة منسوخة عبر منصات متعددة\n☐ مؤثر معروف بـ pump & dump\n☐ خيارات OTM calls غير عادية قبل الضجة\n\nدرجة التلاعب: 0-6\n0-1: عضوي → التداول ممكن\n2-3: مشبوه → حجم أصغر، وقف ضيق جداً\n4+: تلاعب محتمل → لا تقترب' }
  },
  { num:34, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Estimation du plancher', en:'Bottom estimation', ar:'تقدير القاع' },
    badge:{ fr:'📉 Floor', en:'📉 Floor', ar:'📉 القاع' },
    desc:{ fr:'5 méthodes pour estimer le plancher d\'un titre en chute libre. Book value, tangible assets, 52-week stats, support technique, coût moyen des institutions. Indispensable avant un "buy the dip".', en:'5 methods to estimate the floor of a stock in freefall. Book value, tangible assets, 52-week stats, technical support, institutional average cost. Essential before any "buy the dip".', ar:'5 طرق لتقدير قاع سهم في سقوط حر. القيمة الدفترية، الأصول الملموسة، إحصائيات 52 أسبوعاً، الدعم الفني، متوسط تكلفة المؤسسات.' },
    code:{ fr:'[TICKER] a chuté de [X%]. Estime le plancher avec 5 méthodes :\n\n1. BOOK VALUE — Valeur comptable par action. Le titre trade-t-il sous sa book value ? Si oui, c\'est un signal fort (sauf si le business se dégrade).\n2. TANGIBLE BOOK VALUE — Retire les intangibles (goodwill, brevets). Prix plancher "liquidation" = actifs tangibles - dettes totales.\n3. 52-WEEK ANALYSIS — Low 52 sem : $[X]. -1 écart-type : $[X]. -2 écarts-types : $[X]. Historiquement, combien de fois le titre a rebondi à ces niveaux ?\n4. SUPPORTS TECHNIQUES — Support EMA 200 : $[X]. Support Fibonacci (61.8% retracement) : $[X]. Volume Profile POC : $[X]. Zone d\'accumulation visible ?\n5. COÛT INSTITUTIONNEL — Prix moyen d\'achat des institutions (proxy via 13F). Si le cours est sous ce niveau, les institutions sont en perte → pression vendeuse OU opportunité si le business est sain.\n\nSYNTHÈSE :\n| Méthode | Plancher estimé | Fiabilité |\n|---------|----------------|-----------|\n| Book Value | $[X] | [haute/moyenne/basse] |\n| Tangible BV | $[X] | |\n| -2σ (52W) | $[X] | |\n| Support technique | $[X] | |\n| Coût institutionnel | $[X] | |\n\nZone d\'achat recommandée : $[X] à $[Y] avec sizing progressif (33%/33%/33%).', en:'[TICKER] has dropped [X%]. Estimate the floor using 5 methods:\n\n1. BOOK VALUE — Book value per share. Is the stock trading below book value? If yes, strong signal (unless the business is deteriorating).\n2. TANGIBLE BOOK VALUE — Remove intangibles (goodwill, patents). Liquidation floor = tangible assets - total debt.\n3. 52-WEEK ANALYSIS — 52-week low: $[X]. -1 std dev: $[X]. -2 std devs: $[X]. Historically, how often has the stock bounced at these levels?\n4. TECHNICAL SUPPORTS — EMA 200 support: $[X]. Fibonacci support (61.8% retracement): $[X]. Volume Profile POC: $[X]. Visible accumulation zone?\n5. INSTITUTIONAL COST — Average institutional purchase price (proxy via 13F). If price is below this, institutions are at a loss → selling pressure OR opportunity if business is healthy.\n\nSUMMARY:\n| Method | Estimated Floor | Reliability |\n|--------|----------------|-------------|\n\nRecommended buy zone: $[X] to $[Y] with progressive sizing (33%/33%/33%).', ar:'[TICKER] انخفض [X%]. قدّر القاع بـ 5 طرق:\n\n1. القيمة الدفترية\n2. القيمة الدفترية الملموسة\n3. تحليل 52 أسبوعاً\n4. الدعوم الفنية\n5. تكلفة المؤسسات\n\nمنطقة الشراء الموصى بها: $[X] إلى $[Y] بتدرج (33%/33%/33%).' }
  },
  { num:35, cat:'portfolio', numBg:'#f5f3ff', numColor:'#7c3aed', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Allocation par régime de marché', en:'Regime-based allocation', ar:'التوزيع حسب نظام السوق' },
    badge:{ fr:'🌡️ Régime', en:'🌡️ Regime', ar:'🌡️ نظام' },
    desc:{ fr:'Adapte ton allocation selon le régime de marché (Risk-On, Risk-Off, Transition). Le VIX est ton thermomètre. Chaque régime a ses secteurs gagnants et perdants.', en:'Adapt your allocation to market regime (Risk-On, Risk-Off, Transition). VIX is your thermometer. Each regime has its winning and losing sectors.', ar:'كيّف توزيعك حسب نظام السوق (Risk-On، Risk-Off، انتقال). VIX هو ميزان حرارتك. كل نظام له قطاعاته الرابحة والخاسرة.' },
    code:{ fr:'Mon portefeuille : [LISTE POSITIONS + % ALLOCATION].\n\n1. RÉGIME ACTUEL — Analyse : VIX (niveau + tendance), credit spreads, DXY, courbe des taux (2Y/10Y). Verdict : Risk-On / Risk-Off / Transition.\n\n2. ALLOCATION RECOMMANDÉE PAR RÉGIME :\n| Classe d\'actifs | Risk-On | Transition | Risk-Off |\n|----------------|---------|-----------|----------|\n| Actions Growth | 35% | 20% | 10% |\n| Actions Value | 20% | 25% | 15% |\n| Obligations | 10% | 20% | 30% |\n| Or/Commodities | 5% | 10% | 20% |\n| Cash | 5% | 15% | 25% |\n| Crypto | 15% | 5% | 0% |\n\n3. ÉCART — Tableau comparatif : mon allocation actuelle vs allocation recommandée. Écart en points.\n\n4. ACTIONS — Top 5 mouvements à faire :\n— Réduire [POSITION] de X% → trop exposé pour ce régime\n— Augmenter [POSITION] de X% → sous-pondéré\n— Ajouter [NOUVEAU] → manque de [type d\'exposition]\n\n5. SIGNAUX DE TRANSITION — 3 indicateurs qui me diront que le régime change. Quand agir ?', en:'My portfolio: [LIST OF POSITIONS + % ALLOCATION].\n\n1. CURRENT REGIME — Analyze: VIX (level + trend), credit spreads, DXY, yield curve (2Y/10Y). Verdict: Risk-On / Risk-Off / Transition.\n\n2. RECOMMENDED ALLOCATION BY REGIME:\n| Asset Class | Risk-On | Transition | Risk-Off |\n|------------|---------|-----------|----------|\n\n3. GAP — Comparison table: my current allocation vs recommended. Gap in points.\n\n4. ACTIONS — Top 5 moves to make.\n\n5. TRANSITION SIGNALS — 3 indicators that will tell me the regime is changing.', ar:'محفظتي: [قائمة المراكز + نسبة التخصيص %].\n\n1. النظام الحالي — حلل: VIX، فروقات الائتمان، DXY، منحنى العائد.\n\n2. التوزيع الموصى حسب النظام\n\n3. الفجوة — مقارنة: توزيعي الحالي مقابل الموصى.\n\n4. الإجراءات — أهم 5 تحركات.\n\n5. إشارات الانتقال' }
  },
  { num:36, cat:'portfolio', numBg:'#f5f3ff', numColor:'#7c3aed', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Cartographie des corrélations', en:'Correlation mapping', ar:'خريطة الارتباطات' },
    badge:{ fr:'🔗 Correl', en:'🔗 Correl', ar:'🔗 ارتباط' },
    desc:{ fr:'Révèle les corrélations cachées de ton portefeuille. Ton "ETF monde + tech US + BTC" est peut-être un seul et même pari déguisé. Ce prompt le montre.', en:'Reveals the hidden correlations in your portfolio. Your "world ETF + US tech + BTC" might be a single disguised bet. This prompt shows it.', ar:'يكشف الارتباطات المخفية في محفظتك. "ETF عالمي + تقنية أمريكية + BTC" قد يكون رهاناً واحداً مُقنَّعاً.' },
    code:{ fr:'Mon portefeuille : [LISTE POSITIONS].\n\nCARTOGRAPHIE DES CORRÉLATIONS :\n1. MATRICE — Corrélation par paire (haute >0.7, moyenne 0.3-0.7, faible <0.3). Mets en ROUGE les paires >0.7.\n2. FACTEURS COMMUNS — Est-ce que tout mon portefeuille est en réalité un pari sur : taux bas ? dollar faible ? growth factor ? Identifie les facteurs dominants.\n3. BETA PORTFOLIO — Beta pondéré vs S&P 500. Si >1.2, le portefeuille amplifie les mouvements du marché.\n4. DIVERSIFICATION RÉELLE — Score de diversification effective (nombre de positions indépendantes réelles, pas nominales).\n5. STRESS CORRÉLATION — En crise, les corrélations montent vers 1. Quelle est la perte attendue si toutes mes positions bougent ensemble ?\n6. DÉCORRÉLANTS — 3 actifs qui réduiraient la corrélation portfolio (ex: or, TLT, managed futures, immobilier). Impact simulé sur le Sharpe ratio.', en:'My portfolio: [LIST OF POSITIONS].\n\nCORRELATION MAPPING:\n1. MATRIX — Pairwise correlation (high >0.7, medium 0.3-0.7, low <0.3). Highlight pairs >0.7 in RED.\n2. COMMON FACTORS — Is my entire portfolio actually a bet on: low rates? weak dollar? growth factor? Identify dominant factors.\n3. PORTFOLIO BETA — Weighted beta vs S&P 500.\n4. REAL DIVERSIFICATION — Effective diversification score.\n5. CRISIS CORRELATION — In a crisis, correlations move toward 1. Expected loss if all positions move together?\n6. DECORRELATORS — 3 assets that would reduce portfolio correlation (e.g.: gold, TLT, managed futures). Simulated impact on Sharpe ratio.', ar:'محفظتي: [قائمة المراكز].\n\nخريطة الارتباطات:\n1. المصفوفة — ارتباط لكل زوج.\n2. العوامل المشتركة.\n3. بيتا المحفظة.\n4. التنويع الحقيقي.\n5. ارتباط الأزمة.\n6. أصول إزالة الارتباط.' }
  },
  { num:37, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Covered call optimal', en:'Optimal covered call', ar:'Covered call الأمثل' },
    badge:{ fr:'💵 Income', en:'💵 Income', ar:'💵 دخل' },
    desc:{ fr:'Trouve le strike et l\'expiry optimaux pour générer du revenu sur tes positions existantes. Le sweet spot ? 30-45 DTE, delta 0.20-0.30.', en:'Find the optimal strike and expiry to generate income on your existing positions. The sweet spot? 30-45 DTE, delta 0.20-0.30.', ar:'أوجد Strike والاستحقاق الأمثل لتوليد دخل من مراكزك الحالية. النقطة المثالية؟ 30-45 يوماً، delta 0.20-0.30.' },
    code:{ fr:'Je détiens 100 actions de [TICKER] à $[PRIX]. Je veux vendre des covered calls pour générer du revenu.\n\nTrouve le call optimal :\n1. FILTRE — DTE 30-45 jours. Delta entre 0.20 et 0.30 (= 70-80% de probabilité de garder mes actions).\n2. OPTIONS — Tableau des 3 meilleurs strikes :\n   | Strike | DTE | Delta | Prime | Rendement annualisé | Prob OTM |\n3. PROTECTION — La prime reçue offre quel % de protection à la baisse ?\n4. RISQUE — Si le titre monte au-dessus du strike, je rate combien de upside ? Suis-je OK avec ce trade-off ?\n5. IV RANK — L\'IV est-elle actuellement haute ou basse ? (haute = prime plus juteuse = meilleur moment pour vendre des calls)\n6. CALENDRIER — Y a-t-il un earnings/dividende/événement avant l\'expiration ? Si oui, éviter ou choisir une expiry après.\n\nRECOMMANDATION : Strike $[X], expiry [DATE], prime ~$[X]. Rendement annualisé : [Y%]. Alerte si le prix touche [Z] → rouler ou fermer.', en:'I own 100 shares of [TICKER] at $[PRICE]. I want to sell covered calls for income.\n\nFind the optimal call:\n1. FILTER — DTE 30-45 days. Delta between 0.20 and 0.30 (= 70-80% probability of keeping shares).\n2. OPTIONS — Table of 3 best strikes:\n   | Strike | DTE | Delta | Premium | Annualized Yield | Prob OTM |\n3. PROTECTION — The received premium provides what % of downside protection?\n4. RISK — If stock moves above strike, how much upside do I miss?\n5. IV RANK — Is IV currently high or low?\n6. CALENDAR — Any earnings/dividend/event before expiry?\n\nRECOMMENDATION: Strike $[X], expiry [DATE], premium ~$[X]. Annualized yield: [Y%].', ar:'أملك 100 سهم من [TICKER] عند $[السعر]. أريد بيع covered calls لتوليد دخل.\n\n1. الفلتر — DTE 30-45 يوماً. Delta بين 0.20 و0.30.\n2. الخيارات — جدول أفضل 3 strikes.\n3. الحماية.\n4. المخاطر.\n5. IV Rank.\n6. التقويم.\n\nالتوصية: Strike $[X]، الاستحقاق [التاريخ]، العلاوة ~$[X].' }
  },
  { num:38, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Put protecteur : sizing optimal', en:'Protective put: optimal sizing', ar:'Put الحماية: الحجم الأمثل' },
    badge:{ fr:'🛡️ Hedge', en:'🛡️ Hedge', ar:'🛡️ تحوط' },
    desc:{ fr:'Calcule le put protecteur optimal pour couvrir ton portefeuille. Le compromis clé : protection vs coût. Un hedge trop cher mange le rendement.', en:'Calculate the optimal protective put to cover your portfolio. The key trade-off: protection vs cost. A hedge that is too expensive eats into returns.', ar:'احسب Put الحماية الأمثل لتغطية محفظتك. المقايضة الأساسية: الحماية مقابل التكلفة.' },
    code:{ fr:'Portefeuille : $[MONTANT] investis. Beta portfolio : ~[X]. Je veux me protéger contre un crash de -[X%].\n\n1. INSTRUMENT — Quel put acheter ? SPY puts (pour couverture large) ou puts sur mes positions individuelles ?\n2. STRIKE — Quel strike ? ATM (protection totale, cher) vs OTM -10% (moins cher, franchise de 10%) vs OTM -20% (tail risk only).\n3. SIZING — Combien de contrats ? Formule : (Valeur portfolio × Beta) / (100 × prix du sous-jacent).\n4. COÛT — Prime totale en $ et en % du portefeuille par an. Seuil acceptable : < 2% du portefeuille/an.\n5. ALTERNATIVES — Comparaison :\n   | Stratégie | Coût annuel | Protection | Complexité |\n   | Long put ATM | $X | -100% | Simple |\n   | Long put -10% | $X | -90% | Simple |\n   | Put spread | $X | Plafonnée | Moyenne |\n   | Collar | ~$0 | Plafonnée haut+bas | Avancée |\n6. TIMING — Quand acheter ? IV basse = puts moins chers. VIX < 15 = bon moment pour hedger.', en:'Portfolio: $[AMOUNT] invested. Portfolio beta: ~[X]. I want protection against a -[X%] crash.\n\n1. INSTRUMENT — Which put to buy? SPY puts (broad coverage) or puts on individual positions?\n2. STRIKE — Which strike? ATM vs OTM -10% vs OTM -20%.\n3. SIZING — How many contracts?\n4. COST — Total premium in $ and as % of portfolio per year. Acceptable: < 2%/year.\n5. ALTERNATIVES — Comparison table.\n6. TIMING — When to buy? Low IV = cheaper puts.', ar:'المحفظة: $[المبلغ]. بيتا المحفظة: ~[X]. أريد الحماية من انهيار -[X%].\n\n1. الأداة — أي put؟\n2. Strike — أي مستوى؟\n3. الحجم — كم عقد؟\n4. التكلفة\n5. البدائل\n6. التوقيت' }
  },
  { num:39, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Decoder earnings whisper', en:'Earnings whisper decoder', ar:'فك شفرة توقعات الأرباح' },
    badge:{ fr:'🎲 Whisper', en:'🎲 Whisper', ar:'🎲 همس' },
    desc:{ fr:'Analyse pré-earnings complète : whisper numbers vs consensus, IV crush estimé, réaction historique, et comment se positionner. Le marché ne trade pas les earnings passés — il trade la surprise.', en:'Complete pre-earnings analysis: whisper vs consensus, estimated IV crush, historical reaction, positioning. The market doesn\'t trade past earnings — it trades the surprise.', ar:'تحليل ما قبل الأرباح الكامل: الأرقام المتوقعة مقابل الإجماع، IV crush المقدر، ردة الفعل التاريخية، وكيفية التموضع.' },
    code:{ fr:'[TICKER] publie ses résultats le [DATE]. Prépare-moi :\n\n1. CONSENSUS vs WHISPER :\n   | Métrique | Consensus | Whisper | Écart |\n   | EPS | $[X] | | |\n   | CA | $[X]B | | |\n   Le whisper est-il au-dessus ou au-dessous du consensus ? (whisper > consensus = la barre est plus haute)\n\n2. HISTORIQUE DES RÉACTIONS — Tableau des 4 derniers earnings :\n   | Trimestre | EPS (beat/miss) | Mouvement J+1 | Direction |\n   Pattern : le titre a-t-il tendance à monter ou baisser après les earnings, quel que soit le résultat ?\n\n3. IV CRUSH — IV actuelle vs IV historique pré-earnings. Move implicite (straddle ATM) : ±[X%]. Move moyen réalisé (4 derniers Q) : ±[Y%]. Si implicite > réalisé → le marché surpaye la vol.\n\n4. POSITIONNEMENT OPTIMAL :\n— Si conviction directionnelle → achat avant (risquer le gap)\n— Si conviction vol → long straddle AVANT, fermer APRÈS (jouer le move)\n— Si pas de conviction → ne rien faire AVANT, acheter le dip/pullback APRÈS\n— JAMAIS acheter des calls/puts nus juste avant (IV crush garantit une perte)\n\n5. NIVEAUX POST-EARNINGS — Si beat : résistance $[X], target $[Y]. Si miss : support $[X], pire cas $[Y].', en:'[TICKER] reports earnings on [DATE]. Prepare me:\n\n1. CONSENSUS vs WHISPER:\n   | Metric | Consensus | Whisper | Gap |\n\n2. HISTORICAL REACTIONS — Table of last 4 earnings.\n\n3. IV CRUSH — Current IV vs historical pre-earnings IV. Implied move (ATM straddle): ±[X%]. Average realized move: ±[Y%].\n\n4. OPTIMAL POSITIONING:\n— If directional conviction → buy before\n— If vol conviction → long straddle before, close after\n— If no conviction → wait, buy the dip after\n— NEVER buy naked calls/puts just before (IV crush guarantees a loss)\n\n5. POST-EARNINGS LEVELS — If beat: resistance $[X]. If miss: support $[X].', ar:'[TICKER] يعلن نتائجه في [التاريخ]. حضّرني:\n\n1. الإجماع مقابل التوقعات\n2. ردود الفعل التاريخية\n3. IV Crush\n4. التموضع الأمثل\n5. المستويات بعد الإعلان' }
  },
  { num:40, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#ecfdf5', badgeColor:'#059669',
    title:{ fr:'Cartographie supports/résistances', en:'Support/resistance mapper', ar:'خريطة الدعوم/المقاومات' },
    badge:{ fr:'📐 S/R Map', en:'📐 S/R Map', ar:'📐 خريطة' },
    desc:{ fr:'Identifie TOUS les niveaux clés avec 5 méthodes différentes. Quand 3+ méthodes convergent sur le même prix, c\'est une zone de haute probabilité.', en:'Identify ALL key levels using 5 different methods. When 3+ methods converge on the same price, it\'s a high-probability zone.', ar:'حدد جميع المستويات الرئيسية بـ 5 طرق مختلفة. عندما تتقاطع 3+ طرق عند نفس السعر، فهي منطقة عالية الاحتمال.' },
    code:{ fr:'[TICKER] à $[PRIX]. Cartographie tous les supports et résistances clés :\n\n1. MÉTHODE 1 — Pivot Points (classiques + Fibonacci) :\n   R3, R2, R1, Pivot, S1, S2, S3\n\n2. MÉTHODE 2 — Moving Averages : EMA 20, EMA 50, EMA 200, SMA 200 — lesquelles sont support, lesquelles résistance ?\n\n3. MÉTHODE 3 — Volume Profile : POC (Point of Control), Value Area High, Value Area Low, HVN (High Volume Nodes) et LVN (Low Volume Nodes)\n\n4. MÉTHODE 4 — Prior Highs/Lows : 52-week high, 52-week low, All-Time High, swing highs/lows récents\n\n5. MÉTHODE 5 — Fibonacci : Retracement 38.2%, 50%, 61.8% depuis le dernier mouvement majeur\n\nSYNTHÈSE — Tableau de convergence :\n| Niveau ($) | Méthode 1 | Méthode 2 | Méthode 3 | Méthode 4 | Méthode 5 | Confluence (/5) |\nLes niveaux avec confluence ≥3 sont les zones les plus fiables.\n\nTOP 3 SUPPORTS : $[X], $[Y], $[Z]\nTOP 3 RÉSISTANCES : $[X], $[Y], $[Z]', en:'[TICKER] at $[PRICE]. Map all key supports and resistances:\n\n1. Pivot Points (classic + Fibonacci)\n2. Moving Averages: EMA 20, 50, 200, SMA 200\n3. Volume Profile: POC, VAH, VAL, HVN, LVN\n4. Prior Highs/Lows: 52W high/low, ATH, recent swings\n5. Fibonacci retracement: 38.2%, 50%, 61.8%\n\nCONVERGENCE TABLE — Levels with confluence ≥3 are most reliable.', ar:'[TICKER] عند $[السعر]. خريطة جميع الدعوم والمقاومات:\n\n1. نقاط المحور\n2. المتوسطات المتحركة\n3. Volume Profile\n4. القمم/القيعان السابقة\n5. مستويات فيبوناتشي\n\nجدول التقاطع — المستويات ذات التقاطع ≥3 هي الأكثر موثوقية.' }
  },
  { num:41, cat:'stock', numBg:'#ecfdf5', numColor:'#059669', badgeBg:'#f5f3ff', badgeColor:'#7c3aed',
    title:{ fr:'Lecture du Volume Profile', en:'Volume profile reader', ar:'قراءة ملف الحجم' },
    badge:{ fr:'📊 Volume', en:'📊 Volume', ar:'📊 حجم' },
    desc:{ fr:'Le Volume Profile révèle où l\'argent institutionnel s\'est concentré. POC = prix le plus échangé = aimant. HVN = zones de consensus. LVN = zones de vide → le prix les traverse vite.', en:'Volume Profile reveals where institutional money concentrated. POC = most traded price = magnet. HVN = consensus zones. LVN = voids → price moves through them fast.', ar:'Volume Profile يكشف أين تركّزت الأموال المؤسسية. POC = أكثر سعر تداولاً = مغناطيس.' },
    code:{ fr:'Analyse le Volume Profile de [TICKER] :\n\n1. POC (Point of Control) : $[X] — Le prix le plus échangé. C\'est un aimant : le prix y revient souvent.\n2. VALUE AREA : de $[X] à $[Y] (70% du volume). Le prix est-il à l\'intérieur ou à l\'extérieur de la Value Area ?\n— Dedans → range, mean-reversion\n— Dessus → bullish, la VA devient support\n— Dessous → bearish, la VA devient résistance\n3. HVN (High Volume Nodes) — Zones de consensus institutionnel. Le prix ralentit ici. Idéal pour les entries.\n4. LVN (Low Volume Nodes) — Zones de vide. Le prix passe rapidement. Dangereux pour les stops.\n5. ACCUMULATION vs DISTRIBUTION :\n— Volume en hausse + prix en hausse = accumulation (bullish)\n— Volume en hausse + prix en baisse = distribution (bearish)\n— Volume en baisse = indécision\n\nACTION : Où placer mon entry ? (sur un HVN). Où placer mon stop ? (sous un LVN — zone de vide, si cassé le prix accélère). Target = prochain HVN ou extrême de la Value Area.', en:'Analyze the Volume Profile for [TICKER]:\n\n1. POC: $[X] — Most traded price, acts as a magnet.\n2. VALUE AREA: $[X] to $[Y] (70% of volume). Price inside or outside?\n3. HVN — Institutional consensus zones. Price slows here.\n4. LVN — Void zones. Price moves fast through them.\n5. ACCUMULATION vs DISTRIBUTION\n\nACTION: Entry on HVN, stop below LVN, target next HVN.', ar:'حلّل Volume Profile لـ [TICKER]:\n\n1. POC: أكثر سعر تداولاً\n2. منطقة القيمة\n3. HVN — مناطق الإجماع\n4. LVN — مناطق الفراغ\n5. تراكم أم توزيع\n\nالإجراء: الدخول على HVN، الوقف تحت LVN.' }
  },
  { num:42, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#eef2ff', badgeColor:'#4338ca',
    title:{ fr:'Optimiseur risk/reward', en:'Risk/reward optimizer', ar:'محسّن المخاطر/العائد' },
    badge:{ fr:'⚙️ R:R', en:'⚙️ R:R', ar:'⚙️ R:R' },
    desc:{ fr:'Entre ton entry, stop, et targets. Ce prompt calcule : R:R, taux de réussite minimum pour être profitable, sizing Kelly, et si le trade vaut le coup.', en:'Enter your entry, stop, and targets. This prompt calculates: R:R, minimum win rate for profitability, Kelly sizing, and whether the trade is worth it.', ar:'أدخل دخولك ووقفك وأهدافك. هذا البرومبت يحسب: R:R، الحد الأدنى لمعدل النجاح، حجم Kelly.' },
    code:{ fr:'Mon trade :\n— Entry : $[X]\n— Stop Loss : $[X]\n— TP1 : $[X] (50% de la position)\n— TP2 : $[X] (50% restant)\n— Capital total : $[X]\n\nCALCULE :\n1. RISQUE — Risque par action : entry - stop = $[X]. En % : [Y%].\n2. R:R — Ratio TP1 : [X:1]. Ratio TP2 : [X:1]. Ratio moyen pondéré (50/50) : [X:1]. Si R:R < 1.5:1 → le trade ne vaut pas le coup.\n3. BREAK-EVEN WIN RATE — Pour être profitable sur 100 trades identiques, quel % minimum de trades gagnants ? Formule : 1 / (1 + R:R).\n4. KELLY CRITERION — Si mon win rate estimé est de [X%], le sizing optimal = (win% × R:R - lose%) / R:R. En % du capital : [Y%]. Kelly/2 (conservateur) : [Z%].\n5. SIZING — Avec un risque max de 2% du capital par trade : combien d\'actions ? Montant total investi ?\n6. VERDICT — ☐ Trade excellent (R:R > 3:1) ☐ Trade acceptable (1.5-3:1) ☐ Trade médiocre (<1.5:1) ☐ Ajuster les niveaux', en:'My trade:\n— Entry: $[X]\n— Stop Loss: $[X]\n— TP1: $[X] (50%)\n— TP2: $[X] (50%)\n— Total capital: $[X]\n\nCALCULATE:\n1. RISK — Risk per share, in %.\n2. R:R — TP1 ratio, TP2 ratio, weighted average.\n3. BREAK-EVEN WIN RATE — Minimum win rate for profitability.\n4. KELLY CRITERION — Optimal sizing.\n5. SIZING — With 2% max risk: how many shares?\n6. VERDICT', ar:'صفقتي:\nالدخول: $[X]، الوقف: $[X]، الهدف1: $[X]، الهدف2: $[X]\n\nاحسب: R:R، معدل التعادل، Kelly، الحجم، الحكم.' }
  },
  { num:43, cat:'macro', numBg:'#eff6ff', numColor:'#2563eb', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Récap hebdomadaire des marchés', en:'Weekly market recap', ar:'الملخص الأسبوعي للأسواق' },
    badge:{ fr:'📰 Weekly', en:'📰 Weekly', ar:'📰 أسبوعي' },
    desc:{ fr:'Génère un récapitulatif institutionnel de la semaine : indices, secteurs, crypto, commodities, macro, géopolitique. Format DailyTickers Weekly.', en:'Generate an institutional weekly recap: indices, sectors, crypto, commodities, macro, geopolitics. DailyTickers Weekly format.', ar:'أنشئ ملخصاً مؤسسياً أسبوعياً: مؤشرات، قطاعات، كريبتو، سلع، ماكرو، جيوسياسة.' },
    code:{ fr:'Rédige un récapitulatif hebdomadaire des marchés (format institutionnel) :\n\n1. DASHBOARD — Performances de la semaine :\n   | Indice/Actif | Clôture | Perf semaine | Perf YTD |\n   SPY, QQQ, DIA, IWM, EFA, EEM, BTC, ETH, GLD, TLT, DXY, VIX\n\n2. FAITS MARQUANTS — Top 3 événements de la semaine avec impact marché.\n\n3. SECTEURS — Performance des 11 secteurs S&P. Meilleur et pire. Rotation détectée ?\n\n4. CRYPTO — BTC et ETH : niveaux clés, dominance, sentiment, flux ETF.\n\n5. MACRO — Données publiées cette semaine (CPI, PMI, emploi...). Surprises vs attentes.\n\n6. GÉOPOLITIQUE — Risques et impacts sur les marchés.\n\n7. EARNINGS — Résultats marquants de la semaine.\n\n8. SEMAINE PROCHAINE — Calendrier : données macro, earnings, réunions BC, événements clés.\n\n9. CONVICTION — Biais pour la semaine prochaine (bullish/bearish/neutre). Niveau à surveiller.', en:'Write a weekly market recap (institutional format):\n\n1. DASHBOARD — Weekly performance table (SPY, QQQ, BTC, GLD, VIX...)\n2. KEY EVENTS — Top 3 with market impact\n3. SECTORS — 11 S&P sectors performance\n4. CRYPTO — BTC, ETH levels and sentiment\n5. MACRO — Data released, surprises\n6. GEOPOLITICS — Risks and impacts\n7. EARNINGS — Notable results\n8. NEXT WEEK — Calendar\n9. CONVICTION — Bias for next week', ar:'اكتب ملخصاً أسبوعياً:\n1. لوحة القيادة\n2. الأحداث الرئيسية\n3. القطاعات\n4. الكريبتو\n5. الماكرو\n6. الجيوسياسة\n7. الأرباح\n8. الأسبوع القادم\n9. الاقتناع' }
  },
  { num:44, cat:'crypto', numBg:'#fff7ed', numColor:'#ea580c', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Audit yield DeFi', en:'DeFi yield audit', ar:'تدقيق عوائد DeFi' },
    badge:{ fr:'🌾 Yield', en:'🌾 Yield', ar:'🌾 عائد' },
    desc:{ fr:'Un APY de 500% ? Trop beau pour être vrai. Ce prompt décompose les sources réelles du rendement, calcule le yield durable, et identifie les risques cachés (IL, smart contract, depeg).', en:'500% APY? Too good to be true. This prompt breaks down real yield sources, calculates sustainable yield, and identifies hidden risks (IL, smart contract, depeg).', ar:'APY بنسبة 500%؟ أجمل من أن يكون حقيقياً. هذا البرومبت يفكّك مصادر العائد الحقيقية ويحدد المخاطر المخفية.' },
    code:{ fr:'[PROTOCOLE/POOL] offre un APY de [X%]. Audite ce rendement :\n\n1. SOURCE DU YIELD — D\'où vient le rendement exactement ?\n☐ Frais de trading (durable ✅)\n☐ Rewards token natif (inflationnaire ⚠️)\n☐ Leverage/emprunt (risqué ❌)\n☐ Subsidies/incentives temporaires (non durable ⚠️)\nYield durable estimé (sans incentives) : [X%]\n\n2. IMPERMANENT LOSS — Pour une pool [TOKEN A / TOKEN B] :\n— Si A monte de 50% vs B : IL = ~2.02%\n— Si A monte de 100% vs B : IL = ~5.72%\n— Le yield compense-t-il l\'IL attendue ?\n\n3. SMART CONTRACT RISK — Audité ? Par qui ? TVL : $[X]M. Exploits passés ? Contrat upgradeable ?\n\n4. RISQUE DE DEPEG — Si stablecoin : mécanisme de peg, réserves, historique de depeg. Si non-stable : corrélation des tokens de la pool.\n\n5. SCÉNARIO RÉALISTE — Après déduction de : gas fees, IL, baisse du token de reward → yield NET réel estimé sur 6 mois : [X%]. Vs simplement HODL les tokens : différence de [Y%].\n\nVERDICT : ☐ Yield réel et durable ☐ Yield artificiellement gonflé ☐ Ponzi déguisé', en:'[PROTOCOL/POOL] offers [X%] APY. Audit this yield:\n\n1. YIELD SOURCE — Where does it come from?\n2. IMPERMANENT LOSS\n3. SMART CONTRACT RISK\n4. DEPEG RISK\n5. REALISTIC SCENARIO — Net yield after gas, IL, reward token decline.\n\nVERDICT: ☐ Real sustainable yield ☐ Artificially inflated ☐ Disguised Ponzi', ar:'[البروتوكول/Pool] يعرض APY بنسبة [X%]. دقّق هذا العائد:\n\n1. مصدر العائد\n2. الخسارة غير الدائمة\n3. مخاطر العقد الذكي\n4. مخاطر فقدان الربط\n5. السيناريو الواقعي\n\nالحكم: ☐ عائد حقيقي مستدام ☐ مضخّم ☐ بونزي مقنّع' }
  },
  { num:45, cat:'crypto', numBg:'#fff7ed', numColor:'#ea580c', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Jauge sentiment memecoin', en:'Memecoin sentiment gauge', ar:'مقياس معنويات الميمكوين' },
    badge:{ fr:'🐸 Meme', en:'🐸 Meme', ar:'🐸 ميم' },
    desc:{ fr:'Analyse en temps réel d\'un memecoin : buzz social, distribution des holders, métriques de lancement, probabilité de pump. Rappel : 95% des memecoins vont à 0.', en:'Real-time memecoin analysis: social buzz, holder distribution, launch metrics, pump probability. Reminder: 95% of memecoins go to 0.', ar:'تحليل فوري لميمكوين: ضجة اجتماعية، توزيع الحاملين، مقاييس الإطلاق. تذكير: 95% من الميمكوين تذهب إلى الصفر.' },
    code:{ fr:'[MEMECOIN] — Analyse express :\n\n1. BUZZ — Mentions X/Twitter (24h). Mentions Reddit. Tendance : croissante, stable, déclinante. Narratif dominant (quel meme/communauté ?).\n2. TOKENOMICS — Supply, distribution top 10 wallets, creator wallet %. Y a-t-il des fonctions de taxe sur les transactions ?\n3. LIQUIDITÉ — Pool LP : taille, lockée ? TVL DEX. Volume 24h vs market cap (ratio sain > 10%).\n4. TIMING — Le pump a-t-il déjà eu lieu ? (Si +500% en 24h → vous êtes probablement en retard). Distance du ATH.\n5. COMPARABLES — Comparer à 3 memecoins similaires qui ont pumpé récemment. Comment se sont-ils terminés ? (la plupart -90%).\n6. VERDICT FROID — Probabilité de +100% supplémentaire : [X%]. Probabilité de -80% : [X%]. Sizing recommandé : max [X]% du capital crypto (= argent que vous acceptez de perdre à 100%).\n\n⚠️ RAPPEL : 95% des memecoins perdent >90% de leur valeur. Si vous investissez, c\'est du casino — pas de l\'investissement. Stop mental obligatoire à -50%.', en:'[MEMECOIN] — Express analysis:\n\n1. BUZZ — X/Twitter mentions (24h), Reddit, trend.\n2. TOKENOMICS — Supply, top 10 wallets, tax functions.\n3. LIQUIDITY — LP pool, locked?, DEX volume.\n4. TIMING — Has the pump already happened?\n5. COMPARABLES — 3 similar memecoins, how did they end?\n6. COLD VERDICT — Probability of +100%: [X%]. Of -80%: [X%].\n\n⚠️ 95% of memecoins lose >90%. If you invest, it\'s gambling.', ar:'[MEMECOIN] — تحليل سريع:\n\n1. الضجة\n2. Tokenomics\n3. السيولة\n4. التوقيت\n5. المقارنات\n6. الحكم البارد\n\n⚠️ 95% من الميمكوين تخسر أكثر من 90%.' }
  },
  { num:46, cat:'macro', numBg:'#eff6ff', numColor:'#2563eb', badgeBg:'#eff6ff', badgeColor:'#2563eb',
    title:{ fr:'Playbook inflation / déflation', en:'Inflation / deflation playbook', ar:'دليل التضخم / الانكماش' },
    badge:{ fr:'📈 CPI Play', en:'📈 CPI Play', ar:'📈 CPI' },
    desc:{ fr:'Après chaque CPI/PCE, ce prompt te dit comment positionner ton portefeuille. TIPS, commodities, immobilier, secteurs rate-sensitive — le playbook complet.', en:'After each CPI/PCE, this prompt tells you how to position your portfolio. TIPS, commodities, real estate, rate-sensitive sectors — the complete playbook.', ar:'بعد كل CPI/PCE، هذا البرومبت يخبرك كيف تموضع محفظتك. TIPS، سلع، عقارات، قطاعات حساسة للفائدة.' },
    code:{ fr:'Dernière donnée : CPI [X%] (core [Y%]) / PCE [X%] (core [Y%]). Tendance : [en hausse / stable / en baisse].\n\nPLAYBOOK :\n1. RÉGIME INFLATION — Où en est-on ?\n☐ Déflation (<1%) → Bonds, tech, growth\n☐ Inflation modérée (1-3%) → Goldilocks, actions en général\n☐ Inflation élevée (3-5%) → Commodities, value, financials\n☐ Stagflation (inflation haute + croissance faible) → Or, TIPS, cash, défensives\n\n2. TAUX — Anticipation marché du prochain mouvement Fed. Impact sur TLT, courbe des taux, high yield.\n\n3. POSITIONNEMENT PAR ACTIF :\n   | Actif | Régime actuel | Action |\n   | TIPS | | Surpondérer/Sous-pondérer/Neutre |\n   | Or (GLD) | | |\n   | Commodities (DBC) | | |\n   | REITs | | |\n   | Tech/Growth | | |\n   | Financials (XLF) | | |\n   | Utilities (XLU) | | |\n   | TLT (bonds long) | | |\n\n4. TRADE — 2 idées de trades basées sur le scénario inflation actuel. Entry, stop, target, R:R.', en:'Latest data: CPI [X%] (core [Y%]). Trend: [rising / stable / declining].\n\nPLAYBOOK:\n1. INFLATION REGIME — Where are we?\n2. RATES — Market expectation for next Fed move.\n3. POSITIONING BY ASSET — Table.\n4. TRADE — 2 trade ideas for current inflation scenario.', ar:'أحدث بيانات: CPI [X%]. الاتجاه: [صعودي / مستقر / هبوطي].\n\n1. نظام التضخم\n2. الأسعار\n3. التموضع حسب الأصل\n4. صفقتان' }
  },
  { num:47, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#eef2ff', badgeColor:'#4338ca',
    title:{ fr:'Constructeur de watchlist', en:'Watchlist builder', ar:'بناء قائمة المراقبة' },
    badge:{ fr:'📋 Watchlist', en:'📋 Watchlist', ar:'📋 قائمة' },
    desc:{ fr:'Construis une watchlist structurée de 10 tickers avec niveaux d\'entrée, stops, catalyseurs et priorité. Pas une liste de souhaits — un plan d\'action.', en:'Build a structured 10-ticker watchlist with entry levels, stops, catalysts and priority. Not a wish list — an action plan.', ar:'ابنِ قائمة مراقبة مهيكلة من 10 أسهم مع مستويات دخول ووقف ومحفزات وأولوية.' },
    code:{ fr:'Mon profil : [PROFIL — agressif/modéré/conservateur]. Secteurs préférés : [SECTEURS]. Capital disponible : $[X].\n\nConstruis une watchlist de 10 tickers :\n\n| # | Ticker | Secteur | Thèse (1 phrase) | Entry Zone | Stop | TP | R:R | Catalyseur | Priorité |\n|---|--------|---------|------------------|------------|------|----|----|-----------|----------|\n\nRÈGLES :\n— Diversification : max 2 tickers par secteur, min 3 géographies\n— Pas de doublons (pas 2 semis, pas 2 pharmas)\n— Au moins 1 position défensive (GLD, TLT, utility)\n— Priorité : A (prêt à acheter maintenant) / B (surveiller, pas encore au bon prix) / C (thèse intéressante, pas mûr)\n\nPour les 3 top priorités (rang A), détaille :\n— Setup technique (pattern, confluences)\n— Catalyseur daté si possible\n— Sizing recommandé (% du capital)\n— Ordre suggéré (limit à $[X])\n\nRevue : quand réévaluer cette watchlist ? (hebdo ? post-earnings ?)' , en:'My profile: [PROFILE — aggressive/moderate/conservative]. Preferred sectors: [SECTORS]. Available capital: $[X].\n\nBuild a 10-ticker watchlist:\n\n| # | Ticker | Sector | Thesis | Entry Zone | Stop | TP | R:R | Catalyst | Priority |\n\nRULES: Max 2 per sector, min 3 geographies, at least 1 defensive.\nPriority: A (ready to buy) / B (watching) / C (interesting, not ripe)\n\nFor top 3 (rank A): detail setup, catalyst, sizing, suggested order.', ar:'بناء قائمة مراقبة من 10 أسهم مع مستويات وأولويات.' }
  },
  { num:48, cat:'essential', numBg:'#eef2ff', numColor:'#4338ca', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Stratégie de sortie', en:'Exit strategy', ar:'استراتيجية الخروج' },
    badge:{ fr:'🚪 Exit', en:'🚪 Exit', ar:'🚪 خروج' },
    desc:{ fr:'Savoir quand vendre est plus dur que savoir quand acheter. Trailing stop, profit-taking rules, signaux de régime — le framework complet pour ne pas rendre vos gains.', en:'Knowing when to sell is harder than knowing when to buy. Trailing stop, profit-taking rules, regime signals — the complete framework to keep your gains.', ar:'معرفة متى تبيع أصعب من معرفة متى تشتري. Trailing stop، قواعد جني الأرباح، إشارات النظام.' },
    code:{ fr:'Je détiens [TICKER] acheté à $[X], actuellement à $[Y] (+[Z%]). Dois-je vendre ?\n\n1. TRAILING STOP — Calculer le trailing stop optimal :\n— ATR-based : 2× ATR(14) sous le plus haut récent = $[X]\n— %-based : -10% depuis le plus haut = $[X]\n— EMA-based : clôture sous EMA 20 (court terme) ou EMA 50 (moyen terme)\n\n2. PROFIT-TAKING RULES :\n— +50% → vendre 25% (récupérer une partie)\n— +100% → vendre 50% (récupérer la mise initiale = "free ride")\n— Le reste : laisser courir avec trailing stop\n\n3. SIGNAUX DE VENTE FONDAMENTAUX :\n☐ La thèse d\'achat originale est-elle encore valide ?\n☐ Les insiders vendent-ils massivement ?\n☐ Les analystes dégradent-ils le titre ?\n☐ Les marges se contractent-elles ?\n☐ Un concurrent disrupte-t-il le business model ?\n\n4. SIGNAUX DE VENTE TECHNIQUES :\n☐ RSI > 80 (suracheté extrême)\n☐ Divergence bearish MACD\n☐ Volume en baisse malgré le prix en hausse\n☐ Cassure d\'un support majeur (EMA 200)\n\n5. VERDICT — ☐ GARDER (thèse intacte + technique OK) ☐ ALLÉGER (prendre une partie) ☐ VENDRE (thèse invalidée ou signaux multiples)\n\nSi ALLÉGER : combien vendre ? À quel prix placer le trailing stop sur le reste ?', en:'I hold [TICKER] bought at $[X], currently at $[Y] (+[Z%]). Should I sell?\n\n1. TRAILING STOP — ATR-based, %-based, EMA-based.\n2. PROFIT-TAKING RULES — +50% sell 25%, +100% sell 50%.\n3. FUNDAMENTAL SELL SIGNALS — 5 checkboxes.\n4. TECHNICAL SELL SIGNALS — 4 checkboxes.\n5. VERDICT — Hold / Trim / Sell', ar:'أملك [TICKER] مشترى عند $[X]، حالياً عند $[Y] (+[Z%]). هل أبيع؟\n\n1. Trailing Stop\n2. قواعد جني الأرباح\n3. إشارات بيع أساسية\n4. إشارات بيع فنية\n5. الحكم' }
  },
  { num:49, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#fef2f2', badgeColor:'#dc2626',
    title:{ fr:'Flux dark pool & options', en:'Dark pool & options flow', ar:'تدفقات Dark Pool والخيارات' },
    badge:{ fr:'🔮 Flow', en:'🔮 Flow', ar:'🔮 تدفقات' },
    desc:{ fr:'Détecte les traces institutionnelles : prints dark pool, block trades, unusual options activity. Si les "smart money" bougent, ce prompt le montre.', en:'Detect institutional footprints: dark pool prints, block trades, unusual options activity. If smart money is moving, this prompt shows it.', ar:'اكشف آثار المؤسسات: dark pool prints، block trades، نشاط خيارات غير عادي.' },
    code:{ fr:'[TICKER] — Analyse des flux institutionnels :\n\n1. DARK POOL — Volume dark pool en % du total (normal : 30-40%). Prints notables > $1M. Net dark pool sentiment (achats - ventes).\n2. BLOCK TRADES — Transactions > 10K actions. Timing (ouverture, clôture, intraday). Direction dominante.\n3. OPTIONS FLOW — Unusual activity :\n— Ratio P/C (Put/Call). Normal ~0.7. > 1 = bearish. < 0.5 = très bullish.\n— Sweeps : achats agressifs (sweep = urgence). Calls ou puts ?\n— Open Interest concentré sur quels strikes/dates ?\n— Max Pain : $[X] — le prix que les market makers veulent à l\'expiry\n— GEX (Gamma Exposure) : positif ou négatif ? (négatif = volatilité attendue)\n4. 13F RÉCENTS — Les hedge funds majeurs ont-ils augmenté ou réduit leurs positions ce trimestre ?\n5. SYNTHÈSE — Le smart money est plutôt : ☐ Bullish ☐ Bearish ☐ Neutre ☐ Pas de signal clair\nConfiance dans le signal : [haute/moyenne/basse] (basée sur le volume et la cohérence des données).', en:'[TICKER] — Institutional flow analysis:\n\n1. DARK POOL — Dark pool volume as % of total. Notable prints > $1M.\n2. BLOCK TRADES — Transactions > 10K shares. Direction.\n3. OPTIONS FLOW — P/C ratio, sweeps, OI concentration, max pain, GEX.\n4. RECENT 13F — Major hedge fund position changes.\n5. SYNTHESIS — Smart money bias: Bullish / Bearish / Neutral.', ar:'[TICKER] — تحليل التدفقات المؤسسية:\n\n1. Dark Pool\n2. Block Trades\n3. تدفقات الخيارات\n4. 13F الأخيرة\n5. التوليف' }
  },
  { num:50, cat:'crypto', numBg:'#fff7ed', numColor:'#ea580c', badgeBg:'#fff7ed', badgeColor:'#ea580c',
    title:{ fr:'Risque stablecoin', en:'Stablecoin risk', ar:'مخاطر العملة المستقرة' },
    badge:{ fr:'⚠️ Peg Risk', en:'⚠️ Peg Risk', ar:'⚠️ خطر الربط' },
    desc:{ fr:'Évalue le risque de depeg d\'un stablecoin : mécanisme de peg, réserves, audit, risque régulateur. L\'effondrement de UST/LUNA a prouvé que rien n\'est garanti.', en:'Evaluate a stablecoin\'s depeg risk: peg mechanism, reserves, audit, regulatory risk. The UST/LUNA collapse proved nothing is guaranteed.', ar:'قيّم خطر فقدان ربط عملة مستقرة: آلية الربط، الاحتياطيات، التدقيق، المخاطر التنظيمية. انهيار UST/LUNA أثبت أن لا شيء مضمون.' },
    code:{ fr:'[STABLECOIN] — Audit de risque :\n\n1. MÉCANISME DE PEG :\n☐ Fiat-backed (USDT, USDC) — réserves en $ ou T-bills\n☐ Crypto-backed (DAI) — surcollatéralisé en ETH/BTC\n☐ Algorithmique (ex: UST/LUNA ☠️) — aucune réserve, juste un algo\nRisque croissant : fiat < crypto-backed < algo\n\n2. RÉSERVES — Composition détaillée. % cash, % T-bills, % commercial paper, % autres. Y a-t-il des actifs risqués dans les réserves ?\n3. AUDIT — Audité par qui ? Fréquence ? Dernier rapport : [DATE]. Attestation (OK) ou audit complet (mieux) ?\n4. HISTORIQUE DE DEPEG — A-t-il déjà dépégé ? Combien de temps ? Amplitude ? Comment a-t-il été restauré ?\n5. CONCENTRATION — Le stablecoin est-il centralisé (blacklist, freeze possible) ? Qui contrôle le contrat ?\n6. RISQUE RÉGULATEUR — Législation en cours (EU MiCA, US stablecoin bill). L\'émetteur est-il conforme ?\n7. TAILLE & LIQUIDITÉ — Market cap : $[X]B. Volume 24h. Ratio market cap / réserves vérifiées.\n\nSCORE RISQUE : /10\n1-3 : Faible risque (fiat-backed, audité, gros market cap)\n4-6 : Risque modéré (réserves pas 100% transparentes)\n7-10 : Risque élevé (algo, petit, pas audité)\n\nRECOMMANDATION : Ne jamais garder >50% de son cash crypto dans un seul stablecoin. Diversifier entre 2-3.', en:'[STABLECOIN] — Risk audit:\n\n1. PEG MECHANISM — Fiat-backed / Crypto-backed / Algorithmic\n2. RESERVES — Detailed composition.\n3. AUDIT — By whom? Frequency?\n4. DEPEG HISTORY\n5. CONCENTRATION — Centralized? Blacklist possible?\n6. REGULATORY RISK\n7. SIZE & LIQUIDITY\n\nRISK SCORE: /10\nNever keep >50% of crypto cash in a single stablecoin.', ar:'[العملة المستقرة] — تدقيق المخاطر:\n\n1. آلية الربط\n2. الاحتياطيات\n3. التدقيق\n4. تاريخ فقدان الربط\n5. التركيز\n6. المخاطر التنظيمية\n7. الحجم والسيولة\n\nدرجة المخاطر: /10' }
  },
  { num:51, cat:'special', numBg:'#fef2f2', numColor:'#dc2626', badgeBg:'#eef2ff', badgeColor:'#4338ca',
    title:{ fr:'Devenir expert d\'un sujet', en:'Master any topic', ar:'إتقان أي موضوع' },
    badge:{ fr:'🎓 Learning', en:'🎓 Learning', ar:'🎓 تعلّم' },
    desc:{ fr:'Template universel pour devenir expert de n\'importe quel sujet — finance, tech, crypto, macro, ou tout autre domaine. Génère un cursus complet en 4 semaines avec des exercices pratiques. Le même framework utilisé dans nos séries éducatives.', en:'Universal template to become an expert on any topic — finance, tech, crypto, macro, or any other field. Generates a complete 4-week curriculum with practical exercises. The same framework used in our educational series.', ar:'قالب عالمي لتصبح خبيراً في أي موضوع — مالية، تكنولوجيا، كريبتو، ماكرو، أو أي مجال آخر. يولّد منهجاً كاملاً في 4 أسابيع مع تمارين عملية. نفس الإطار المستخدم في سلاسلنا التعليمية.' },
    code:{ fr:'Je veux devenir expert en [SUJET] en partant de [MON NIVEAU : débutant / intermédiaire / avancé].\n\nCrée un PLAN DE MAÎTRISE en 4 semaines structuré ainsi :\n\n📅 SEMAINE 1 — FONDATIONS\n- 5 concepts fondamentaux à maîtriser (avec définition en 1 phrase)\n- 3 ressources incontournables (livre, article, vidéo) avec liens\n- Exercice pratique quotidien (15 min/jour)\n- Mini-projet de fin de semaine\n\n📅 SEMAINE 2 — APPROFONDISSEMENT\n- 5 concepts intermédiaires qui connectent les fondations\n- Méthode d\'analyse : framework en 5 étapes applicable à tout cas\n- Exercice : analyser un cas réel avec le framework\n- Erreurs courantes à ce niveau + comment les éviter\n\n📅 SEMAINE 3 — APPLICATION\n- 3 techniques avancées utilisées par les pros\n- Étude de cas détaillée : décortiquer un exemple réel (succès ET échec)\n- Exercice : construire son propre outil/checklist/dashboard\n- Sources d\'information des experts (newsletters, comptes X, podcasts)\n\n📅 SEMAINE 4 — MAÎTRISE\n- Interconnexions avec d\'autres domaines\n- Construire sa propre méthodologie\n- Exercice final : enseigner le sujet à quelqu\'un d\'autre (meilleur test de compréhension)\n- Plan de veille permanente : comment rester à jour en 10 min/jour\n\n🎯 QUIZ DE VALIDATION — 10 questions (facile → expert) pour tester ma compréhension. Note sur 10.\n\n📊 MÉTRIQUES DE PROGRESSION — Comment savoir que je progresse ? 3 indicateurs concrets.\n\nTon : passionné et structuré. Si un concept est complexe, utilise une analogie du quotidien.', en:'I want to become an expert in [TOPIC] starting from [MY LEVEL: beginner / intermediate / advanced].\n\nCreate a 4-WEEK MASTERY PLAN structured as follows:\n\n📅 WEEK 1 — FOUNDATIONS\n- 5 fundamental concepts to master (with 1-sentence definition)\n- 3 essential resources (book, article, video) with links\n- Daily practical exercise (15 min/day)\n- End-of-week mini-project\n\n📅 WEEK 2 — DEEPENING\n- 5 intermediate concepts that connect the foundations\n- Analysis method: 5-step framework applicable to any case\n- Exercise: analyze a real case with the framework\n- Common mistakes at this level + how to avoid them\n\n📅 WEEK 3 — APPLICATION\n- 3 advanced techniques used by pros\n- Detailed case study: dissect a real example (success AND failure)\n- Exercise: build your own tool/checklist/dashboard\n- Expert information sources (newsletters, X accounts, podcasts)\n\n📅 WEEK 4 — MASTERY\n- Interconnections with other domains\n- Build your own methodology\n- Final exercise: teach the topic to someone else (best comprehension test)\n- Permanent monitoring plan: how to stay updated in 10 min/day\n\n🎯 VALIDATION QUIZ — 10 questions (easy → expert) to test my understanding. Score out of 10.\n\n📊 PROGRESS METRICS — How do I know I\'m progressing? 3 concrete indicators.\n\nTone: passionate and structured. If a concept is complex, use a daily-life analogy.', ar:'أريد أن أصبح خبيراً في [الموضوع] انطلاقاً من [مستواي: مبتدئ / متوسط / متقدم].\n\nأنشئ خطة إتقان في 4 أسابيع:\n\n📅 الأسبوع 1 — الأسس\n- 5 مفاهيم أساسية (مع تعريف بجملة واحدة)\n- 3 موارد لا غنى عنها (كتاب، مقال، فيديو) مع روابط\n- تمرين عملي يومي (15 دقيقة/يوم)\n- مشروع صغير نهاية الأسبوع\n\n📅 الأسبوع 2 — التعمق\n- 5 مفاهيم وسيطة تربط الأسس\n- إطار تحليل من 5 خطوات\n- تمرين: تحليل حالة حقيقية\n- أخطاء شائعة في هذا المستوى\n\n📅 الأسبوع 3 — التطبيق\n- 3 تقنيات متقدمة يستخدمها المحترفون\n- دراسة حالة مفصلة (نجاح وفشل)\n- تمرين: بناء أداتك الخاصة\n- مصادر المعلومات للخبراء\n\n📅 الأسبوع 4 — الإتقان\n- الترابطات مع مجالات أخرى\n- بناء منهجيتك الخاصة\n- تمرين نهائي: علّم الموضوع لشخص آخر\n- خطة متابعة دائمة: كيف تبقى محدثاً في 10 دقائق/يوم\n\n🎯 اختبار تحقق — 10 أسئلة. درجة من 10.\n📊 مؤشرات التقدم — 3 مؤشرات ملموسة.' }
  }
];
